"""Anlık bildirim (push): her site bildirimi, bildirimleri açmış cihazlara da gönderilir.

İki kanal var, ikisi de isteğe bağlıdır:
  * WEB: tarayıcı ve ana ekrana eklenen web uygulaması (Web Push, VAPID). `pip install pywebpush==2.5.0` gerekir;
    anahtarlar ilk kullanımda instance/vapid_ozel.pem dosyasına üretilir. Tarayıcılar bunu yalnızca HTTPS adreslerde
    (ya da bilgisayarın kendisindeki localhost'ta) izin verir.
  * FCM: mobil/ klasöründeki Android uygulaması (Firebase Cloud Messaging). instance/firebase.json dosyasına Firebase
    hizmet hesabı anahtarı konunca açılır (adımlar mobil/BENIOKU.md'de).
Gönderim, veritabanı işlemi kaydedildikten sonra arka planda yapılır; istek beklemez. Geçersizleşen abonelikler silinir.

Tasarım: GoF **Adapter** — iki kanalın dış API'leri birbirinden farklıdır (pywebpush'ın webpush() fonksiyonu, Firebase
HTTP v1). Her biri AnlikKanal arayüzüne uyarlanır; forumun geri kalanı yalnızca `etkin / abonelik_coz / gonder`
bilir. Kanallar KANALLAR sözlüğünde durur (**Strategy**); yeni kanal yeni bir sınıftır, testler sözlüğe sahte bir
kanal koyar.
"""
import base64
import importlib.util
import json
import logging
import os
import threading
import time
import urllib.error
import urllib.parse
import urllib.request
from abc import ABC, abstractmethod

from . import ayarlar, zaman
from .hatalar import KuralHatasi

log = logging.getLogger(__name__)
_kilit = threading.Lock()
# Tarayıcıların Web Push servisleri. Sunucu bu adrese istek attığı için yalnızca bunlardan biri kabul edilir (SSRF).
PUSH_SERVISLERI = ("fcm.googleapis.com", "android.googleapis.com", "push.services.mozilla.com",
                   "notify.windows.com", "push.apple.com")


def push_adresi_gecerli_mi(adres):
    parca = urllib.parse.urlsplit(adres or "")
    ad = (parca.hostname or "").lower()
    return parca.scheme == "https" and parca.port in (None, 443) and \
        any(ad == s or ad.endswith("." + s) for s in PUSH_SERVISLERI)


def _instance(db):
    return os.path.dirname(os.path.abspath(db.yol))


def _b64(veri):
    return base64.urlsafe_b64encode(veri).rstrip(b"=").decode()


def _cryptography_var():
    return importlib.util.find_spec("cryptography") is not None


# --- Hedef arayüz ---

class AnlikKanal(ABC):
    """Bir anlık bildirim kanalı. `klasor`: sunucunun instance klasörü (anahtar dosyaları burada)."""
    kod = ""

    @abstractmethod
    def etkin(self, klasor):
        """Kanal bu sunucuda kullanılabilir mi (kütüphane ve anahtarlar hazır mı)?"""

    @abstractmethod
    def abonelik_coz(self, veri):
        """İstemcinin gönderdiği abonelik verisini doğrular. Döner: (adres, anahtarlar_json ya da None)."""

    @abstractmethod
    def gonder(self, klasor, abonelik, yuk):
        """Bildirimi gönderir. Döner: abonelik hâlâ geçerli mi (False ise silinir). Ağ hatasında istisna fırlatır."""


class WebPushKanali(AnlikKanal):
    """pywebpush kütüphanesini AnlikKanal arayüzüne uyarlar."""
    kod = "WEB"

    def etkin(self, klasor):
        return importlib.util.find_spec("pywebpush") is not None

    def vapid_yolu(self, klasor):
        return os.path.join(klasor, "vapid_ozel.pem")

    def acik_anahtar(self, klasor):
        """Tarayıcının abone olurken istediği sunucu anahtarı (applicationServerKey). Gerekirse anahtar çiftini üretir."""
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric import ec
        yol = self.vapid_yolu(klasor)
        with _kilit:
            if not os.path.exists(yol):
                ozel = ec.generate_private_key(ec.SECP256R1())
                with os.fdopen(os.open(yol, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "wb") as f:
                    f.write(ozel.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8,
                                               serialization.NoEncryption()))
            with open(yol, "rb") as f:
                ozel = serialization.load_pem_private_key(f.read(), password=None)
        return _b64(ozel.public_key().public_bytes(serialization.Encoding.X962,
                                                   serialization.PublicFormat.UncompressedPoint))

    def abonelik_coz(self, veri):
        adres = (veri or {}).get("endpoint", "")
        anahtarlar = (veri or {}).get("keys") or {}
        if not push_adresi_gecerli_mi(adres) or not anahtarlar.get("p256dh") or not anahtarlar.get("auth"):
            raise KuralHatasi("Geçersiz tarayıcı aboneliği.")
        return adres, json.dumps({"p256dh": anahtarlar["p256dh"], "auth": anahtarlar["auth"]})

    def gonder(self, klasor, abonelik, yuk):
        from pywebpush import WebPushException, webpush
        try:
            webpush({"endpoint": abonelik["adres"], "keys": json.loads(abonelik["anahtarlar"])}, data=yuk,
                    vapid_private_key=self.vapid_yolu(klasor), timeout=10, ttl=86400,
                    vapid_claims={"sub": os.environ.get("FORUM_ANLIK_ILETISIM", "mailto:agora@example.com")})
            return True
        except WebPushException as e:
            if e.response is not None and e.response.status_code in (404, 410):
                return False
            raise


class FcmKanali(AnlikKanal):
    """Firebase Cloud Messaging HTTP v1 uç noktasını (hizmet hesabıyla imzalı JWT → OAuth) arayüze uyarlar."""
    kod = "FCM"

    def __init__(self):
        self._erisim = {"anahtar": None, "bitis": 0}          # kısa ömürlü OAuth anahtarının önbelleği

    def hesap(self, klasor):
        yol = os.path.join(klasor, "firebase.json")
        if not os.path.exists(yol):
            return None
        with open(yol, encoding="utf-8") as f:
            return json.load(f)

    def etkin(self, klasor):
        return self.hesap(klasor) is not None and _cryptography_var()     # JWT imzası için cryptography gerekir

    def abonelik_coz(self, veri):
        adres = str((veri or {}).get("token", ""))
        if not 20 <= len(adres) <= 4096:
            raise KuralHatasi("Geçersiz cihaz anahtarı.")
        return adres, None

    def _erisim_anahtari(self, hesap):
        """Hizmet hesabıyla imzalanmış JWT karşılığında kısa ömürlü OAuth erişim anahtarı alır (saatlik önbellek)."""
        with _kilit:
            if self._erisim["anahtar"] and self._erisim["bitis"] > time.time() + 60:
                return self._erisim["anahtar"]
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        an = int(time.time())
        govde = {"iss": hesap["client_email"], "scope": "https://www.googleapis.com/auth/firebase.messaging",
                 "aud": hesap.get("token_uri", "https://oauth2.googleapis.com/token"), "iat": an, "exp": an + 3600}
        imzalanacak = (_b64(json.dumps({"alg": "RS256", "typ": "JWT"}).encode()) + "." +
                       _b64(json.dumps(govde).encode()))
        anahtar = serialization.load_pem_private_key(hesap["private_key"].encode(), password=None)
        jwt = imzalanacak + "." + _b64(anahtar.sign(imzalanacak.encode(), padding.PKCS1v15(), hashes.SHA256()))
        istek = urllib.request.Request(govde["aud"], data=urllib.parse.urlencode(
            {"grant_type": "urn:ietf:params:oauth:grant-type:jwt-bearer", "assertion": jwt}).encode())
        with urllib.request.urlopen(istek, timeout=10) as y:
            cevap = json.load(y)
        with _kilit:
            self._erisim.update(anahtar=cevap["access_token"], bitis=time.time() + int(cevap.get("expires_in", 3600)))
        return cevap["access_token"]

    def gonder(self, klasor, abonelik, yuk):
        hesap = self.hesap(klasor)
        v = json.loads(yuk)
        mesaj = {"message": {"token": abonelik["adres"], "notification": {"title": v["baslik"], "body": v["metin"]},
                             "data": {"url": v["url"]}, "android": {"priority": "high"}}}
        istek = urllib.request.Request(
            f"https://fcm.googleapis.com/v1/projects/{hesap['project_id']}/messages:send",
            data=json.dumps(mesaj).encode(), headers={"Authorization": f"Bearer {self._erisim_anahtari(hesap)}",
                                                      "Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(istek, timeout=10):
                return True
        except urllib.error.HTTPError as e:
            if e.code == 404 or (e.code == 400 and b"UNREGISTERED" in e.read()):
                return False                        # uygulama silinmiş ya da anahtar yenilenmiş
            raise


KANALLAR = {k.kod: k for k in (WebPushKanali(), FcmKanali())}


def _kanal(tur):
    kanal = KANALLAR.get(tur)
    if kanal is None:
        raise KuralHatasi("Geçersiz bildirim kanalı.")
    return kanal


# --- Kanalların durumu ---

def vapid_acik_anahtar(db):
    kanal = KANALLAR["WEB"]
    return kanal.acik_anahtar(_instance(db)) if kanal.etkin(_instance(db)) else None


def durum(db):
    return {kod.lower(): kanal.etkin(_instance(db)) for kod, kanal in KANALLAR.items()}


# --- Abonelikler ---

def abone_ol(db, kullanici, tur, veri, cihaz=""):
    kanal = _kanal(tur)
    if not kanal.etkin(_instance(db)):
        # Kapalı kanala abonelik alınırsa her bildirimde gönderim hatası günlüğe düşer, abonelik hiç işe yaramaz.
        raise KuralHatasi("Bu bildirim kanalı sunucuda kurulu değil.")
    adres, anahtar_json = kanal.abonelik_coz(veri)
    db.execute(
        """INSERT INTO anlik_abonelikler (kullanici_id, tur, adres, anahtarlar, cihaz, olusturma) VALUES (?, ?, ?, ?, ?, ?)
           ON CONFLICT(adres) DO UPDATE SET kullanici_id = excluded.kullanici_id, anahtarlar = excluded.anahtarlar,
           cihaz = excluded.cihaz""",
        (kullanici["id"], tur, adres, anahtar_json, (cihaz or "")[:80], zaman.simdi_metin()))


def abonelikten_cik(db, kullanici, adres):
    db.execute("DELETE FROM anlik_abonelikler WHERE kullanici_id = ? AND adres = ?", (kullanici["id"], adres or ""))


def abonelikler(db, kullanici_id):
    return db.execute("SELECT * FROM anlik_abonelikler WHERE kullanici_id = ? ORDER BY id DESC",
                      (kullanici_id,)).fetchall()


# --- Gönderim ---

def kuyruga_ekle(db, kullanici_id, metin, baglanti):
    """bildirimler.gonder çağırır. İşlem kaydedilince (commit) arka planda gönderilir; geri alınırsa gönderilmez."""
    hedefler = [dict(r) for r in db.execute("SELECT * FROM anlik_abonelikler WHERE kullanici_id = ?", (kullanici_id,))]
    if not hedefler:
        return
    if db.anlik_kuyrugu is None:
        db.anlik_kuyrugu = []
        yol = db.yol

        def gonder_hepsi():
            isler, db.anlik_kuyrugu = db.anlik_kuyrugu, None
            threading.Thread(target=_gonder, args=(yol, isler), daemon=True).start()
        db.commit_sonrasi.append(gonder_hepsi)
    yuk = json.dumps({"baslik": ayarlar.SITE_ADI, "metin": metin[:240], "url": baglanti or "/bildirimler"},
                     ensure_ascii=False)
    db.anlik_kuyrugu.extend((h, yuk) for h in hedefler)


def _gonder(yol, isler):
    from . import veritabani
    db = veritabani.baglan(yol)
    klasor = _instance(db)
    try:
        silinecek = []
        for abonelik, yuk in isler:
            kanal = KANALLAR.get(abonelik["tur"])
            if kanal is None or not kanal.etkin(klasor):
                continue                            # kanal sonradan kapatıldı: abonelik kalır, gönderim denenmez
            try:
                gecerli = kanal.gonder(klasor, abonelik, yuk)
            except Exception:                       # ağ hatası: abonelik kalır, bir sonraki bildirimde tekrar denenir
                log.exception("Anlık bildirim gönderilemedi")
                continue
            if not gecerli:
                silinecek.append(abonelik["id"])
        for i in silinecek:
            db.execute("DELETE FROM anlik_abonelikler WHERE id = ?", (i,))
        db.commit()
    finally:
        db.close()

"""Bildirimler: üyeye kendisini ilgilendiren olayları haber verir."""
from . import zaman


def gonder(db, kullanici_id, metin, baglanti):
    if kullanici_id is None:
        return
    k = db.execute("SELECT yz_mi FROM kullanicilar WHERE id = ?", (kullanici_id,)).fetchone()
    if not k or k["yz_mi"]:
        return
    db.execute("INSERT INTO bildirimler (kullanici_id, metin, baglanti, olusturma) VALUES (?, ?, ?, ?)",
               (kullanici_id, metin, baglanti, zaman.simdi_metin()))
    from . import anlik
    anlik.kuyruga_ekle(db, kullanici_id, metin, baglanti)


def coklu_gonder(db, kullanici_idleri, metin, baglanti, haric=None):
    for kid in set(kullanici_idleri) - {haric}:
        gonder(db, kid, metin, baglanti)


def okunmamis_sayisi(db, kullanici_id):
    return db.execute("SELECT COUNT(*) FROM bildirimler WHERE kullanici_id = ? AND okundu = 0",
                      (kullanici_id,)).fetchone()[0]


def liste(db, kullanici_id, sayfa=1, boy=20):
    toplam = db.execute("SELECT COUNT(*) FROM bildirimler WHERE kullanici_id = ?", (kullanici_id,)).fetchone()[0]
    satirlar = db.execute("SELECT * FROM bildirimler WHERE kullanici_id = ? ORDER BY id DESC LIMIT ? OFFSET ?",
                          (kullanici_id, boy, (sayfa - 1) * boy)).fetchall()
    return satirlar, toplam


def hepsini_okundu_yap(db, kullanici_id):
    db.execute("UPDATE bildirimler SET okundu = 1 WHERE kullanici_id = ? AND okundu = 0", (kullanici_id,))


def okundu_yap(db, kullanici_id, bildirim_id):
    r = db.execute("SELECT baglanti FROM bildirimler WHERE id = ? AND kullanici_id = ?",
                   (bildirim_id, kullanici_id)).fetchone()
    if r:
        db.execute("UPDATE bildirimler SET okundu = 1 WHERE id = ?", (bildirim_id,))
    return r["baglanti"] if r else None


def konu_katilimcilari(db, konu_id):
    """Konuya mesaj yazmış ya da konuyu açmış kişiler."""
    idler = {r["yazar_id"] for r in db.execute(
        "SELECT DISTINCT yazar_id FROM mesajlar WHERE konu_id = ? AND yazar_id IS NOT NULL", (konu_id,))}
    sahip = db.execute("SELECT sahip_id FROM konular WHERE id = ?", (konu_id,)).fetchone()
    if sahip:
        idler.add(sahip["sahip_id"])
    return idler


def takipciler(db, kullanici_id):
    return [r["takip_eden_id"] for r in
            db.execute("SELECT takip_eden_id FROM takipler WHERE takip_edilen_id = ?", (kullanici_id,))]

"""Dağıtık defter (distributed ledger).

Forumda olan her önemli olay (tasarı, mesaj özeti, oy taahhüdü, sonuç, karar...) bir blok olarak
hash zincirine eklenir. Zincir birden fazla düğümde (A, B, C düğümleri) ayrı dosyalarda tutulur:

  * Her blok bir öncekinin hash'ini içerir: bir blok değiştirilirse sonraki bütün bağlar kopar.
  * Düğümler çoğunlukla uzlaşır: 3 düğümden 2'si aynı zincirdeyse o zincir geçerlidir.
  * Bozulan bir düğüm tespit edilir ve sağlam düğümlerden onarılır.
  * Veritabanı defterle karşılaştırılır: silinen ya da gizlice değiştirilen mesaj/oy yakalanır.

Kişisel veri deftere yazılmaz: mesajların sadece SHA-256 özeti, oyların sadece taahhüdü yazılır.

Tasarım desenleri:
  * **Repository** — bir düğümün blokları `DugumDeposu` arayüzünün arkasındadır. Üretimde `SqliteDugumDeposu`,
    testlerde `BellekDugumDeposu` kullanılır.
  * **Observer** — defter, veritabanının "işlem kaydedildi" olayına abone olur (`veritabani.commit_aboneligi`).
    Veritabanı katmanı defteri tanımaz.

Defter işlevlerinin `kaynak` parametresi bir klasör yolu (üretim) ya da `DugumDeposu` listesidir (test).
"""
import hashlib
import json
import logging
import os
import random
import sqlite3
import threading
import time
import weakref
from abc import ABC, abstractmethod
from collections import Counter
from contextlib import contextmanager

from . import ayarlar, veritabani, zaman

_KILIT = threading.RLock()     # yazma, onarım ve doğrulama önbelleği aynı kilitle korunur
log = logging.getLogger(__name__)
BASLANGIC_HASH = "0" * 64
# Deftere yazılabilen blok türleri (tek doğruluk kaynağı: defter sayfasındaki süzgeç de buradan gelir).
BLOK_TURLERI = ("KONU", "KONU_DUZENLEME", "KONU_DURUM", "MESAJ", "MESAJ_DUZENLEME", "GIZLEME", "TEKLIF", "OY", "SONUC",
                "KARAR", "DEVIR", "DEVIR_GERI", "UYE", "UZMANLIK", "KATEGORI", "YONETIM")
BASLANGIC_ZAMANI = "2026-01-01 00:00:00"


def ozet(metin):
    return hashlib.sha256(metin.encode("utf-8")).hexdigest()


def blok_hash(no, zaman_, tur, veri, onceki):
    return ozet(f"{no}|{zaman_}|{tur}|{veri}|{onceki}")


def ekle(db, tur, veri):
    """Kaydı işlem kuyruğuna ekler; veritabanı commit edilince düğümlere yazılır."""
    if tur not in BLOK_TURLERI:
        raise ValueError(f"Bilinmeyen defter bloğu türü: {tur}")
    if db.defter_klasoru:
        db.defter_kuyrugu.append((tur, json.dumps(veri, ensure_ascii=False, sort_keys=True), zaman.simdi_metin()))


@veritabani.commit_aboneligi
def _islem_kaydedildi(db):
    """Observer: işlem kaydedilince kuyruktaki blokları düğümlere yazar. Geri alınan işlemin kuyruğu bağlantı
    tarafından zaten boşaltılmıştır (rollback), deftere girmez."""
    if not (db.defter_kuyrugu and db.defter_klasoru):
        return
    kuyruk, db.defter_kuyrugu = db.defter_kuyrugu, []
    try:
        dugumlere_yaz(db.defter_klasoru, kuyruk)
    except Exception:
        # Veri artık kalıcı; istek hata vermez (kullanıcı tekrar denerse çift kayıt oluşurdu). Eksik bloğu
        # tutarlılık denetimi gösterir.
        log.exception("Kayıt defterine %d blok yazılamadı", len(kuyruk))


# --- Düğüm depoları (Repository) ---

def baslangic_blogu():
    """Bütün düğümlerde birebir aynı olan 0 numaralı blok (zamanı sabittir)."""
    veri = json.dumps({"ad": ayarlar.SITE_ADI + " dağıtık defteri", "dugumler": ayarlar.DEFTER_DUGUMLERI},
                      ensure_ascii=False)
    return {"no": 0, "zaman": BASLANGIC_ZAMANI, "tur": "BASLANGIC", "veri": veri, "onceki": BASLANGIC_HASH,
            "hash": blok_hash(0, BASLANGIC_ZAMANI, "BASLANGIC", veri, BASLANGIC_HASH)}


class YinelenenBlok(Exception):
    """Eklenmek istenen numarada zaten bir blok var. Bütün depo gerçeklemeleri aynı hatayı verir (Liskov)."""


class DugumDeposu(ABC):
    """Bir düğümün blok deposu. Boş bir depo ilk okunduğunda başlangıç bloğuyla açılır.

    Soyut olan yalnızca dört temel işlemdir (oku, ekle, yeniden kur, sürüm). Sorgu işlemlerinin (son blok, sayfa,
    türe göre süzme, arama) doğru ama yavaş varsayılanları burada bütün zincirden hesaplanır; SQLite deposu bunları
    SQL ile hızlı yapar. İki gerçekleme aynı sonucu verir (testlerde karşılaştırılır)."""

    def __init__(self, ad):
        self.ad = ad

    @abstractmethod
    def bloklar(self):
        """Bütün bloklar, numara sırasıyla (sözlük listesi)."""

    @abstractmethod
    def ekle(self, yeni):
        """Blokları zincirin sonuna ekler; hepsi ya eklenir ya hiçbiri. Aynı numaralı bir blok zaten varsa YinelenenBlok."""

    @abstractmethod
    def yeniden_kur(self, zincir):
        """Depodaki zinciri verilen zincirle değiştirir (onarım)."""

    @abstractmethod
    def veri_degistir(self, no, veri):
        """Bir bloğun verisini hash'ine dokunmadan değiştirir. SADECE kurcalama gösterimi (boz_demo) içindir."""

    @abstractmethod
    def surum(self):
        """Depo her değiştiğinde (kim değiştirirse değiştirsin) değişen bir değer. Doğrulama önbelleği buna bağlıdır."""

    def son_blok(self):
        return self.bloklar()[-1]

    def blok(self, no):
        return next((b for b in self.bloklar() if b["no"] == no), None)

    def sayfa(self, tur, atla, boy):
        """En yeniden eskiye (tur verilirse yalnız o türden) bloklar: (liste, toplam). atla ≥ 0 olmalı."""
        liste = [b for b in reversed(self.bloklar()) if tur is None or b["tur"] == tur]
        return liste[atla:atla + boy], len(liste)

    def turdeki(self, turler):
        return [b for b in self.bloklar() if b["tur"] in turler]

    def bul(self, anahtar):
        """Numarası anahtar olan ya da hash'i anahtarla başlayan ilk blok."""
        return next((b for b in self.bloklar() if b["hash"].startswith(anahtar) or str(b["no"]) == anahtar), None)


_EKLE = "INSERT INTO bloklar VALUES (:no, :zaman, :tur, :veri, :onceki, :hash)"


class SqliteDugumDeposu(DugumDeposu):
    """Üretim deposu: her düğüm klasörde ayrı bir SQLite dosyasıdır (A.db, B.db, C.db)."""

    def __init__(self, klasor, ad):
        super().__init__(ad)
        self.yol = os.path.join(klasor, f"{ad}.db")

    def _baglan(self):
        os.makedirs(os.path.dirname(self.yol), exist_ok=True)
        c = sqlite3.connect(self.yol, timeout=10)
        c.row_factory = sqlite3.Row
        c.execute("""CREATE TABLE IF NOT EXISTS bloklar (
                       no INTEGER PRIMARY KEY, zaman TEXT NOT NULL, tur TEXT NOT NULL,
                       veri TEXT NOT NULL, onceki TEXT NOT NULL, hash TEXT NOT NULL)""")
        if c.execute("SELECT 1 FROM bloklar LIMIT 1").fetchone() is None:     # COUNT(*) tüm tabloyu tarar
            c.execute(_EKLE, baslangic_blogu())
            c.commit()
        return c

    def _oku(self, sql, parametre=()):
        c = self._baglan()
        try:
            return [dict(r) for r in c.execute(sql, parametre)]
        finally:
            c.close()

    def _yaz(self, sql_ler):
        c = self._baglan()
        try:
            for sql, parametre in sql_ler:
                (c.executemany if isinstance(parametre, list) else c.execute)(sql, parametre)
            c.commit()
        finally:
            c.close()

    def bloklar(self):
        return self._oku("SELECT * FROM bloklar ORDER BY no")

    def ekle(self, yeni):
        try:
            self._yaz([(_EKLE, list(yeni))])
        except sqlite3.IntegrityError as hata:              # birincil anahtar (no) çakıştı; işlem geri alındı
            raise YinelenenBlok("Bu numarada bir blok zaten var.") from hata

    def yeniden_kur(self, zincir):
        self._yaz([("DELETE FROM bloklar", ()), (_EKLE, list(zincir))])

    def veri_degistir(self, no, veri):
        self._yaz([("UPDATE bloklar SET veri = ? WHERE no = ?", (veri, no))])

    def surum(self):
        """Depo sürümü: SQLite başlığındaki değişiklik sayacı, dosya kimliği (inode), boyu, değişiklik ve durum değişim
        zamanları (mtime, ctime), varsa WAL dosyasının boyu ve zamanı. Ham bayt değişikliği sayacı artırmaz; mtime geri
        alınabildiği için ctime de tutulur. (Windows'ta ctime oluşturma zamanıdır; oradaki güvence önbellek ömrüdür,
        bkz. _dugum_durumu.) Dosya yoksa None."""
        try:
            with open(self.yol, "rb") as f:
                baslik = f.read(28)
            bilgi = os.stat(self.yol)
        except FileNotFoundError:
            return None
        try:
            wal = os.stat(self.yol + "-wal")
            wal = (wal.st_size, wal.st_mtime_ns, wal.st_ctime_ns)
        except FileNotFoundError:
            wal = None
        return baslik[24:28], bilgi.st_ino, bilgi.st_size, bilgi.st_mtime_ns, bilgi.st_ctime_ns, wal

    def son_blok(self):
        return self._oku("SELECT * FROM bloklar ORDER BY no DESC LIMIT 1")[0]

    def blok(self, no):
        r = self._oku("SELECT * FROM bloklar WHERE no = ?", (no,))
        return r[0] if r else None

    def sayfa(self, tur, atla, boy):
        kosul = "WHERE ? IS NULL OR tur = ?"
        c = self._baglan()
        try:       # liste ve toplam aynı bağlantıdan, arada yazma araya girmesin
            toplam = c.execute(f"SELECT COUNT(*) FROM bloklar {kosul}", (tur, tur)).fetchone()[0]
            if atla >= toplam:
                return [], toplam
            liste = [dict(r) for r in c.execute(f"SELECT * FROM bloklar {kosul} ORDER BY no DESC LIMIT ? OFFSET ?",
                                                (tur, tur, boy, atla))]
            return liste, toplam
        finally:
            c.close()

    def turdeki(self, turler):
        return self._oku(f"SELECT * FROM bloklar WHERE tur IN ({','.join('?' * len(turler))}) ORDER BY no",
                         tuple(turler))

    def bul(self, anahtar):
        r = self._oku("SELECT * FROM bloklar WHERE substr(hash, 1, length(?)) = ? OR CAST(no AS TEXT) = ? "
                      "ORDER BY no LIMIT 1", (anahtar, anahtar, anahtar))
        return r[0] if r else None


class BellekDugumDeposu(DugumDeposu):
    """Test deposu (sahte depo): bloklar bellekte bir listede durur; disk ya da SQLite gerekmez."""

    def __init__(self, ad):
        super().__init__(ad)
        self._bloklar = []
        self._surum = 0

    def _degisti(self):
        self._surum += 1

    def _ac(self):
        if not self._bloklar:
            self._bloklar.append(baslangic_blogu())
            self._degisti()

    def bloklar(self):
        self._ac()
        return [dict(b) for b in self._bloklar]

    def ekle(self, yeni):
        self._ac()
        var = {b["no"] for b in self._bloklar}
        yeni = [dict(b) for b in yeni]
        if any(b["no"] in var for b in yeni) or len({b["no"] for b in yeni}) != len(yeni):
            raise YinelenenBlok("Bu numarada bir blok zaten var.")   # SQLite deposundaki birincil anahtarın karşılığı
        self._bloklar.extend(yeni)
        self._degisti()

    def yeniden_kur(self, zincir):
        self._bloklar = [dict(b) for b in zincir]
        self._degisti()

    def veri_degistir(self, no, veri):
        self._ac()
        for b in self._bloklar:
            if b["no"] == no:
                b["veri"] = veri
                self._degisti()

    def surum(self):
        return self._surum

    def son_blok(self):
        self._ac()
        return dict(self._bloklar[-1])


def bellek_depolari():
    """Her düğüm için boş bir bellek deposu (testler için)."""
    return [BellekDugumDeposu(ad) for ad in ayarlar.DEFTER_DUGUMLERI]


_SQLITE_DEPOLARI = {}     # klasör → {ad: depo}; aynı nesneler kullanılır ki doğrulama önbelleği korunsun


def _depolar(kaynak):
    """kaynak: klasör yolu → SQLite depoları; DugumDeposu listesi ya da {ad: depo} → olduğu gibi. Döner: {ad: depo}."""
    if isinstance(kaynak, (str, os.PathLike)):
        klasor = os.path.abspath(kaynak)
        if klasor not in _SQLITE_DEPOLARI:
            _SQLITE_DEPOLARI[klasor] = {ad: SqliteDugumDeposu(klasor, ad) for ad in ayarlar.DEFTER_DUGUMLERI}
        return _SQLITE_DEPOLARI[klasor]
    if isinstance(kaynak, dict):
        return kaynak
    return {d.ad: d for d in kaynak}


# --- Doğrulama ve uzlaşma ---

def zinciri_dogrula(bloklar):
    """(geçerli_mi, ilk bozuk blok no)."""
    onceki = BASLANGIC_HASH
    for i, b in enumerate(bloklar):
        if b["no"] != i or b["onceki"] != onceki or b["hash"] != blok_hash(b["no"], b["zaman"], b["tur"],
                                                                         b["veri"], b["onceki"]):
            return False, b["no"]
        onceki = b["hash"]
    return True, None


# Düğüm başına son tam doğrulamanın sonucu, düğümün o anki sürümüyle birlikte. Sürüm değişmedikçe zincir yeniden
# okunup hash'lenmez. Her yazmada üç zincirin tam doğrulaması 50.000 blokta yarım saniye sürer (bkz.
# olcum/gecikme_olcumu.py). Defterin kendi eklemeleri önbelleği günceller; dosyayı dışarıdan değiştirmek sürümü
# değiştirir ve bir sonraki okumada tam doğrulama yapılır. Sürümün göremeyeceği değişikliklere (disk bozulması;
# Windows'ta zamanı geri alınmış ham bayt değişikliği) karşı iki güvence: bir sonuç en fazla DOGRULAMA_OMRU saniye
# kullanılır ve "denetle" istekleri (tam=True) önbelleği hiç kullanmaz.
_DOGRULAMA = weakref.WeakKeyDictionary()
DOGRULAMA_OMRU = 600
_saat = time.monotonic      # testler değiştirir


def _dugum_durumu(depo, tam=False):
    with _KILIT:
        surum = depo.surum()
        d = _DOGRULAMA.get(depo)
        if tam or d is None or d["surum"] != surum or _saat() - d["dogrulama"] > DOGRULAMA_OMRU:
            z = depo.bloklar()
            gecerli, bozuk = zinciri_dogrula(z)
            d = {"surum": surum, "uzunluk": len(z), "bas": z[-1]["hash"] if z else None, "gecerli": gecerli,
                 "bozuk_blok": bozuk, "dogrulama": _saat()}
            _DOGRULAMA[depo] = d
        return dict(d)


def _eklendi(depo, yeni):
    """Defterin kendi eklemesinden sonra: eklenen bloklar zaten doğru hesaplandı, önbellek ilerletilir."""
    d = _DOGRULAMA.get(depo)
    if d is not None:
        d.update(surum=depo.surum(), uzunluk=yeni[-1]["no"] + 1, bas=yeni[-1]["hash"])


def _uzlasma(kaynak, tam=False):
    """Geçerli zincirlerin baş hash'lerine göre çoğunluk: (çoğunluk baş hash'i ya da None, okunacak depo ya da None,
    düğüm durumları). Okunacak depo, en çok düğümün paylaştığı geçerli zincirdeki ilk düğümdür. Düğümler kilit altında
    okunur: bir yazmanın ortasında okunan düğümler yanlışlıkla "ayrışmış" görünmesin. tam=True: önbellek kullanılmaz."""
    depolar = _depolar(kaynak)
    durumlar = []
    with _KILIT:
        for ad, depo in depolar.items():
            d = _dugum_durumu(depo, tam)
            durumlar.append({"ad": ad, "uzunluk": d["uzunluk"], "bas": d["bas"], "gecerli": d["gecerli"],
                             "bozuk_blok": d["bozuk_blok"]})
    sayac = Counter(d["bas"] for d in durumlar if d["gecerli"])
    if not sayac:
        for d in durumlar:
            d["durum"] = "BOZUK"
        return None, None, durumlar
    bas, oy = sayac.most_common(1)[0]
    cogunluk = oy > len(depolar) // 2
    kaynak_adi = next(d["ad"] for d in durumlar if d["gecerli"] and d["bas"] == bas)
    for d in durumlar:
        if not d["gecerli"]:
            d["durum"] = "BOZUK"
        elif d["bas"] == bas:
            d["durum"] = "UYUMLU" if cogunluk else "AZINLIKTA"
        else:
            d["durum"] = "AYRISMIS"
    return (bas if cogunluk else None), depolar[kaynak_adi], durumlar


@contextmanager
def _surecler_arasi_kilit(depolar):
    """Birden çok sunucu süreci (ör. WSGI işçileri) aynı düğümlere yazarsa aynı numaralı bloğu iki kez ekleyip zinciri
    bölebilir. Yazmalar, düğüm klasöründeki kilit.db üzerinde BEGIN IMMEDIATE ile sıraya girer; bu SQLite'ın dosya
    kilididir ve Windows'ta da çalışır. Bellek depolarında gerekmez."""
    klasorler = sorted({os.path.dirname(d.yol) for d in depolar.values() if isinstance(d, SqliteDugumDeposu)})
    if not klasorler:
        yield
        return
    os.makedirs(klasorler[0], exist_ok=True)
    c = sqlite3.connect(os.path.join(klasorler[0], "kilit.db"), timeout=30, isolation_level=None)
    try:
        c.execute("BEGIN IMMEDIATE")
        yield
    finally:
        c.close()          # açık işlem kapanışta geri alınır, kilit bırakılır


def dugumlere_yaz(kaynak, kuyruk):
    """kuyruk: (tür, veri_json, zaman) üçlüleri. Bloklar çoğunluk zincirinin sonuna eklenir ve o zincirdeki
    bütün düğümlere yazılır. Zincirin yalnızca son bloğu okunur."""
    if not kuyruk:
        return
    depolar = _depolar(kaynak)
    with _KILIT, _surecler_arasi_kilit(depolar):
        _, okunan, durumlar = _uzlasma(depolar)
        if okunan is None:
            log.error("Kayıt defterinde sağlam düğüm yok; %d blok yazılamadı", len(kuyruk))
            return
        son = okunan.son_blok()
        bas_hash = son["hash"]
        yeni = []
        for tur, veri, z in kuyruk:
            no = son["no"] + 1
            h = blok_hash(no, z, tur, veri, son["hash"])
            son = {"no": no, "zaman": z, "tur": tur, "veri": veri, "onceki": son["hash"], "hash": h}
            yeni.append(son)
        for d in durumlar:
            if d["bas"] != bas_hash or not d["gecerli"]:
                continue   # bozuk ya da ayrışmış düğüme yazılmaz; önce onarılmalı
            depolar[d["ad"]].ekle(yeni)
            _eklendi(depolar[d["ad"]], yeni)


def _uzunluk(okunan, durumlar):
    return next((d["uzunluk"] for d in durumlar if okunan and d["ad"] == okunan.ad), 0)


def durum(kaynak, tam=False):
    """tam=True: düğümler önbelleğe bakılmadan baştan doğrulanır ("denetle" istekleri)."""
    bas, okunan, durumlar = _uzlasma(kaynak, tam)
    return {"bas": bas, "uzunluk": _uzunluk(okunan, durumlar), "dugumler": durumlar,
            "saglikli": all(d.get("durum") == "UYUMLU" for d in durumlar)}


def onar(kaynak, ad):
    """Bozuk/ayrışmış düğümü çoğunluk zincirinden yeniden kurar."""
    depolar = _depolar(kaynak)
    with _KILIT, _surecler_arasi_kilit(depolar):
        bas, okunan, _ = _uzlasma(depolar, tam=True)       # onarım kaynağı önbelleğe güvenilmeden seçilir
        if bas is None:
            raise ValueError("Çoğunluk sağlanamıyor; onarım için en az iki sağlam düğüm gerekli.")
        depolar[ad].yeniden_kur(okunan.bloklar())


def boz_demo(kaynak, ad):
    """SADECE DEMO: bir düğümdeki rastgele bir bloğun verisini hash'i güncellemeden değiştirir.
    Döner: bozulan bloğun numarası (başlangıç bloğundan başka blok yoksa None)."""
    with _KILIT:
        depo = _depolar(kaynak)[ad]
        adaylar = [b for b in depo.bloklar() if b["no"] > 0]      # yalnızca demo: bütün zinciri okumak sorun değil
        if not adaylar:
            return None
        blok = random.choice(adaylar)
        veri = json.loads(blok["veri"])
        veri["kurcalandi"] = 1
        depo.veri_degistir(blok["no"], json.dumps(veri, ensure_ascii=False, sort_keys=True))
        return blok["no"]


# --- Okuma ---

def _json_ekle(b):
    if b is not None:
        b["veri_json"] = json.loads(b["veri"])
    return b


def bloklar(kaynak, sayfa=1, boy=25, tur=None):
    _, okunan, _ = _uzlasma(kaynak)
    if okunan is None:
        return [], 0
    secilen, toplam = okunan.sayfa(tur, (max(1, sayfa) - 1) * boy, boy)
    return [_json_ekle(b) for b in secilen], toplam


def blok_bul(kaynak, anahtar):
    _, okunan, _ = _uzlasma(kaynak)
    return _json_ekle(okunan.bul(anahtar)) if okunan else None


def taahhut(teklif_id, secim, makbuz):
    return ozet(f"{teklif_id}|{secim}|{makbuz}")


def makbuz_dogrula(kaynak, teklif_id, makbuz, secenekler):
    """Makbuz koduyla, oyun deftere hangi seçimle yazıldığını bulur (seçim sadece makbuz sahibince bilinir).
    Döner: None ya da (blok, seçim, güncel_mi). Oy sonradan değiştirildiyse eski makbuzun bloğu güncel değildir."""
    olasi = {taahhut(teklif_id, s, makbuz.strip()): s for s in secenekler}
    _, okunan, _ = _uzlasma(kaynak)
    bulunan, son_oy = None, {}
    for b in okunan.turdeki(("OY",)) if okunan else []:
        v = json.loads(b["veri"])
        if v.get("teklif") != teklif_id:
            continue
        son_oy[v.get("yurttas")] = b["no"]
        if v.get("taahhut") in olasi:
            bulunan = (b, olasi[v["taahhut"]], v.get("yurttas"))
    if not bulunan:
        return None
    blok, secim, yurttas = bulunan
    return blok, secim, son_oy[yurttas] == blok["no"]


# --- Veritabanı ile tutarlılık denetimi ---

def tutarlilik(db):
    """Veritabanındaki mesajları, oyları ve sonuçları defterle karşılaştırır."""
    _, okunan, _ = _uzlasma(db.defter_klasoru)
    mesaj_ozetleri, oylar, sonuclar = {}, {}, {}
    for b in okunan.turdeki(("MESAJ", "MESAJ_DUZENLEME", "OY", "SONUC")) if okunan else []:
        v = json.loads(b["veri"])
        if b["tur"] in ("MESAJ", "MESAJ_DUZENLEME"):
            mesaj_ozetleri[v["mesaj"]] = v["ozet"]
        elif b["tur"] == "OY":
            oylar.setdefault(v["teklif"], {})[v["yurttas"]] = v["taahhut"]
        elif b["tur"] == "SONUC":
            sonuclar[v["teklif"]] = v["ozet"]

    sorunlar = []
    db_mesajlar = {r["id"]: r["icerik"] for r in db.execute("SELECT id, icerik FROM mesajlar")}
    for mid, ozet_ in mesaj_ozetleri.items():
        if mid not in db_mesajlar:
            sorunlar.append(f"#{mid} numaralı mesaj veritabanından SİLİNMİŞ (defterde kaydı var).")
        elif ozet(db_mesajlar[mid]) != ozet_:
            sorunlar.append(f"#{mid} numaralı mesaj defterdeki özetle uyuşmuyor (gizlice değiştirilmiş).")
    for mid in db_mesajlar.keys() - mesaj_ozetleri.keys():
        sorunlar.append(f"#{mid} numaralı mesaj deftere hiç yazılmamış.")

    db_oylar = {}
    for r in db.execute("SELECT o.teklif_id, k.takma_ad, o.taahhut FROM oylar o "
                        "JOIN kullanicilar k ON k.id = o.kullanici_id"):
        db_oylar.setdefault(r["teklif_id"], {})[r["takma_ad"]] = r["taahhut"]
    for tid in set(oylar) | set(db_oylar):
        if oylar.get(tid, {}) != db_oylar.get(tid, {}):
            sorunlar.append(f"#{tid} numaralı oylamanın oyları defterle uyuşmuyor.")
    for r in db.execute("SELECT id, sonuc FROM teklifler WHERE sonuc IS NOT NULL"):
        if r["id"] in sonuclar and ozet(r["sonuc"]) != sonuclar[r["id"]]:
            sorunlar.append(f"#{r['id']} numaralı oylamanın sonucu defterdeki özetle uyuşmuyor.")

    return {"sorunlar": sorunlar, "mesaj": len(mesaj_ozetleri), "oylama": len(oylar), "sonuc": len(sonuclar)}

"""Yönetmeliğin denetim maddeleri (D1–D7) — GoF **Chain of Responsibility**.

Her madde zincirin bir halkasıdır: kendi kontrolünü yapar, bulgusunu ekler ve isteği sıradaki halkaya iletir
(ders slaytı 44'teki `Dogrulayici(sonraki)` kalıbı). Zincir sonuna kadar yürür; hiçbir halka akışı kesmez, çünkü
rapor bütün maddelerin sonucunu gösterir. Bir maddenin ciddiyeti (ENGEL / UYARI / KAPALI) yönetmelikte veridir ve
oylamayla değişir; halka yalnızca "geçti mi, ne diyeceğim" sorusunu yanıtlar.

Yeni bir madde (ör. D8) için yonetmelik.MADDELER'e metni eklenir ve burada bir halka sınıfı yazılır; mesajlara da
uygulanacaksa `mesajlara_uygulanir = True` yapılır. Halkalar tek tek test edilebilir.
"""
import re
from abc import ABC, abstractmethod
from dataclasses import dataclass

from . import ontoloji, yonetmelik, zaman
from .hatalar import KuralHatasi
from .metin import yuzde

KABA_IFADELER = ["aptal", "salak", "gerizekal", "geri zekal", "cahil", "ahmak", "beyinsiz", "serefsiz",
                 "haysiyetsiz", "mankafa", "dangalak", "embesil"]
_YUMUSAMA = {"k": "g", "p": "b", "t": "d", "c": "c"}


def _yumusamis(kok):
    """Türkçe ünsüz yumuşaması: ünlüyle başlayan ek alınca sondaki p, ç, t, k → b, c, d, ğ (ahmak → ahmağın).
    Katlanmış metinde ğ, g olur; bu yüzden "ahmağın" gibi biçimler "ahmag" kökünden yakalanır."""
    return kok[:-1] + _YUMUSAMA[kok[-1]] if kok[-1] in _YUMUSAMA else kok


KABA_KOKLER = sorted(set(KABA_IFADELER) | {_yumusamis(k) for k in KABA_IFADELER})
# Kök kelimenin başında aranır (Türkçe sondan eklemeli): "asalak bitkiler" içindeki "salak" hakaret sayılmaz.
_KABA_DESENLER = {k: re.compile(r"(?<![a-z0-9])" + re.escape(k)) for k in KABA_KOKLER}
# Desenler rakam ya da kelime sınırında başlar: sınırsız desen uzun metinde her konumda yeniden denenir. Telefon
# deseni de 13 haneli bir barkodun içindeki 10 haneyi telefon sayar.
KISISEL_VERI_DESENLERI = {
    "telefon numarası": re.compile(r"(?<!\d)(?:\+?90|0)?\s?\(?5\d{2}\)?[\s-]?\d{3}[\s-]?\d{2}[\s-]?\d{2}(?!\d)"),
    "e-posta adresi": re.compile(r"(?<![\w.+-])[\w.+-]+@[\w-]+\.[\w.]+"),
    "IBAN": re.compile(r"(?<![a-z0-9])TR\s?\d{2}(?:[\s-]?\d{4}){5}[\s-]?\d{2}(?!\d)", re.IGNORECASE),
}
METIN_EN_UZUN = 5000    # serbest metinler (mesaj, fikir, gerekçe, açıklama) için üst sınır
_ON_BIR_HANE = re.compile(r"(?<!\d)[1-9]\d{10}(?!\d)")


def tc_kimlik_gecerli_mi(no):
    """T.C. kimlik numarasının resmi sağlaması: 11 hane, ilk hane 0 değil, 10. ve 11. haneler önceki hanelerden hesaplanır.
    Sağlama, 11 haneli sipariş ya da fatura numaralarının kişisel veri sayılmasını önler."""
    if len(no) != 11 or not no.isdigit() or no[0] == "0":
        return False
    h = [int(c) for c in no]
    return (sum(h[0:9:2]) * 7 - sum(h[1:8:2])) % 10 == h[9] and sum(h[:10]) % 10 == h[10]


def kaba_ifadeler(metin):
    katli = ontoloji.katla(metin)
    return [k for k, desen in _KABA_DESENLER.items() if desen.search(katli)]


def kisisel_veriler(metin):
    bulunan = [ad for ad, desen in KISISEL_VERI_DESENLERI.items() if desen.search(metin)]
    if any(tc_kimlik_gecerli_mi(no) for no in _ON_BIR_HANE.findall(metin)):
        bulunan.insert(1, "T.C. kimlik numarası")
    return bulunan


@dataclass
class DenetimIstegi:
    """Zincir boyunca taşınan istek: denetlenen konu taslağı."""
    db: object
    baslik: str
    aciklama: str
    kategori_id: int
    konum_id: object = None
    ust: object = None
    haric_konu_id: object = None
    onerilen_kategori: object = None       # D3 doldurur: metin başka bir kategoriye daha çok uyuyorsa

    @property
    def metin(self):
        return f"{self.baslik}\n{self.aciklama}"


class DenetimKurali(ABC):
    """Zincirin bir halkası."""
    kod = ""
    mesajlara_uygulanir = False            # True: mesaj, fikir ve gerekçelerde de uygulanır (ENGEL ise engeller, UYARI ise uyarır)

    def __init__(self, sonraki=None):
        self.sonraki = sonraki

    def isle(self, istek):
        """Bu halkanın bulgusu + sonraki halkaların bulguları."""
        bulgular = []
        sonuc = self.kontrol(istek)
        if sonuc is not None:
            gecti, mesaj = sonuc
            bulgular.append({"kod": self.kod, "baslik": yonetmelik.madde_basligi(istek.db, self.kod),
                             "ciddiyet": yonetmelik.ciddiyet(istek.db, self.kod), "gecti": gecti, "mesaj": mesaj})
        if self.sonraki:
            bulgular += self.sonraki.isle(istek)
        return bulgular

    @abstractmethod
    def kontrol(self, istek):
        """Döner: (geçti_mi, açıklama) ya da None (madde bu istek için geçerli değil, ör. üst konu yokken D6)."""

    def mesaj_sorunu(self, metin):
        """Mesaja uygulanan maddeler için: sorun varsa kullanıcıya gösterilecek metin, yoksa None."""
        return None

    def halkalar(self):
        h = self
        while h:
            yield h
            h = h.sonraki


class SayginDil(DenetimKurali):
    kod = "D1"
    mesajlara_uygulanir = True

    def kontrol(self, istek):
        kaba = kaba_ifadeler(istek.metin)
        return (not kaba, "Kaba ifade bulunamadı." if not kaba
                else f"Kaba ifade var: {', '.join(kaba)}. Kişiye değil fikre yönelik yaz.")

    def mesaj_sorunu(self, metin):
        return "Mesajında kaba ifade var; kişiye değil fikre yönelik yaz." if kaba_ifadeler(metin) else None


class KisiselVeri(DenetimKurali):
    kod = "D2"
    mesajlara_uygulanir = True

    def kontrol(self, istek):
        kisisel = kisisel_veriler(istek.metin)
        return (not kisisel, "Kişisel veri bulunamadı." if not kisisel
                else f"Metinde {', '.join(kisisel)} var. Kişisel verileri kaldır.")

    def mesaj_sorunu(self, metin):
        kisisel = kisisel_veriler(metin)
        return f"Mesajında kişisel veri var ({', '.join(kisisel)}); kaldırıp tekrar gönder." if kisisel else None


class KategoriyeUygunluk(DenetimKurali):
    kod = "D3"

    def kontrol(self, istek):
        db, kategori_id = istek.db, istek.kategori_id
        kategori_adi = ontoloji.yol_metni(db, "kategoriler", kategori_id)
        if ontoloji.genel_mi(db, kategori_id):
            return True, f"“{kategori_adi}” her konuya açık."
        terimler, _ = ontoloji.kategori_iliskisi(db, istek.metin, kategori_id)
        if terimler:
            return True, f"“{kategori_adi}” kavramlarıyla ilişkili: {', '.join(terimler[:6])}."
        oneri_id, oneri_terimler = ontoloji.en_uygun_kategori(db, istek.metin)
        if oneri_id:
            istek.onerilen_kategori = oneri_id
            return False, (f"“{kategori_adi}” ile ilgili bir kavram yok. Metin daha çok "
                           f"“{ontoloji.yol_metni(db, 'kategoriler', oneri_id)}” kategorisine uyuyor "
                           f"({', '.join(oneri_terimler[:4])}).")
        return False, "Metin hiçbir kategoriyle eşleşmedi. Açıklamaya konunun alanıyla ilgili ayrıntı ekle."


class KonumTutarliligi(DenetimKurali):
    kod = "D4"

    def kontrol(self, istek):
        db, konum_id = istek.db, istek.konum_id
        yerler = ontoloji.metindeki_yerler(db, istek.metin)
        if not yerler:
            return True, "Metinde belirli bir yer adı geçmiyor."
        if konum_id is None:
            adlar = ", ".join(ontoloji.yol_metni(db, "konumlar", y) for y in yerler[:3])
            return False, (f"Metinde {adlar} geçiyor ama katılım herkese açık. Konu yalnızca o yeri "
                           "ilgilendiriyorsa katılımı o yerin sakinleriyle sınırlayabilirsin.")
        uyumsuz = [y for y in yerler if not (ontoloji.altinda_mi(db, "konumlar", y, konum_id)
                                            or ontoloji.altinda_mi(db, "konumlar", konum_id, y))]
        if not uyumsuz:
            return True, "Metindeki yer adları katılım kuralıyla uyumlu."
        return False, (f"Katılım {ontoloji.yol_metni(db, 'konumlar', konum_id)} sakinlerine açık ama metinde "
                       f"{', '.join(ontoloji.yol_metni(db, 'konumlar', y) for y in uyumsuz[:3])} geçiyor.")


class BenzerKonu(DenetimKurali):
    kod = "D5"
    ESIK = 0.5

    def kontrol(self, istek):
        benzer = None
        for k in istek.db.execute("SELECT id, baslik FROM konular WHERE silindi = 0 AND durum != 'SONUCSUZ' AND id != ?",
                                  (istek.haric_konu_id or 0,)):
            oran = ontoloji.benzerlik_orani(istek.baslik, k["baslik"])
            if oran >= self.ESIK and (benzer is None or oran > benzer[1]):
                benzer = (k, oran)
        if benzer is None:
            return True, "Benzer bir konu bulunamadı."
        return False, f"#{benzer[0]['id']} “{benzer[0]['baslik']}” ile {yuzde(benzer[1])} benzer."


class AltKonuIliskisi(DenetimKurali):
    kod = "D6"

    def kontrol(self, istek):
        ust = istek.ust
        if ust is None:
            return None
        db = istek.db
        if (ontoloji.altinda_mi(db, "kategoriler", istek.kategori_id, ust["kategori_id"])
                or ontoloji.altinda_mi(db, "kategoriler", ust["kategori_id"], istek.kategori_id)):
            return True, "Üst konuyla aynı alanda."
        ortak = ontoloji.anlamli_kelimeler(istek.metin) & ontoloji.anlamli_kelimeler(f"{ust['baslik']} {ust['aciklama']}")
        if ortak:
            return True, f"Üst konuyla ortak kavramlar: {', '.join(sorted(ortak)[:5])}."
        return False, "Üst konuyla alanı da kavramları da ortak değil."


class Aciklik(DenetimKurali):
    kod = "D7"
    EN_AZ = 40

    def kontrol(self, istek):
        if len(istek.aciklama.strip()) < self.EN_AZ:
            return False, "Açıklama çok kısa. Derdini ve nedenini anlat."
        return True, "Açıklama yeterli uzunlukta."


def zincir_kur(*siniflar):
    """Halkaları verilen sırayla birbirine bağlar; ilk halkayı döndürür."""
    ilk = None
    for sinif in reversed(siniflar):
        ilk = sinif(ilk)
    return ilk


ZINCIR = zincir_kur(SayginDil, KisiselVeri, KategoriyeUygunluk, KonumTutarliligi, BenzerKonu, AltKonuIliskisi, Aciklik)


def denetle(db, baslik, aciklama, kategori_id, konum_id=None, ust=None, haric_konu_id=None):
    """Bir konu taslağını zincirden geçirir ve bir rapor döndürür."""
    istek = DenetimIstegi(db, baslik, aciklama, kategori_id, konum_id, ust, haric_konu_id)
    bulgular = ZINCIR.isle(istek)
    etkin = [b for b in bulgular if b["ciddiyet"] != "KAPALI"]
    return {
        "bulgular": bulgular,
        "engel": [b for b in etkin if not b["gecti"] and b["ciddiyet"] == "ENGEL"],
        "uyarilar": [b for b in etkin if not b["gecti"] and b["ciddiyet"] == "UYARI"],
        "puan": round(100 * sum(1 for b in etkin if b["gecti"]) / len(etkin)) if etkin else 100,
        "onerilen_kategori": istek.onerilen_kategori,
        "zaman": zaman.simdi_metin(),
    }


def mesaj_denetle(db, icerik):
    """Mesajlar (ve fikir, gerekçe gibi serbest metinler) için zincirin yalnızca ENGEL durumundaki mesaj halkaları
    uygulanır (hakaret, kişisel veri). Gerekçe alanlarının kendi üst sınırı olmadığından uzunluk burada sınırlanır."""
    if len(icerik) > METIN_EN_UZUN:
        raise KuralHatasi(f"Metin en fazla {METIN_EN_UZUN} karakter olabilir.")
    sorunlar = _mesaj_sorunlari(db, icerik, "ENGEL")
    if sorunlar:
        raise KuralHatasi(" ".join(sorunlar))


def mesaj_uyarilari(db, icerik):
    """UYARI durumundaki mesaj halkalarının bulguları. Mesaj yayımlanır, yazana uyarı gösterilir."""
    return _mesaj_sorunlari(db, icerik, "UYARI")


def _mesaj_sorunlari(db, icerik, ciddiyet):
    return [s for h in ZINCIR.halkalar() if h.mesajlara_uygulanir and yonetmelik.ciddiyet(db, h.kod) == ciddiyet
            for s in [h.mesaj_sorunu(icerik or "")] if s]

"""Oy devri (likit demokrasi).

Kurallar:
  * Kapsam: tüm forum (GENEL), bir kategori (KATEGORI) ya da tek konu (KONU).
    Bir oylamada en özel kapsam geçerlidir: KONU > KATEGORI > GENEL.
  * Zincirleme: A → B → C. Döngüler engellenir.
  * Doğrudan oy devri ezer: devretmiş olsan da kendin oy verirsen senin oyun sayılır.
  * Devralan kişinin o oylamada oy hakkı yoksa devir o oylamada geçmez.
  * Sadece temel oy (1) devredilir; uzmanlık ağırlığı kişiye özeldir.
  * Bir kişi en fazla MAX_DEVIR (yönetmelik parametresi) devredilmiş oy taşıyabilir.
  * Yapay zeka hesapları oy kullanmadığı için onlara oy devredilemez.
"""
from collections import defaultdict

from . import bildirimler, defter, gunluk, ontoloji, uygunluk, yonetmelik, zaman
from .hatalar import KuralHatasi, tamsayi

KAPSAMLAR = {"GENEL": "Tüm forum", "KATEGORI": "Kategori", "KONU": "Konu"}

DUSME_NEDENLERI = {
    "DONGU": "devir zinciri döngüye giriyor",
    "HAK_YOK": "devralan kişinin bu oylamada oy hakkı yok",
    "TAVAN": "devralan kişi devir tavanına ulaştı",
}


def devir_ekle(db, veren, alan_takma_ad, kapsam, kapsam_id=0):
    if kapsam not in KAPSAMLAR:
        raise KuralHatasi("Geçersiz devir kapsamı.")
    if veren["yz_mi"]:
        raise KuralHatasi("YZ hesapları oy devredemez.")
    kapsam_id = 0 if kapsam == "GENEL" else tamsayi(kapsam_id, "Geçersiz kategori ya da konu.")
    if kapsam == "KATEGORI":
        if not ontoloji.dugum(db, "kategoriler", kapsam_id):
            raise KuralHatasi("Kategori bulunamadı.")
    elif kapsam == "KONU":
        if not db.execute("SELECT 1 FROM konular WHERE id = ? AND silindi = 0", (kapsam_id,)).fetchone():
            raise KuralHatasi("Konu bulunamadı.")

    alan = db.execute("SELECT * FROM kullanicilar WHERE takma_ad = ?", (alan_takma_ad.strip(),)).fetchone()
    if not alan:
        raise KuralHatasi(f"“{alan_takma_ad}” adında bir kullanıcı yok.")
    if alan["id"] == veren["id"]:
        raise KuralHatasi("Oyunu kendine devredemezsin.")
    if alan["yz_mi"]:
        raise KuralHatasi("Yapay zeka hesapları oy kullanmaz; onlara oy devredilemez.")

    # Aynı kapsamda zinciri izle: veren'e geri dönüyorsa döngü var.
    x, gorulen = alan["id"], set()
    while x and x not in gorulen:
        if x == veren["id"]:
            raise KuralHatasi(f"Bu devir bir döngü oluşturur (@{alan['takma_ad']} zaten sana zincirle bağlı).")
        gorulen.add(x)
        r = db.execute("SELECT alan_id FROM devirler WHERE veren_id = ? AND kapsam = ? AND kapsam_id = ?",
                       (x, kapsam, kapsam_id)).fetchone()
        x = r["alan_id"] if r else None

    db.execute(
        """INSERT INTO devirler (veren_id, alan_id, kapsam, kapsam_id, olusturma) VALUES (?, ?, ?, ?, ?)
           ON CONFLICT (veren_id, kapsam, kapsam_id)
           DO UPDATE SET alan_id = excluded.alan_id, olusturma = excluded.olusturma""",
        (veren["id"], alan["id"], kapsam, kapsam_id, zaman.simdi_metin()),
    )
    kapsam_yazi = kapsam_metni(db, kapsam, kapsam_id)
    gunluk.kaydet(db, veren["id"], "DEVIR", f"Oy devri → @{alan['takma_ad']} ({kapsam_yazi})")
    defter.ekle(db, "DEVIR", {"veren": veren["takma_ad"], "alan": alan["takma_ad"], "kapsam": kapsam_yazi})
    bildirimler.gonder(db, alan["id"], f"@{veren['takma_ad']} oy hakkını sana devretti ({kapsam_yazi}).",
                       f"/kullanici/{veren['takma_ad']}")


def devir_sil(db, veren, devir_id):
    d = db.execute("SELECT * FROM devirler WHERE id = ? AND veren_id = ?", (devir_id, veren["id"])).fetchone()
    if not d:
        raise KuralHatasi("Devir bulunamadı.")
    db.execute("DELETE FROM devirler WHERE id = ?", (devir_id,))
    kapsam_yazi = kapsam_metni(db, d["kapsam"], d["kapsam_id"])
    gunluk.kaydet(db, veren["id"], "DEVIR_GERI", f"Oy devri geri alındı ({kapsam_yazi})")
    defter.ekle(db, "DEVIR_GERI", {"veren": veren["takma_ad"], "kapsam": kapsam_yazi})


def kapsam_metni(db, kapsam, kapsam_id):
    if kapsam == "GENEL":
        return "tüm forum"
    if kapsam == "KATEGORI":
        return "kategori: " + ontoloji.yol_metni(db, "kategoriler", kapsam_id)
    r = db.execute("SELECT baslik FROM konular WHERE id = ?", (kapsam_id,)).fetchone()
    return "konu: " + (r["baslik"] if r else f"#{kapsam_id}")


def verilen_devirler(db, kullanici_id):
    return db.execute(
        """SELECT d.*, k.takma_ad AS alan_ad, k.yz_mi AS alan_yz FROM devirler d
           JOIN kullanicilar k ON k.id = d.alan_id WHERE d.veren_id = ? ORDER BY d.id""",
        (kullanici_id,),
    ).fetchall()


def alinan_devirler(db, kullanici_id):
    return db.execute(
        """SELECT d.*, k.takma_ad AS veren_ad FROM devirler d
           JOIN kullanicilar k ON k.id = d.veren_id WHERE d.alan_id = ? ORDER BY d.id""",
        (kullanici_id,),
    ).fetchall()


def gecerli_devir(db, kullanici_id, baglam):
    """Bu bağlamda kullanıcının oyunu kime devrettiği: en özel kapsam kazanır."""
    devirler = {(d["kapsam"], d["kapsam_id"]): d["alan_id"] for d in
                db.execute("SELECT * FROM devirler WHERE veren_id = ?", (kullanici_id,))}
    if not devirler:
        return None, None
    if baglam.konu is not None:
        for k in reversed(uygunluk.konu_zinciri(db, baglam.konu)):
            if ("KONU", k["id"]) in devirler:
                return devirler[("KONU", k["id"])], "KONU"
    kategoriler = ontoloji.atalar(db, "kategoriler", baglam.kategori_id) if baglam.kategori_id else []
    for kategori_id in reversed(kategoriler):
        if ("KATEGORI", kategori_id) in devirler:
            return devirler[("KATEGORI", kategori_id)], "KATEGORI"
    if ("GENEL", 0) in devirler:
        return devirler[("GENEL", 0)], "GENEL"
    return None, None


def _zinciri_izle(db, kullanici_id, baglam, dogrudan, hakli):
    """(oyun ulaştığı doğrudan oy veren, düşme nedeni)."""
    gorulen, x = {kullanici_id}, kullanici_id
    while True:
        alan, _ = gecerli_devir(db, x, baglam)
        if alan is None:
            return None, None          # zincir oy vermeyen birinde bitti: oy kullanılmadı
        if alan in gorulen:
            return None, "DONGU"
        if alan not in hakli:
            return None, "HAK_YOK"
        if alan in dogrudan:
            return alan, None
        gorulen.add(alan)
        x = alan


def devirleri_coz(db, baglam, dogrudan, hakli):
    """Doğrudan oy vermeyen hak sahiplerinin oylarını zincir boyunca taşır.

    dogrudan: doğrudan oy veren kullanıcı id'leri
    hakli:    bu oylamada oy hakkı olan kullanıcı id'leri
    Döner: ({oy_veren_id: [devreden_id, ...]}, [(kullanici_id, neden_kodu), ...])
    """
    tasinan, dusen = defaultdict(list), []
    for uid in sorted(hakli):
        if uid in dogrudan:
            continue
        hedef, neden = _zinciri_izle(db, uid, baglam, dogrudan, hakli)
        if hedef is not None:
            tasinan[hedef].append(uid)
        elif neden:
            dusen.append((uid, neden))
    tavan = yonetmelik.deger(db, "MAX_DEVIR")
    for hedef, liste in tasinan.items():
        if len(liste) > tavan:
            dusen.extend((uid, "TAVAN") for uid in liste[tavan:])
            tasinan[hedef] = liste[:tavan]
    return dict(tasinan), dusen

"""Üyeler grafı.

Düğümler üyelerdir. Kenarlar:
  DEVIR     veren → alan         (oy devri)
  YANIT     yanıtlayan → yazar   (tartışma etkileşimi)
  TAKIP     takipçi → takip edilen
  BENZERLIK iki üyenin sonuçlanmış oylamalarda aynı yönde oy verme oranı (yönsüz). YALNIZCA İÇ HESAPTA kullanılır:
            ikili benzerlik dışarı verilirse kendi oyunu bilen biri komşusunun gizli oyunu çıkarabilir (T4 gizli oy).
            Dışarıya yalnızca en az GRUP_EN_AZ kişilik görüş grupları gösterilir (k-anonimlik).

Graf üzerinde hesaplananlar:
  * Etki puanı (PageRank)
  * Oy gücü dağılımı ve Gini katsayısı (güç yoğunlaşması uyarısı)
  * Görüş grupları (oy benzerliği grafında etiket yayılımı)
"""
from collections import defaultdict

from . import ayarlar, bildirimler, yonetmelik, zaman
from .hatalar import BulunamadiHatasi, KuralHatasi

# Görüş grupları da paletten renk alır: yeşilin ve grinin birbirinden kolay ayrılan tonları
GRUP_RENKLERI = [ayarlar.YESIL[600], ayarlar.GRI[500], ayarlar.YESIL[300], ayarlar.YESIL[800],
                 ayarlar.GRI[300], ayarlar.YESIL[400], ayarlar.YESIL[200], ayarlar.GRI[700]]
GRUPSUZ_RENK = ayarlar.TAS_BEYAZI[50]
KENAR_AGIRLIKLARI = {"DEVIR": 2.0, "YANIT": 1.0, "TAKIP": 0.5}
GRUP_EN_AZ = 3        # bundan küçük görüş grubu gösterilmez: iki kişilik grup, iki kişinin aynı oyu verdiğini ele verir


# --- Takip (sosyal kenar) ---

def takip_et(db, kullanici, hedef_id):
    if hedef_id == kullanici["id"]:
        raise KuralHatasi("Kendini takip edemezsin.")
    hedef = db.execute("SELECT * FROM kullanicilar WHERE id = ?", (hedef_id,)).fetchone()
    if not hedef:
        raise BulunamadiHatasi("Kullanıcı bulunamadı.")
    if takip_ediyor_mu(db, kullanici["id"], hedef_id):
        db.execute("DELETE FROM takipler WHERE takip_eden_id = ? AND takip_edilen_id = ?", (kullanici["id"], hedef_id))
        return False
    db.execute("INSERT INTO takipler (takip_eden_id, takip_edilen_id, olusturma) VALUES (?, ?, ?)",
               (kullanici["id"], hedef_id, zaman.simdi_metin()))
    bildirimler.gonder(db, hedef_id, f"@{kullanici['takma_ad']} seni takip etmeye başladı.",
                       f"/kullanici/{kullanici['takma_ad']}")
    return True


def takip_ediyor_mu(db, eden_id, edilen_id):
    return bool(db.execute("SELECT 1 FROM takipler WHERE takip_eden_id = ? AND takip_edilen_id = ?",
                           (eden_id, edilen_id)).fetchone())


def takip_sayilari(db, kullanici_id):
    takipci = db.execute("SELECT COUNT(*) FROM takipler WHERE takip_edilen_id = ?", (kullanici_id,)).fetchone()[0]
    takip = db.execute("SELECT COUNT(*) FROM takipler WHERE takip_eden_id = ?", (kullanici_id,)).fetchone()[0]
    return takipci, takip


# --- Kenarlar ---

def kenarlar(db):
    """[(kaynak, hedef, tür, ağırlık)] — yönlü kenarlar (benzerlik hariç)."""
    liste = []
    for r in db.execute("SELECT veren_id, alan_id, COUNT(*) n FROM devirler GROUP BY veren_id, alan_id"):
        liste.append((r["veren_id"], r["alan_id"], "DEVIR", r["n"]))
    for r in db.execute("""SELECT y.yazar_id k, u.yazar_id h, COUNT(*) n FROM mesajlar y
                           JOIN mesajlar u ON u.id = y.ust_mesaj_id
                           WHERE y.yazar_id IS NOT NULL AND u.yazar_id IS NOT NULL AND y.yazar_id != u.yazar_id
                           GROUP BY y.yazar_id, u.yazar_id"""):
        liste.append((r["k"], r["h"], "YANIT", r["n"]))
    for r in db.execute("SELECT takip_eden_id, takip_edilen_id FROM takipler"):
        liste.append((r["takip_eden_id"], r["takip_edilen_id"], "TAKIP", 1))
    return liste


def cekismeli_oylamalar(db, tavan=0.8):
    """Görüş ayrılığını gösteren oylamalar: en az 3 oy, önde giden seçenek oyların %80'inden azı.
    Neredeyse oybirliğiyle geçen oylamalar kimin kiminle aynı düşündüğünü göstermez."""
    dagilim = defaultdict(lambda: defaultdict(int))
    for r in db.execute("""SELECT o.teklif_id, o.secim FROM oylar o JOIN teklifler t ON t.id = o.teklif_id
                           WHERE t.durum != 'ACIK' AND o.secim != 'CEKIMSER'"""):
        dagilim[r["teklif_id"]][r["secim"]] += 1
    return {t for t, d in dagilim.items() if sum(d.values()) >= 3 and max(d.values()) / sum(d.values()) < tavan}


def oy_benzerlikleri(db, en_az_ortak=2, esik=0.6):
    """{(a, b): benzerlik} — çekişmeli oylamalarda aynı yönde oy verme oranı (çekimserler hariç)."""
    cekismeli = cekismeli_oylamalar(db)
    oylar = defaultdict(dict)
    for r in db.execute("""SELECT o.kullanici_id, o.teklif_id, o.secim FROM oylar o
                           JOIN teklifler t ON t.id = o.teklif_id
                           WHERE t.durum != 'ACIK' AND o.secim != 'CEKIMSER'"""):
        if r["teklif_id"] in cekismeli:
            oylar[r["kullanici_id"]][r["teklif_id"]] = r["secim"]
    kisiler = sorted(oylar)
    sonuc = {}
    for i, a in enumerate(kisiler):
        for b in kisiler[i + 1:]:
            ortak = oylar[a].keys() & oylar[b].keys()
            if len(ortak) < en_az_ortak:
                continue
            oran = sum(1 for t in ortak if oylar[a][t] == oylar[b][t]) / len(ortak)
            if oran >= esik:
                sonuc[(a, b)] = oran
    return sonuc


# --- Görüş grupları ---

def gorus_gruplari(db):
    """Oy benzerliği grafında etiket yayılımıyla bulunan gruplar (en az GRUP_EN_AZ üyeli)."""
    if "gruplar" in db.onbellek:
        return db.onbellek["gruplar"]
    benzerlik = oy_benzerlikleri(db)
    komsular = defaultdict(dict)
    for (a, b), w in benzerlik.items():
        komsular[a][b] = w
        komsular[b][a] = w
    etiket = {k: k for k in komsular}
    for _ in range(20):
        degisti = False
        for k in sorted(komsular):
            puanlar = defaultdict(float)
            for n, w in komsular[k].items():
                puanlar[etiket[n]] += w
            en_iyi = min(puanlar, key=lambda e: (-puanlar[e], e))
            if puanlar[en_iyi] > puanlar.get(etiket[k], 0) and en_iyi != etiket[k]:
                etiket[k] = en_iyi
                degisti = True
        if not degisti:
            break
    kumeler = defaultdict(list)
    for k, e in etiket.items():
        kumeler[e].append(k)
    gruplar = sorted((sorted(u) for u in kumeler.values() if len(u) >= GRUP_EN_AZ), key=lambda u: (-len(u), u[0]))
    sonuc = [{"no": i, "ad": f"Grup {chr(65 + i)}", "renk": GRUP_RENKLERI[i % len(GRUP_RENKLERI)], "uyeler": u}
             for i, u in enumerate(gruplar)]
    db.onbellek["gruplar"] = sonuc
    return sonuc


# --- Etki (PageRank) ---

def etki_puanlari(db, adim=30, sonum=0.85):
    kisiler = [r["id"] for r in db.execute("SELECT id FROM kullanicilar")]
    if not kisiler:
        return {}
    cikis = defaultdict(list)
    for k, h, tur, n in kenarlar(db):
        cikis[k].append((h, KENAR_AGIRLIKLARI[tur] * n))
    n = len(kisiler)
    puan = {k: 1 / n for k in kisiler}
    for _ in range(adim):
        yeni = {k: (1 - sonum) / n for k in kisiler}
        sarkan = sum(puan[k] for k in kisiler if not cikis[k])
        for k in kisiler:
            toplam = sum(w for _, w in cikis[k])
            for h, w in cikis[k]:
                yeni[h] += sonum * puan[k] * w / toplam
        for k in kisiler:
            yeni[k] += sonum * sarkan / n
        puan = yeni
    en = max(puan.values())
    return {k: round(100 * v / en) for k, v in puan.items()}


# --- Oy gücü ve yoğunlaşma ---

def oy_gucleri(db):
    """Genel kapsamlı devirlere göre, devretmeyenler oy verdiğinde her üyenin taşıdığı oy sayısı.
    Oyunu devreden 0 taşır; zincirin sonundaki kişi kendi oyu + devredilenleri (tavanlı) taşır."""
    alan = {r["veren_id"]: r["alan_id"] for r in
            db.execute("SELECT veren_id, alan_id FROM devirler WHERE kapsam = 'GENEL'")}
    guc = {r["id"]: 1 for r in db.execute("SELECT id FROM kullanicilar")}
    tasinan = defaultdict(int)
    for veren in alan:
        guc[veren] = 0
        gorulen, x = {veren}, alan[veren]
        while x in alan and x not in gorulen:
            gorulen.add(x)
            x = alan[x]
        if x not in gorulen and x in guc:      # döngüye giren devir kaybolur
            tasinan[x] += 1
    tavan = yonetmelik.deger(db, "MAX_DEVIR")
    for x, n in tasinan.items():
        guc[x] += min(n, tavan)
    return guc


def gini(degerler):
    degerler = sorted(v for v in degerler if v >= 0)
    n, toplam = len(degerler), sum(degerler)
    if n == 0 or toplam == 0:
        return 0.0
    kumulatif = sum((i + 1) * v for i, v in enumerate(degerler))
    return (2 * kumulatif) / (n * toplam) - (n + 1) / n


# --- Görselleştirme verisi ---

def graf_verisi(db):
    etki = etki_puanlari(db)
    gruplar = gorus_gruplari(db)
    grup_of = {u: g for g in gruplar for u in g["uyeler"]}
    uzmanlar = {r["kullanici_id"] for r in db.execute("SELECT kullanici_id FROM uzmanliklar WHERE bitis > ?",
                                                      (zaman.simdi_metin(),))}
    dugumler = [{"id": r["id"], "ad": r["takma_ad"], "yz": bool(r["yz_mi"]), "uzman": r["id"] in uzmanlar,
                 "etki": etki.get(r["id"], 0), "grup": grup_of[r["id"]]["ad"] if r["id"] in grup_of else None,
                 "renk": grup_of[r["id"]]["renk"] if r["id"] in grup_of else GRUPSUZ_RENK}
                for r in db.execute("SELECT id, takma_ad, yz_mi FROM kullanicilar ORDER BY id")]
    kenar_listesi = [{"kaynak": k, "hedef": h, "tur": t, "agirlik": n} for k, h, t, n in kenarlar(db)]
    return {"dugumler": dugumler, "kenarlar": kenar_listesi}   # ikili oy benzerliği gizli oy nedeniyle verilmez


def ozet(db):
    guc = oy_gucleri(db)
    etki = etki_puanlari(db)
    adlar = {r["id"]: r["takma_ad"] for r in db.execute("SELECT id, takma_ad FROM kullanicilar")}
    g = gini(list(guc.values()))
    return {
        "gini": g,
        "yogunlasma": "düşük" if g < 0.2 else ("orta" if g < 0.4 else "yüksek"),
        "en_guclu": sorted(((adlar[k], v) for k, v in guc.items() if v > 1), key=lambda x: -x[1])[:5],
        "en_etkili": sorted(((adlar[k], v) for k, v in etki.items()), key=lambda x: -x[1])[:8],
        "gruplar": [{"ad": gr["ad"], "renk": gr["renk"], "uyeler": [adlar[u] for u in gr["uyeler"]]}
                    for gr in gorus_gruplari(db)],
    }

