"""Güvenlik: giriş denemesi sınırı, şifre kurtarma kodu, API anahtarları."""
import hashlib
import os
import secrets
from datetime import timedelta

from werkzeug.security import check_password_hash, generate_password_hash

from . import ayarlar, zaman
from .hatalar import KuralHatasi

# Şifre özeti yöntemi. Üretimde Werkzeug'ün scrypt'i kullanılır; testler her scrypt çağrısı ~0,1 sn sürdüğü için
# bunu hızlı bir yönteme çevirir.
SIFRE_YONTEMI = os.environ.get("FORUM_SIFRE_YONTEMI", "scrypt")


# --- Kaba kuvvet saldırısına karşı giriş sınırı ---

def _anahtar(anahtar):
    return anahtar[:200]          # uzun takma ad denemeleriyle tablo şişirilemesin


def giris_kilitli_mi(db, anahtar):
    anahtar = _anahtar(anahtar)
    r = db.execute("SELECT * FROM giris_denemeleri WHERE anahtar = ?", (anahtar,)).fetchone()
    if r and r["kilit_bitis"] and r["kilit_bitis"] > zaman.simdi_metin():
        kalan = zaman.coz(r["kilit_bitis"]) - zaman.simdi()
        raise KuralHatasi(f"Çok fazla hatalı giriş denemesi. {max(1, kalan.seconds // 60)} dakika sonra tekrar dene.")


def hatali_giris(db, anahtar):
    anahtar = _anahtar(anahtar)
    r = db.execute("SELECT * FROM giris_denemeleri WHERE anahtar = ?", (anahtar,)).fetchone()
    sayi = (r["sayi"] if r and not r["kilit_bitis"] else 0) + 1
    kilit = None
    if sayi >= ayarlar.GIRIS_DENEME_SINIRI:
        kilit = zaman.metin(zaman.simdi() + timedelta(minutes=ayarlar.GIRIS_KILIT_DAKIKA))
        sayi = 0
    db.execute("INSERT INTO giris_denemeleri (anahtar, sayi, kilit_bitis) VALUES (?, ?, ?) "
               "ON CONFLICT (anahtar) DO UPDATE SET sayi = excluded.sayi, kilit_bitis = excluded.kilit_bitis",
               (anahtar, sayi, kilit))
    db.commit()


def basarili_giris(db, anahtar):
    db.execute("DELETE FROM giris_denemeleri WHERE anahtar = ?", (_anahtar(anahtar),))


def hiz_siniri(db, anahtar, sinir, dakika, mesaj):
    """Aynı anahtarla (ör. bir IP'den yeni üyelik) `dakika` içinde en fazla `sinir` işlem. Aşılırsa KuralHatasi.
    giris_denemeleri tablosu kullanılır; kilit_bitis sütunu burada pencerenin bitişidir."""
    anahtar, simdi = _anahtar(anahtar), zaman.simdi()
    r = db.execute("SELECT * FROM giris_denemeleri WHERE anahtar = ?", (anahtar,)).fetchone()
    if r and r["kilit_bitis"] and r["kilit_bitis"] > zaman.metin(simdi):
        if r["sayi"] >= sinir:
            raise KuralHatasi(mesaj)
        db.execute("UPDATE giris_denemeleri SET sayi = sayi + 1 WHERE anahtar = ?", (anahtar,))
        return
    db.execute("INSERT INTO giris_denemeleri (anahtar, sayi, kilit_bitis) VALUES (?, 1, ?) ON CONFLICT (anahtar) "
               "DO UPDATE SET sayi = 1, kilit_bitis = excluded.kilit_bitis",
               (anahtar, zaman.metin(simdi + timedelta(minutes=dakika))))


# --- Şifre ---

def sifre_kontrol(sifre, tekrar):
    if len(sifre or "") < ayarlar.SIFRE_MIN:
        raise KuralHatasi(f"Şifre en az {ayarlar.SIFRE_MIN} karakter olmalı.")
    if not any(c.isdigit() for c in sifre) or not any(c.isalpha() for c in sifre):
        raise KuralHatasi("Şifre en az bir harf ve bir rakam içermeli.")
    if sifre != tekrar:
        raise KuralHatasi("Şifreler aynı değil.")


def sifre_hash(sifre):
    return generate_password_hash(sifre, method=SIFRE_YONTEMI)


def sifre_dogru_mu(hash_, sifre):
    return bool(hash_) and check_password_hash(hash_, sifre or "")


# --- Kurtarma kodu (e-posta olmadan şifre sıfırlama) ---

def kurtarma_kodu_uret():
    parcalar = [secrets.token_hex(2).upper() for _ in range(4)]
    return "AGORA-" + "-".join(parcalar)


def kurtarma_hash(kod):
    return generate_password_hash(kod.strip().upper(), method=SIFRE_YONTEMI)


def kurtarma_dogru_mu(hash_, kod):
    return bool(hash_) and check_password_hash(hash_, (kod or "").strip().upper())


# --- API anahtarları (mobil uygulama / dış istemciler) ---

def _anahtar_ozeti(anahtar):
    return hashlib.sha256(anahtar.encode()).hexdigest()


def api_anahtari_olustur(db, kullanici_id, ad):
    """Aynı adlı (aynı cihazın) eski anahtarı yenisiyle değiştirir; mobil uygulama her girişte kilitlenmesin."""
    ad = ((ad or "").strip() or "Uygulama")[:40]
    db.execute("DELETE FROM api_anahtarlari WHERE kullanici_id = ? AND ad = ?", (kullanici_id, ad))
    if db.execute("SELECT COUNT(*) FROM api_anahtarlari WHERE kullanici_id = ?", (kullanici_id,)).fetchone()[0] >= 5:
        raise KuralHatasi("En fazla 5 API anahtarın olabilir; önce birini sil.")
    anahtar = "agr_" + secrets.token_urlsafe(32)
    db.execute("INSERT INTO api_anahtarlari (kullanici_id, ad, anahtar_hash, olusturma) VALUES (?, ?, ?, ?)",
               (kullanici_id, ad[:40], _anahtar_ozeti(anahtar), zaman.simdi_metin()))
    return anahtar


def api_anahtari_kullanici(db, anahtar):
    r = db.execute("SELECT * FROM api_anahtarlari WHERE anahtar_hash = ?", (_anahtar_ozeti(anahtar),)).fetchone()
    if not r:
        return None
    db.execute("UPDATE api_anahtarlari SET son_kullanim = ? WHERE id = ?", (zaman.simdi_metin(), r["id"]))
    return db.execute("SELECT * FROM kullanicilar WHERE id = ?", (r["kullanici_id"],)).fetchone()


def api_anahtarlari(db, kullanici_id):
    return db.execute("SELECT id, ad, olusturma, son_kullanim FROM api_anahtarlari WHERE kullanici_id = ? "
                      "ORDER BY id DESC", (kullanici_id,)).fetchall()


def api_anahtari_sil(db, kullanici_id, anahtar_id):
    db.execute("DELETE FROM api_anahtarlari WHERE id = ? AND kullanici_id = ?", (anahtar_id, kullanici_id))


def oturumlari_kapat(db, kullanici_id):
    """Şifre değişince: eski oturum çerezleri (sürüm) ve bütün API anahtarları geçersiz olur."""
    db.execute("UPDATE kullanicilar SET oturum_surumu = oturum_surumu + 1 WHERE id = ?", (kullanici_id,))
    db.execute("DELETE FROM api_anahtarlari WHERE kullanici_id = ?", (kullanici_id,))

class KuralHatasi(Exception):
    """Forum kurallarına aykırı bir istek. Mesajı doğrudan kullanıcıya gösterilir."""


class BulunamadiHatasi(KuralHatasi):
    """İstenen kayıt (konu, mesaj, oylama, üye…) yok. Web katmanı bunu 404'e çevirir (KuralHatasi 400/422 olur)."""


def tamsayi(deger, mesaj="Sayı bekleniyordu."):
    """Formdan ya da JSON'dan gelen değeri tam sayıya çevirir. Boşsa None; çevrilemiyorsa KuralHatasi.

    Kullanıcı girdisi hiçbir yerde doğrudan int() ile çevrilmez: "abc", "1.5" ya da "²" gibi değerler
    500 hatası yerine kullanıcıya anlaşılır bir uyarı olarak döner."""
    if deger is None or (isinstance(deger, str) and not deger.strip()):
        return None
    try:
        return int(str(deger).strip())
    except ValueError:
        raise KuralHatasi(mesaj) from None

"""Kategoriler: forumun zamanla büyüyen konu ağacı.

7 temel alan ve Genel kategori hazır gelir (ontoloji.KATEGORILER). Her üye yeni bir ana kategori ya da bir ana
kategorinin altına alt kategori önerebilir. Öneri bütün üyelerin oyuna sunulur (herkes 1 oy, ESIK_KATEGORI);
kabul edilirse kategori eklenir ve önerirken yazılan kavramlar kategori denetiminde (D3) kullanılır.
"""
import json
from datetime import timedelta

from . import ayarlar, bildirimler, defter, denetim, gunluk, ontoloji, oylama, zaman
from .hatalar import KuralHatasi, tamsayi

MAX_KAVRAM = 15
SIRALAMALAR = {"populer": "En çok konu", "etkin": "Son etkinlik", "ad": "Ada göre", "yeni": "En yeni"}
SUZGECLER = {"": "Tümü", "ana": "Ana kategoriler", "alt": "Alt kategoriler", "topluluk": "Topluluğun ekledikleri",
             "dolu": "Konusu olanlar"}


def kategori_adi(ad):
    ad = " ".join((ad or "").split())
    if not 2 <= len(ad) <= 40:
        raise KuralHatasi("Kategori adı 2–40 karakter olmalı.")
    return ad


def kardes_var_mi(db, ad, ust_id, haric_id=None):
    """Aynı üst kategori altında aynı adda (büyük/küçük harf fark etmeden) başka bir kategori var mı?"""
    return db.execute("SELECT 1 FROM kategoriler WHERE ad = ? COLLATE NOCASE AND ust_id IS ? AND id IS NOT ?",
                      (ad, ust_id, haric_id)).fetchone()


def ust_kategori(db, ust_id):
    """Alt kategori eklenecek üst kategoriyi doğrular. Topluluk önerisi de yönetici eklemesi de bu kuralı kullanır."""
    ust_id = tamsayi(ust_id, "Alt kategori yalnızca bir ana kategorinin altına eklenebilir.")
    if not ust_id:
        return None
    ust = ontoloji.dugum(db, "kategoriler", ust_id)
    if not ust or ust["ust_id"] is not None:
        raise KuralHatasi("Alt kategori yalnızca bir ana kategorinin altına eklenebilir.")
    if ust["ad"] == ayarlar.GENEL_KATEGORI:
        raise KuralHatasi("Genel kategorinin alt kategorisi olmaz; yeni bir ana kategori öner.")
    return ust


def _kavramlar(metin):
    terimler = []
    for t in (metin or "").split(","):
        t = ontoloji.katla(" ".join(t.split()))
        if not t:
            continue
        if not 2 <= len(t) <= 30:
            raise KuralHatasi("Her kavram 2–30 karakter olmalı.")
        if t not in terimler:
            terimler.append(t)
    if len(terimler) > MAX_KAVRAM:
        raise KuralHatasi(f"En fazla {MAX_KAVRAM} kavram yazılabilir.")
    return terimler


def oner(db, kullanici, ad, ust_id, kavramlar, gerekce):
    """Yeni kategori önerisini oylamaya sunar. Döner: oylamanın id'si."""
    if kullanici["yz_mi"]:
        raise KuralHatasi("Yapay zeka hesapları kategori öneremez.")
    ad = kategori_adi(ad)
    ust = ust_kategori(db, ust_id)
    ust_id = ust["id"] if ust else None
    if kardes_var_mi(db, ad, ust_id):
        raise KuralHatasi(f"“{ad}” adında bir kategori zaten var.")
    for t in oylama_suren_oneriler(db):
        veri = json.loads(t["veri"])
        if ontoloji.katla(veri["ad"]) == ontoloji.katla(ad) and veri.get("ust_id") == ust_id:
            raise KuralHatasi("Bu kategori için zaten süren bir oylama var.")
        if t["acan_id"] == kullanici["id"]:
            raise KuralHatasi("Sonucu bekleyen bir kategori önerin var; o sonuçlanınca yenisini önerebilirsin.")
    terimler = _kavramlar(kavramlar)
    gerekce = (gerekce or "").strip()
    if len(gerekce) < 20:
        raise KuralHatasi("Bu kategoriye neden ihtiyaç olduğunu yaz (en az 20 karakter).")
    denetim.mesaj_denetle(db, f"{ad} {gerekce} {' '.join(terimler)}")
    return oylama.teklif_ac(db, "KATEGORI", kullanici["id"], gerekce=gerekce,
                            veri={"ad": ad, "ust_id": ust_id, "kavramlar": terimler})


def oylama_suren_oneriler(db):
    return db.execute("SELECT * FROM teklifler WHERE tip = 'KATEGORI' AND durum = 'ACIK' ORDER BY bitis").fetchall()


def son_oneriler(db, limit=8):
    return db.execute("SELECT * FROM teklifler WHERE tip = 'KATEGORI' AND durum != 'ACIK' ORDER BY id DESC LIMIT ?",
                      (limit,)).fetchall()


def oneri_basligi(db, veri):
    ust = f"{ontoloji.ad(db, 'kategoriler', veri['ust_id'])} › " if veri.get("ust_id") else ""
    return f"{ust}{veri['ad']}"


def ekle(db, teklif):
    """Kabul edilen öneriyi kategori olarak ekler (o arada aynı adda kategori açıldıysa eklemez)."""
    veri = json.loads(teklif["veri"])
    ust_id = veri.get("ust_id")
    if kardes_var_mi(db, veri["ad"], ust_id) or (ust_id and not ontoloji.dugum(db, "kategoriler", ust_id)):
        return None
    yeni = db.execute("INSERT INTO kategoriler (ad, ust_id, kaynak, kavramlar, olusturma) VALUES (?, ?, 'TOPLULUK', ?, ?)",
                      (veri["ad"], ust_id, ",".join(veri.get("kavramlar") or []) or None, zaman.simdi_metin())).lastrowid
    db.onbellek.clear()
    yol = ontoloji.yol_metni(db, "kategoriler", yeni)
    gunluk.kaydet(db, teklif["acan_id"], "YENI_KATEGORI", f"Oylamayla yeni kategori eklendi: {yol}")
    defter.ekle(db, "KATEGORI", {"kategori": yol, "teklif": teklif["id"]})
    bildirimler.gonder(db, teklif["acan_id"], f"Önerdiğin “{yol}” kategorisi kabul edildi ve eklendi.",
                       f"/konular?kategori={yeni}")
    return yeni


# --- Kategoriler sayfası ---

def liste(db, siralama="populer", aranan="", suzgec=""):
    """Her kategori için sayılar; arama, süzme ve sıralama uygulanmış olarak."""
    tum = db.execute("SELECT * FROM kategoriler").fetchall()
    konu = {r["kategori_id"]: r for r in db.execute(
        """SELECT kategori_id, COUNT(*) AS n, SUM(durum IN ('TARTISMA', 'OYLAMA')) AS acik FROM konular
           WHERE silindi = 0 GROUP BY kategori_id""")}
    son = {r["kategori_id"]: r["son"] for r in db.execute(
        """SELECT k.kategori_id, MAX(m.olusturma) AS son FROM mesajlar m JOIN konular k ON k.id = m.konu_id
           WHERE k.silindi = 0 GROUP BY k.kategori_id""")}
    hafta = zaman.metin(zaman.simdi() - timedelta(days=7))
    haftalik = {r["kategori_id"]: r["n"] for r in db.execute(
        """SELECT k.kategori_id, COUNT(*) AS n FROM mesajlar m JOIN konular k ON k.id = m.konu_id
           WHERE k.silindi = 0 AND m.yazar_id IS NOT NULL AND m.olusturma >= ? GROUP BY k.kategori_id""", (hafta,))}
    simdi = zaman.simdi_metin()
    uzman = {}
    for r in db.execute("SELECT kategori_id, COUNT(DISTINCT kullanici_id) AS n FROM uzmanliklar "
                        "WHERE baslangic <= ? AND bitis > ? GROUP BY kategori_id", (simdi, simdi)):
        uzman[r["kategori_id"]] = r["n"]

    def topla(kid, sozluk, alan=None):
        ids = ontoloji.alt_agac(db, "kategoriler", kid)
        return sum(((sozluk[i][alan] or 0) if alan else sozluk[i]) for i in ids if i in sozluk)

    satirlar = []
    for k in tum:
        ids = ontoloji.alt_agac(db, "kategoriler", k["id"])
        satirlar.append({
            "id": k["id"], "ad": k["ad"], "ust_id": k["ust_id"], "yol": ontoloji.yol_metni(db, "kategoriler", k["id"]),
            "renk": ontoloji.kategori_rengi(db, k["id"]), "kaynak": k["kaynak"], "olusturma": k["olusturma"] or "",
            "konu": topla(k["id"], konu, "n"), "acik": topla(k["id"], konu, "acik"), "hafta": topla(k["id"], haftalik),
            "uzman": topla(k["id"], uzman), "son": max([son[i] for i in ids if i in son] or [""]),
            "genel": k["ad"] == ayarlar.GENEL_KATEGORI and k["ust_id"] is None,
            "altlar": [], "kavramlar": ontoloji.kavramlar(dict(k))[:8],
        })
    harita = {s["id"]: s for s in satirlar}
    for s in satirlar:
        if s["ust_id"] in harita:
            harita[s["ust_id"]]["altlar"].append(s)

    aranan = ontoloji.katla((aranan or "").strip())
    if aranan:
        satirlar = [s for s in satirlar if aranan in ontoloji.katla(s["yol"]) or any(aranan in t for t in s["kavramlar"])]
    satirlar = [s for s in satirlar if {"ana": s["ust_id"] is None, "alt": s["ust_id"] is not None,
                                          "topluluk": s["kaynak"] == "TOPLULUK", "dolu": s["konu"] > 0}.get(suzgec, True)]
    anahtar = {"ad": lambda s: ontoloji.tr_sirala(s["yol"]),
               "yeni": lambda s: s["olusturma"],
               "etkin": lambda s: s["son"],
               "populer": lambda s: (s["konu"], s["hafta"])}.get(siralama) or (lambda s: (s["konu"], s["hafta"]))
    satirlar.sort(key=anahtar, reverse=siralama != "ad")
    for s in satirlar:
        s["altlar"].sort(key=lambda a: -a["konu"])
    return satirlar


def ana_kategoriler(db):
    """Öneri formundaki "hangi ana kategorinin altına?" seçenekleri (Genel hariç)."""
    return [(k["id"], k["ad"]) for k in sorted(
        db.execute("SELECT id, ad FROM kategoriler WHERE ust_id IS NULL").fetchall(), key=lambda k: ontoloji.tr_sirala(k["ad"]))
        if k["ad"] != ayarlar.GENEL_KATEGORI]

"""Konunun yaşam döngüsü — GoF **State** deseni.

    TARTISMA ──► OYLAMA (1.–5. tur) ──► KARARA_BAGLANDI
                                   └──► SONUCSUZ
    (kaldırılmamış her durumdan oylamayla) ──► KALDIRILDI   (veritabanında `silindi = 1`)

Her durum bir sınıftır ve "bu durumda ne yapılabilir?" sorusunu kendisi yanıtlar. İzinler ve izin verilen geçişler
buradan okunur; geçişi yapan işlemler (konular.oylamayi_baslat, durum_degistir, konuyu_kaldir) geçiş tablosuna danışır.

Geçişin kendisi durum nesnesinde değil konular.py'de yapılır: geçiş veritabanı, kayıt defteri ve bildirim yazımı
gerektirir. Bunları durum sınıflarına taşımak modüller arasında döngüsel bağımlılık yaratır. Durum nesneleri
"ne yapılabilir ve nereye gidilebilir" bilgisinin tek kaynağıdır.

Durumlar iç durum taşımaz; her biri tek bir paylaşılan nesnedir. `durumu(konu)` bir veritabanı satırına karşılık
gelen durum nesnesini verir.
"""
from . import ayarlar
from .hatalar import KuralHatasi


class GecersizGecis(Exception):
    """Programlama hatası: durum makinesinde tanımlı olmayan bir geçiş istendi (ör. TARTISMA → KARARA_BAGLANDI)."""


class KonuDurumu:
    kod = ""
    yazilabilir = False          # mesaj yazma, yanıtlama, mesaj düzenleme, özet isteme
    kapali = False               # sonuçlanmış: itiraz konusu açılabilir
    okunabilir = True            # içerik ve geçmiş gösterilebilir
    zamanli = False              # süresi dolunca zamanlayıcı bir sonraki aşamaya geçirir (sunumda "Süreyi ilerlet")
    sonrakiler = frozenset()     # izin verilen geçişler

    @property
    def ad(self):
        return ayarlar.KONU_DURUMLARI.get(self.kod, "Kaldırıldı")

    def fikir_yazilabilir(self, konu):
        return False

    def konu_duzenlenebilir(self):
        return False

    def fikir_duzenlenebilir(self):
        return False

    def gecis_dogrula(self, yeni):
        if yeni not in self.sonrakiler:
            raise GecersizGecis(f"{self.kod} → {yeni} geçişi tanımlı değil")

    def __repr__(self):
        return f"<KonuDurumu {self.kod}>"


class Tartisma(KonuDurumu):
    kod = "TARTISMA"
    yazilabilir = True
    zamanli = True
    sonrakiler = frozenset({"OYLAMA", "KALDIRILDI"})

    def fikir_yazilabilir(self, konu):
        return True

    def konu_duzenlenebilir(self):
        return True

    def fikir_duzenlenebilir(self):
        return True


class Oylama(KonuDurumu):
    kod = "OYLAMA"
    yazilabilir = True                                   # oylama sürerken tartışma devam eder
    zamanli = True
    sonrakiler = frozenset({"KARARA_BAGLANDI", "SONUCSUZ", "KALDIRILDI"})

    def fikir_yazilabilir(self, konu):
        return konu["tur"] == 1                          # yeni fikir 1. tur bitene kadar yazılabilir


class KararaBaglandi(KonuDurumu):
    kod = "KARARA_BAGLANDI"
    kapali = True
    sonrakiler = frozenset({"KALDIRILDI"})


class Sonucsuz(KonuDurumu):
    kod = "SONUCSUZ"
    kapali = True
    sonrakiler = frozenset({"KALDIRILDI"})


class Kaldirildi(KonuDurumu):
    """Konu oylamayla kaldırıldı: hiçbir işlem yapılamaz, içerik ve geçmiş gösterilmez."""
    kod = "KALDIRILDI"
    okunabilir = False


DURUMLAR = {d.kod: d for d in (Tartisma(), Oylama(), KararaBaglandi(), Sonucsuz())}
KALDIRILDI = Kaldirildi()


def durumu(konu):
    return KALDIRILDI if konu["silindi"] else DURUMLAR[konu["durum"]]


def onceki_durumlar(yeni):
    """`yeni` duruma geçilebilen durumların kodları (atomik UPDATE'lerin WHERE koşulu bu tablodan kurulur)."""
    return sorted(kod for kod, d in DURUMLAR.items() if yeni in d.sonrakiler)


# --- Korumalar: kural ihlalinde kullanıcıya gösterilecek KuralHatasi ---

def okunabilir_olmali(konu):
    if not durumu(konu).okunabilir:
        raise KuralHatasi("Bu konu kaldırıldı.")


def yazilabilir_olmali(konu):
    d = durumu(konu)
    okunabilir_olmali(konu)
    if not d.yazilabilir:
        raise KuralHatasi("Bu konu kapandı; artık yazılamaz. Karara katılmıyorsan itiraz konusu açabilirsin.")

