_BELIRSIZ_YER_ADLARI = {"bala", "evren", "kiraz", "tire", "konak", "van", "kars", "ordu", "mus", "batman", "urla"}

_TABLOLAR = {"konumlar", "kategoriler"}
_ALFABE = "abcçdefgğhıijklmnoöprsştuüvyz"
_KATLAMA = str.maketrans("çğıöşüâîû", "cgiosuaiu")
DURAK_KELIMELER = set("ve ile bir bu su o da de mi mu icin olsun olarak gibi daha en ne ya ki her cok ama veya "
                      "hem bunu sey nasil neden hangi mi olmali olur ise kadar".split())


# --- Metin yardımcıları ---

def tr_kucuk(metin):
    return metin.replace("I", "ı").replace("İ", "i").lower()


def katla(metin):
    """Türkçe karakterleri katlanmış küçük harf metin: 'İstanbul'da Öğrenci' → 'istanbul'da ogrenci'."""
    return tr_kucuk(metin).translate(_KATLAMA)


def kelimeler(metin):
    return re.findall(r"[a-z0-9]+", katla(metin))


def anlamli_kelimeler(metin):
    return {k for k in kelimeler(metin) if len(k) > 2 and k not in DURAK_KELIMELER}


def tr_sirala(metin):
    """Türk alfabesine göre sıralama anahtarı."""
    return [_ALFABE.index(h) if h in _ALFABE else 100 + ord(h) for h in tr_kucuk(metin)]


def benzerlik_orani(a, b):
    """İki metnin anlamlı kelime kümelerinin Jaccard benzerliği (0–1)."""
    ka, kb = anlamli_kelimeler(a), anlamli_kelimeler(b)
    if not ka or not kb:
        return 0.0
    return len(ka & kb) / len(ka | kb)


# --- Tablolar ---

def yukle(db):
    if not db.execute("SELECT COUNT(*) FROM konumlar").fetchone()[0]:
        ekle = "INSERT INTO konumlar (ad, tur, ust_id) VALUES (?, ?, ?)"
        turkiye = db.execute(ekle, ("Türkiye", "ULKE", None)).lastrowid
        for bolge, iller in BOLGELER.items():
            bolge_id = db.execute(ekle, (bolge, "BOLGE", turkiye)).lastrowid
            for il in iller:
                il_id = db.execute(ekle, (il, "IL", bolge_id)).lastrowid
                for ilce in ILCELER.get(il, []):
                    db.execute(ekle, (ilce, "ILCE", il_id))
    surum = db.execute("SELECT deger FROM site_ayarlari WHERE anahtar = 'kategori_surumu'").fetchone()
    if not surum or surum[0] != KATEGORI_SURUMU:
        _kategori_agacini_kur(db)
        db.execute("INSERT INTO site_ayarlari (anahtar, deger) VALUES ('kategori_surumu', ?) "
                   "ON CONFLICT(anahtar) DO UPDATE SET deger = excluded.deger", (KATEGORI_SURUMU,))
    db.onbellek.clear()


def _kategori_bul(db, ad_, ust_id):
    r = db.execute("SELECT id FROM kategoriler WHERE ad = ? AND ust_id IS ?", (ad_, ust_id)).fetchone()
    return r[0] if r else None


def _kategori_agacini_kur(db):
    """Temel ağacı kurar (eksikleri ekler) ve eski kategorileri yenilerine bağlar. Yönetici ya da topluluk tarafından
    eklenen kategorilere dokunmaz."""
    from . import zaman
    an = zaman.simdi_metin()
    for alan, alt_alanlar in KATEGORILER.items():
        alan_id = _kategori_bul(db, alan, None) or db.execute(
            "INSERT INTO kategoriler (ad, ust_id, kaynak, olusturma) VALUES (?, NULL, 'SISTEM', ?)", (alan, an)).lastrowid
        for alt in alt_alanlar:
            if not _kategori_bul(db, alt, alan_id):
                db.execute("INSERT INTO kategoriler (ad, ust_id, kaynak, olusturma) VALUES (?, ?, 'SISTEM', ?)",
                           (alt, alan_id, an))
    for (eski_ana, eski_alt), (yeni_ana, yeni_alt) in ESKI_KATEGORILER.items():
        eski_ana_id = _kategori_bul(db, eski_ana, None)
        if eski_ana_id is None or eski_alt is None:
            continue
        eski_id = _kategori_bul(db, eski_alt, eski_ana_id)
        yeni_id = _kategori_bul(db, yeni_alt, _kategori_bul(db, yeni_ana, None))
        if eski_id and yeni_id:
            _kategoriyi_birlestir(db, eski_id, yeni_id)
    for eski_ana in {a for a, _ in ESKI_KATEGORILER}:
        eski_ana_id = _kategori_bul(db, eski_ana, None)
        if eski_ana_id is None:
            continue
        hedef_ana, hedef_alt = ESKI_KATEGORILER[(eski_ana, None)]
        hedef_ana_id = _kategori_bul(db, hedef_ana, None)
        # Yöneticinin sonradan eklediği alt kategoriler silinmez, yeni ana kategorinin altına taşınır.
        db.execute("UPDATE kategoriler SET ust_id = ? WHERE ust_id = ?", (hedef_ana_id, eski_ana_id))
        _kategoriyi_birlestir(db, eski_ana_id, _kategori_bul(db, hedef_alt, hedef_ana_id))


def _kategoriyi_birlestir(db, eski_id, yeni_id):
    """eski kategoriye bağlı her şeyi yenisine taşır ve eskisini siler."""
    import json
    if eski_id == yeni_id:
        return
    db.execute("UPDATE konular SET kategori_id = ? WHERE kategori_id = ?", (yeni_id, eski_id))
    db.execute("UPDATE uzmanliklar SET kategori_id = ? WHERE kategori_id = ?", (yeni_id, eski_id))
    db.execute("DELETE FROM devirler WHERE kapsam = 'KATEGORI' AND kapsam_id = ? AND EXISTS (SELECT 1 FROM devirler d "
               "WHERE d.veren_id = devirler.veren_id AND d.kapsam = 'KATEGORI' AND d.kapsam_id = ?)", (eski_id, yeni_id))
    db.execute("UPDATE devirler SET kapsam_id = ? WHERE kapsam = 'KATEGORI' AND kapsam_id = ?", (yeni_id, eski_id))
    for t in db.execute("SELECT id, veri FROM teklifler WHERE veri LIKE '%kategori_id%'").fetchall():
        veri = json.loads(t["veri"] or "{}")
        if veri.get("kategori_id") == eski_id:
            veri["kategori_id"] = yeni_id
            db.execute("UPDATE teklifler SET veri = ? WHERE id = ?", (json.dumps(veri, ensure_ascii=False), t["id"]))
    db.execute("DELETE FROM kategoriler WHERE id = ?", (eski_id,))


def _harita(db, tablo):
    assert tablo in _TABLOLAR
    if tablo not in db.onbellek:
        db.onbellek[tablo] = {r["id"]: dict(r) for r in db.execute(f"SELECT * FROM {tablo}")}
    return db.onbellek[tablo]


def dugum(db, tablo, dugum_id):
    return _harita(db, tablo).get(dugum_id)


def atalar(db, tablo, dugum_id):
    """Kökten düğüme kadar olan id listesi (düğümün kendisi dahil)."""
    harita = _harita(db, tablo)
    yol = []
    while dugum_id is not None:
        yol.append(dugum_id)
        dugum_id = harita[dugum_id]["ust_id"]
    return list(reversed(yol))


def altinda_mi(db, tablo, alt_id, ust_id):
    return ust_id in atalar(db, tablo, alt_id)


def alt_agac(db, tablo, dugum_id):
    return [i for i in _harita(db, tablo) if altinda_mi(db, tablo, i, dugum_id)]


def yol_metni(db, tablo, dugum_id):
    harita = _harita(db, tablo)
    adlar = [harita[i]["ad"] for i in atalar(db, tablo, dugum_id)]
    if tablo == "konumlar" and len(adlar) > 1:
        adlar = adlar[1:]
    return " › ".join(adlar)


def kategori_rengi(db, kategori_id):
    """Alt kategoriler, ana kategorinin rengini alır. Yönetim panelinde seçilen renk önceliklidir."""
    from .ayarlar import KATEGORI_RENKLERI, VARSAYILAN_KATEGORI_RENGI
    kok = _harita(db, "kategoriler")[atalar(db, "kategoriler", kategori_id)[0]]
    return kok.get("renk") or KATEGORI_RENKLERI.get(kok["ad"], VARSAYILAN_KATEGORI_RENGI)


def ad(db, tablo, dugum_id):
    return _harita(db, tablo)[dugum_id]["ad"]


def benzerlik(db, tablo, kullanici_dugum, hedef_dugum):
    """Ontoloji tabanlı uygunluk: ortak en yakın atanın derinliği / hedefin derinliği.
    Hedef Kadıköy iken: Kadıköy 1.0, Beşiktaş 0.67 (aynı il), Bursa 0.33 (aynı bölge), Ankara 0."""
    kullanici_yolu = atalar(db, tablo, kullanici_dugum)
    hedef_yolu = atalar(db, tablo, hedef_dugum)
    ortak = 0
    for a, b in zip(kullanici_yolu, hedef_yolu):
        if a != b:
            break
        ortak += 1
    hedef_derinlik = len(hedef_yolu) - 1
    if hedef_derinlik == 0:
        return 1.0
    return max(0, ortak - 1) / hedef_derinlik


# --- Kavram eşleştirme (yönetmelik denetimi için) ---

def _terim_var_mi(terim, kelime_listesi, katli_metin):
    if " " in terim:
        return terim in katli_metin
    if len(terim) <= 3:
        return terim in kelime_listesi
    return any(k.startswith(terim) for k in kelime_listesi)


def kategori_eslesmeleri(db, metin):
    """{kategori_id: [eşleşen terimler]} — metnin ontolojideki kavramlarla ilişkisi."""
    katli = katla(metin)
    liste = kelimeler(metin)
    sonuc = {}
    for kid, d in _harita(db, "kategoriler").items():
        terimler = [t for t in kavramlar(d) if _terim_var_mi(t, liste, katli)]
        if terimler:
            sonuc[kid] = terimler
    return sonuc


def kavramlar(kategori):
    """Bir kategorinin terimleri: koddaki liste + topluluğun önerirken yazdıkları."""
    ek = [t.strip() for t in (kategori.get("kavramlar") or "").split(",") if t.strip()]
    return KAVRAMLAR.get(kategori["ad"], []) + ek


def genel_mi(db, kategori_id):
    from .ayarlar import GENEL_KATEGORI
    return ad(db, "kategoriler", atalar(db, "kategoriler", kategori_id)[0]) == GENEL_KATEGORI


def kategori_iliskisi(db, metin, kategori_id):
    """Metnin seçilen kategoriyle ilişkisi: kategori, üst ve alt kategorilerin terimleri sayılır."""
    eslesme = kategori_eslesmeleri(db, metin)
    ilgili = set(atalar(db, "kategoriler", kategori_id)) | set(alt_agac(db, "kategoriler", kategori_id))
    terimler = sorted({t for kid in ilgili for t in eslesme.get(kid, [])})
    return terimler, eslesme


def alan_puanlari(db, eslesme):
    """{ana alan id: (eşleşen farklı kavram sayısı, bunlardan alt kategori düzeyinde olanların sayısı)}.
    Aynı kavram iki alt kategoride geçse de (ör. "kampus": Üniversite ve Kampüs Yaşamı) bir kez sayılır."""
    alanlar = {}
    for kid, terimler in eslesme.items():
        yol = atalar(db, "kategoriler", kid)
        tum, alt = alanlar.setdefault(yol[0], (set(), set()))
        tum.update(terimler)
        if len(yol) > 1:
            alt.update(terimler)
    return {kok: (len(tum), len(alt)) for kok, (tum, alt) in alanlar.items()}


def en_uygun_kategori(db, metin):
    """Metne en uygun kategori. Önce ana alan seçilir: alt kategorileriyle birlikte en çok farklı kavramı eşleşen alan;
    eşitlikte alt kategori düzeyinde daha çok eşleşen alan. Sonra o alanın içinde en çok eşleşen, eşitlikte en derindeki
    kategori döner. Her kategori tek başına yarıştırılırsa "belediye meclis toplantıları canlı yayınlansın" metninde
    Siyaset ve Yerel Yönetim birer eşleşmeyle Biyoloji'ye (canlı) eşit kalır ve kazananı sözlük sırası belirlerdi.
    Tam eşitlikte kazananı kategori sırası belirler; bu durumda D3 yalnızca uyarı verir."""
    eslesme = kategori_eslesmeleri(db, metin)
    if not eslesme:
        return None, []
    puanlar = alan_puanlari(db, eslesme)
    kok = max(puanlar, key=puanlar.get)
    kid = max((k for k in eslesme if atalar(db, "kategoriler", k)[0] == kok),
              key=lambda k: (len(eslesme[k]), len(atalar(db, "kategoriler", k))))
    return kid, eslesme[kid]


def metindeki_yerler(db, metin):
    """Metinde geçen il ve ilçe adları → konum id listesi."""
    liste = set(kelimeler(metin))
    bulunan = []
    for kid, d in _harita(db, "konumlar").items():
        if d["tur"] not in ("IL", "ILCE"):
            continue
        adi = katla(d["ad"])
        if adi in _BELIRSIZ_YER_ADLARI:
            continue
        if (" " in adi and adi in katla(metin)) or adi in liste:
            bulunan.append(kid)
    return bulunan


# --- Formlar için seçenek listeleri ---

def il_listesi(db):
    iller = [d for d in _harita(db, "konumlar").values() if d["tur"] == "IL"]
    return sorted(iller, key=lambda d: tr_sirala(d["ad"]))


def ilce_haritasi(db):
    sonuc = {}
    for d in _harita(db, "konumlar").values():
        if d["tur"] == "ILCE":
            sonuc.setdefault(d["ust_id"], []).append({"id": d["id"], "ad": d["ad"]})
    for liste in sonuc.values():
        liste.sort(key=lambda d: tr_sirala(d["ad"]))
    return sonuc


def konum_agaci(db):
    harita = _harita(db, "konumlar")
    cocuklar = {}
    for d in harita.values():
        cocuklar.setdefault(d["ust_id"], []).append(d)
    for liste in cocuklar.values():
        liste.sort(key=lambda d: tr_sirala(d["ad"]))
    kok = cocuklar[None][0]
    return [(bolge, [(il, cocuklar.get(il["id"], [])) for il in cocuklar.get(bolge["id"], [])])
            for bolge in cocuklar.get(kok["id"], [])]


def kategori_listesi(db):
    """Formlardaki seçim listesi: ana kategoriler Türk alfabesine göre, Genel en sonda."""
    from .ayarlar import GENEL_KATEGORI
    liste = [(i, yol_metni(db, "kategoriler", i)) for i in _harita(db, "kategoriler")]
    return sorted(liste, key=lambda x: (x[1].split(" › ")[0] == GENEL_KATEGORI, tr_sirala(x[1])))

"""Şikayet kutusu: üyeler bir mesajı ya da konuyu şikayet eder.

Tek bir şikayet yöneticilere gitmez: aynı içeriği en az SIKAYET_TABANI (varsayılan 3) farklı üye şikayet edince
yöneticilere ulaşır. Böylece tek kişinin keyfî şikayeti yöneticiyi meşgul etmez.

Yönetici şikayeti iki yoldan sonuçlandırır: gizleme/kaldırma oylaması açar (karar yine oylamayla verilir) ya da
yersiz bulup kapatır. Aynı içerik hakkındaki bütün açık şikayetler birlikte sonuçlanır ve şikayet edenlere bildirilir.
"""
from datetime import timedelta

from . import ayarlar, bildirimler, denetim, gunluk, konular, oylama, yonetmelik, zaman
from .hatalar import BulunamadiHatasi, KuralHatasi

TURLER = {"MESAJ": "Mesaj", "KONU": "Konu"}
DURUMLAR = {"ACIK": "Bekliyor", "OYLAMADA": "Oylamaya alındı", "YERSIZ": "Yersiz bulundu"}
GUNLUK_SINIR = 10


def _hedef(db, tur, hedef_id):
    """Döner: (konu, mesaj ya da None). Şikayet edilebilir değilse hata verir."""
    if tur == "MESAJ":
        m = konular.mesaj_getir(db, hedef_id)
        if m["tip"] == "SISTEM" or m["yazar_id"] is None:
            raise KuralHatasi("Sistem mesajları şikayet edilemez.")
        if m["gizli"]:
            raise KuralHatasi("Bu mesaj zaten gizlenmiş.")
        konu = konular.konu_getir(db, m["konu_id"])
    elif tur == "KONU":
        m, konu = None, konular.konu_getir(db, hedef_id)
    else:
        raise KuralHatasi("Geçersiz şikayet türü.")
    if konu["silindi"]:
        raise KuralHatasi("Bu konu kaldırıldı.")
    return konu, m


def sikayet_et(db, kullanici, tur, hedef_id, neden, aciklama=""):
    try:
        hedef_id = int(hedef_id)
    except (TypeError, ValueError):
        raise KuralHatasi("Şikayet edilecek içerik bulunamadı.")
    if kullanici["yz_mi"]:
        raise KuralHatasi("Yapay zeka hesapları şikayet gönderemez.")
    konu, m = _hedef(db, tur, hedef_id)
    sahip_id = m["yazar_id"] if m else konu["sahip_id"]
    if sahip_id == kullanici["id"]:
        raise KuralHatasi("Kendi mesajını şikayet edemezsin; gizletmek istersen gizleme oylaması açabilirsin." if m else
                          "Kendi konunu şikayet edemezsin.")
    if neden not in ayarlar.SILME_NEDENLERI:
        raise KuralHatasi("Bir neden seç.")
    aciklama = (aciklama or "").strip()
    if len(aciklama) > 500:
        raise KuralHatasi("Açıklama en fazla 500 karakter olabilir.")
    if aciklama:
        denetim.mesaj_denetle(db, aciklama)
    if db.execute("SELECT 1 FROM sikayetler WHERE sikayetci_id = ? AND tur = ? AND hedef_id = ? AND durum = 'ACIK'",
                  (kullanici["id"], tur, hedef_id)).fetchone():
        raise KuralHatasi("Bu içerik için bekleyen bir şikayetin zaten var.")
    dun = zaman.metin(zaman.simdi() - timedelta(days=1))
    if db.execute("SELECT COUNT(*) FROM sikayetler WHERE sikayetci_id = ? AND olusturma >= ?",
                  (kullanici["id"], dun)).fetchone()[0] >= GUNLUK_SINIR:
        raise KuralHatasi(f"Bir günde en fazla {GUNLUK_SINIR} şikayet gönderebilirsin.")
    sikayet_id = db.execute(
        "INSERT INTO sikayetler (sikayetci_id, tur, hedef_id, konu_id, neden, aciklama, olusturma) "
        "VALUES (?, ?, ?, ?, ?, ?, ?)",
        (kullanici["id"], tur, hedef_id, konu["id"], neden, aciklama or None, zaman.simdi_metin())).lastrowid
    sayi, taban = sikayetci_sayisi(db, tur, hedef_id), yonetmelik.deger(db, "SIKAYET_TABANI")
    if sayi == taban:                       # taban tam dolduğunda, bir kez
        ne = f"#{hedef_id} numaralı mesaj" if tur == "MESAJ" else f"“{konu['baslik']}” konusu"
        for (yonetici_id,) in db.execute("SELECT id FROM kullanicilar WHERE yonetici_mi = 1").fetchall():
            bildirimler.gonder(db, yonetici_id, f"{sayi} üye şikayet etti: {ne}.", "/yonetim/sikayetler")
    return sikayet_id, max(0, taban - sayi)


def sikayetci_sayisi(db, tur, hedef_id):
    return db.execute("SELECT COUNT(DISTINCT sikayetci_id) FROM sikayetler WHERE tur = ? AND hedef_id = ? "
                      "AND durum = 'ACIK'", (tur, hedef_id)).fetchone()[0]


def acik_sayisi(db):
    """Yöneticilere ulaşmış (tabanı geçmiş) farklı içerik sayısı."""
    taban = yonetmelik.deger(db, "SIKAYET_TABANI")
    return db.execute("""SELECT COUNT(*) FROM (SELECT 1 FROM sikayetler WHERE durum = 'ACIK' GROUP BY tur, hedef_id
                         HAVING COUNT(DISTINCT sikayetci_id) >= ?)""", (taban,)).fetchone()[0]


def liste(db, durum="ACIK"):
    """Şikayetleri içeriğe göre gruplar: her grup bir mesaj ya da konu, içinde o içerik hakkındaki şikayetler."""
    satirlar = db.execute(
        """SELECT s.*, k.takma_ad AS sikayetci, y.takma_ad AS yonetici FROM sikayetler s
           JOIN kullanicilar k ON k.id = s.sikayetci_id LEFT JOIN kullanicilar y ON y.id = s.yonetici_id
           WHERE s.durum = ? ORDER BY s.id DESC LIMIT 300""" if durum == "ACIK" else
        """SELECT s.*, k.takma_ad AS sikayetci, y.takma_ad AS yonetici FROM sikayetler s
           JOIN kullanicilar k ON k.id = s.sikayetci_id LEFT JOIN kullanicilar y ON y.id = s.yonetici_id
           WHERE s.durum != 'ACIK' ORDER BY s.kapanis DESC, s.id DESC LIMIT 100""", (durum,) if durum == "ACIK" else ()
    ).fetchall()
    gruplar = {}
    for s in satirlar:
        anahtar = (s["tur"], s["hedef_id"], s["durum"], s["teklif_id"])
        if anahtar not in gruplar:
            konu = db.execute("SELECT id, baslik, silindi FROM konular WHERE id = ?", (s["konu_id"],)).fetchone()
            mesaj = db.execute(
                "SELECT m.*, u.takma_ad FROM mesajlar m LEFT JOIN kullanicilar u ON u.id = m.yazar_id WHERE m.id = ?",
                (s["hedef_id"],)).fetchone() if s["tur"] == "MESAJ" else None
            suren = None
            if s["durum"] == "ACIK":
                suren = (konular.gizleme_oylamasindaki_mesajlar(db, konu["id"]).get(s["hedef_id"]) if mesaj else
                         (oylama.acik_teklif(db, "KONU_SILME", konu_id=konu["id"]) or {"id": None})["id"])
            gruplar[anahtar] = {"tur": s["tur"], "hedef_id": s["hedef_id"], "konu": konu, "mesaj": mesaj,
                                "durum": s["durum"], "teklif_id": s["teklif_id"], "suren_oylama": suren,
                                "sonuc_notu": s["sonuc_notu"], "yonetici": s["yonetici"], "kapanis": s["kapanis"],
                                "ilk_id": s["id"], "sikayetler": []}
        gruplar[anahtar]["sikayetler"].append(s)
    if durum == "ACIK":                     # tabanın altındaki şikayetler yöneticiye gösterilmez
        taban = yonetmelik.deger(db, "SIKAYET_TABANI")
        return [g for g in gruplar.values() if len({s["sikayetci_id"] for s in g["sikayetler"]}) >= taban]
    return list(gruplar.values())


def _gruptakiler(db, sikayet_id):
    s = db.execute("SELECT * FROM sikayetler WHERE id = ?", (sikayet_id,)).fetchone()
    if not s:
        raise BulunamadiHatasi("Şikayet bulunamadı.")
    if s["durum"] != "ACIK":
        raise KuralHatasi("Bu şikayet zaten sonuçlandı.")
    if sikayetci_sayisi(db, s["tur"], s["hedef_id"]) < yonetmelik.deger(db, "SIKAYET_TABANI"):
        raise KuralHatasi("Bu içerik henüz yeterli sayıda üye tarafından şikayet edilmedi.")
    return s, db.execute("SELECT * FROM sikayetler WHERE tur = ? AND hedef_id = ? AND durum = 'ACIK'",
                         (s["tur"], s["hedef_id"])).fetchall()


def _kapat(db, yonetici, grup, durum, not_metni, teklif_id=None):
    an = zaman.simdi_metin()
    for s in grup:
        db.execute("UPDATE sikayetler SET durum = ?, sonuc_notu = ?, teklif_id = ?, yonetici_id = ?, kapanis = ? "
                   "WHERE id = ?", (durum, not_metni, teklif_id, yonetici["id"], an, s["id"]))


def oylamaya_al(db, yonetici, sikayet_id):
    """Şikayet edilen mesaj için gizleme, konu için kaldırma oylaması açar. Süren oylama varsa ona bağlar."""
    s, grup = _gruptakiler(db, sikayet_id)
    konu, m = _hedef(db, s["tur"], s["hedef_id"])
    aciklama = "; ".join(sorted({x["aciklama"] for x in grup if x["aciklama"]}))[:300]
    if m:
        teklif_id = konular.gizleme_oylamasindaki_mesajlar(db, konu["id"]).get(m["id"])
        if not teklif_id:
            teklif_id = konular.mesaj_silme_teklifi(db, yonetici, [m["id"]], s["neden"],
                                                    f"Şikayet üzerine. {aciklama}".strip(), katilim_denetimi=False)
        ne = f"#{m['id']} numaralı mesaj"
    else:
        t = oylama.acik_teklif(db, "KONU_SILME", konu_id=konu["id"])
        teklif_id = t["id"] if t else konular.kaldirma_teklifi(
            db, yonetici, konu["id"], f"Şikayet üzerine ({s['neden']}). {aciklama}".strip(), katilim_denetimi=False)
        ne = f"“{konu['baslik']}” konusu"
    _kapat(db, yonetici, grup, "OYLAMADA", "Oylamaya alındı", teklif_id)
    gunluk.kaydet(db, yonetici["id"], "SIKAYET", f"{ne} hakkındaki {len(grup)} şikayet oylamaya alındı (#{teklif_id})")
    for sikayetci_id in {x["sikayetci_id"] for x in grup}:
        bildirimler.gonder(db, sikayetci_id, f"Şikayetin üzerine {ne} için oylama açıldı.", f"/oylama/{teklif_id}")
    return teklif_id


def yersiz_bul(db, yonetici, sikayet_id, not_metni):
    s, grup = _gruptakiler(db, sikayet_id)
    not_metni = (not_metni or "").strip()
    if len(not_metni) < 5:
        raise KuralHatasi("Şikayet edene gösterilecek kısa bir not yaz (en az 5 karakter).")
    _kapat(db, yonetici, grup, "YERSIZ", not_metni[:300])
    ne = f"#{s['hedef_id']} numaralı mesaj" if s["tur"] == "MESAJ" else f"#{s['hedef_id']} numaralı konu"
    gunluk.kaydet(db, yonetici["id"], "SIKAYET", f"{ne} hakkındaki {len(grup)} şikayet yersiz bulundu")
    baglanti = f"/konu/{s['konu_id']}" + (f"#m{s['hedef_id']}" if s["tur"] == "MESAJ" else "")
    for sikayetci_id in {x["sikayetci_id"] for x in grup}:
        bildirimler.gonder(db, sikayetci_id, f"Şikayetin incelendi ve yersiz bulundu: {not_metni[:120]}", baglanti)


def kullanicinin_sikayetleri(db, kullanici_id, limit=20):
    return db.execute("SELECT s.*, k.baslik FROM sikayetler s JOIN konular k ON k.id = s.konu_id "
                      "WHERE s.sikayetci_id = ? ORDER BY s.id DESC LIMIT ?", (kullanici_id, limit)).fetchall()

"""Fikir oylaması turunun sonucu: eleme kuralları ve turun sonuçları.

(Evet/Hayır oylamalarının sonucu kendi tür sınıflarındadır: teklif_turleri.py.)
Fikir oylamasında (KARAR) tur bitince eleme kuralları uygulanır:
  1. Yeter sayı yoksa ya da hiç fikir yoksa konu sonuçsuz kapanır.
  2. Bir fikir ezici üstünlük oranına (varsayılan %75) ulaştıysa hemen kabul edilir.
  3. Son turda (5.) en yüksek oranlı fikir kabul edilir; eşitlik varsa konu sonuçsuz kapanır.
  4. Diğer turlarda oranı eleme eşiğinin altında kalan fikirler elenir (1. ve 2. tur %5, 3. tur %10, 4. tur %20).
     Geriye tek fikir kalırsa o kabul edilir; hiç kalmazsa konu sonuçsuz kapanır; birden fazla kalırsa sonraki tur açılır.
Oran = ağırlıklı pay ile kişi payının küçüğü (çekimserler toplamda sayılır); bkz. oylama.sayim.
"""
from dataclasses import dataclass

from . import ayarlar, bildirimler, kararlar, konular, yonetmelik, yz
from .konu_durumlari import durumu
from .metin import yuzde

_HASSASIYET = 1e-9


def ozet(s):
    return (f"ağırlıklı {yuzde(s['agirlik_oran'])}, kişi {yuzde(s['kisi_oran'])}, "
            f"katılım {s['katilan']}/{s['hak_sahibi']}")


# --- Fikir oylaması turu ---

@dataclass(frozen=True)
class TurKarari:
    """Bir turun sonucu ve o turda geçerli olan kurallar. Oylama kapanırken sonuca yazılır; yönetmelik sonradan
    değişse de geçmiş tur kendi kurallarıyla anlatılır."""
    sonuc: str                 # "KABUL" (kalanlar[0] kazandı), "DEVAM" (kalanlar sonraki tura geçti), "SONUCSUZ"
    kalanlar: tuple            # seçenek anahtarları
    elenenler: tuple           # eleme eşiğinin altında kaldığı için elenenler
    aciklama: str
    ezici: float
    eleme: object = None       # bu turun eleme eşiği (son turda None)

    def sozluk(self):
        return {"sonuc": self.sonuc, "kalanlar": list(self.kalanlar), "elenenler": list(self.elenenler),
                "aciklama": self.aciklama, "ezici": self.ezici, "eleme": self.eleme}

    @classmethod
    def sozlukten(cls, d):
        return cls(d["sonuc"], tuple(d["kalanlar"]), tuple(d["elenenler"]), d["aciklama"], d["ezici"], d["eleme"])


def tur_kurallari(db, tur_no):
    """(ezici üstünlük oranı, eleme eşiği) — son turda eleme yoktur."""
    eleme = None if tur_no >= ayarlar.TUR_SAYISI else yonetmelik.deger(db, ayarlar.ELEME_PARAMETRELERI[tur_no])
    return yonetmelik.deger(db, "ESIK_EZICI"), eleme


def tur_karari(tur_no, s, ezici, eleme):
    """Turun sonucunu hesaplayan SAF fonksiyon: yalnızca sayımı (s) ve iki kuralı alır, veritabanına dokunmaz."""
    def karar(sonuc, kalanlar=(), elenenler=(), aciklama=""):
        return TurKarari(sonuc, tuple(f["anahtar"] for f in kalanlar), tuple(f["anahtar"] for f in elenenler),
                         aciklama, ezici, eleme)

    if not s["yeter"]:
        return karar("SONUCSUZ", aciklama=f"yeter sayıya ulaşılamadı (katılım {s['katilan']}, gereken {s['gerekli']})")
    # orana göre büyükten küçüğe sıralı; oylamayla gizlenen fikir yarışmaz (oyları toplamda sayılmaya devam eder)
    fikirler = [f for f in s["secenekler"] if f["kisi"] > 0 and not f.get("gizli")]
    if not s["secenekler"]:
        return karar("SONUCSUZ", aciklama="hiç fikir yazılmadı")
    if not fikirler:
        return karar("SONUCSUZ", aciklama="hiçbir fikir oy alamadı")
    if fikirler[0]["oran"] + _HASSASIYET >= ezici:
        return karar("KABUL", fikirler[:1], aciklama=f"ezici üstünlük ({yuzde(fikirler[0]['oran'])})")
    if eleme is None:                                   # son tur: en çok oy alan kazanır
        if len(fikirler) > 1 and abs(fikirler[0]["oran"] - fikirler[1]["oran"]) < _HASSASIYET:
            return karar("SONUCSUZ", aciklama="son turda eşitlik çıktı")
        return karar("KABUL", fikirler[:1], aciklama=f"son turda en çok oyu aldı ({yuzde(fikirler[0]['oran'])})")
    kalanlar = [f for f in fikirler if f["oran"] + _HASSASIYET >= eleme]
    elenenler = [f for f in s["secenekler"] if f not in kalanlar and not f.get("gizli")]
    if not kalanlar:
        return karar("SONUCSUZ", elenenler=elenenler, aciklama=f"hiçbir fikir {yuzde(eleme)} eşiğini geçemedi")
    if len(kalanlar) == 1:
        return karar("KABUL", kalanlar, elenenler, f"eşiği geçen tek fikir ({yuzde(kalanlar[0]['oran'])})")
    return karar("DEVAM", kalanlar, elenenler,
                 f"{yuzde(eleme)} altında kalan {len(elenenler)} fikir elendi" if elenenler else
                 f"bütün fikirler {yuzde(eleme)} eşiğini geçti, elenen olmadı")


def tur_sonucu(db, t, s):
    """Kapanan turun kararı: kapanışta yazılmış anlık görüntü; yoksa (eski kayıt) bugünkü kurallarla hesaplanır."""
    if s.get("tur"):
        return TurKarari.sozlukten(s["tur"])
    return tur_karari(t["tur_no"], s, *tur_kurallari(db, t["tur_no"]))


def tur_uygula(db, t, s):
    """Tur bitince: karar (konu kapanır), sonraki tur ya da sonuçsuz kapanış; sonra yapay zeka tur özeti."""
    konu_id, tur_no = t["konu_id"], t["tur_no"]
    konu = konular.konu_getir(db, konu_id)
    if durumu(konu).kod != "OYLAMA":
        return
    k = tur_sonucu(db, t, s)
    secenek = {f["anahtar"]: f for f in s["secenekler"]}
    fikirler = [secenek[a] for a in k.kalanlar]
    katilim = f"katılım {s['katilan']}/{s['hak_sahibi']}"
    alicilar = bildirimler.konu_katilimcilari(db, konu_id) | {
        r["kullanici_id"] for r in db.execute("SELECT kullanici_id FROM oylar WHERE teklif_id = ?", (t["id"],))}
    baglanti = f"/konu/{konu_id}"
    if k.sonuc == "KABUL":
        kazanan = fikirler[0]
        kararlar.olustur(db, konu_id, t["id"], int(kazanan["anahtar"]), kazanan["metin"])
        konular.kapat(db, konu_id, "KARARA_BAGLANDI")
        konular.sistem_mesaji(db, konu_id, f"Karar: “{kazanan['metin']}”. {tur_no}. turda {k.aciklama}; {katilim}. "
                                           "Konu kapandı. Karara katılmayanlar itiraz konusu açabilir.")
        bildirimler.coklu_gonder(db, alicilar, f"Karar çıktı: “{kazanan['metin']}”", baglanti)
    elif k.sonuc == "DEVAM":
        konular.sonraki_tur(db, konu_id, tur_no + 1, [(f["metin"], f["mesaj_id"]) for f in fikirler])
        konular.sistem_mesaji(db, konu_id, f"{tur_no}. tur bitti: {k.aciklama}; {katilim}. {len(fikirler)} fikirle "
                                           f"{tur_no + 1}. tur başladı.")
    else:
        konular.kapat(db, konu_id, "SONUCSUZ")
        konular.sistem_mesaji(db, konu_id, f"Konu sonuçsuz kapandı: {tur_no}. turda {k.aciklama}. "
                                           "İsteyen yeni bir konu açabilir.")
        bildirimler.coklu_gonder(db, alicilar, f"Konu sonuçsuz kapandı: {konu['baslik']}", baglanti)
    yz.tur_ozeti(db, konu_id, tur_no, s, k)

// Forum arayüz yardımcıları. Satır içi betik yok (içerik güvenlik politikası: script-src 'self').
(function () {
