      }).then(function (y) { return y.json().then(function (j) { return { ok: y.ok, j: j }; }); })
        .then(function (s) { goster(kutu, s.ok ? s.j : null, s.ok ? null : s.j.hata); })
        .catch(function () { goster(kutu, null, "Denetim yapılamadı; bağlantını kontrol et."); })
