{% macro kategori_cipi(kategori_id) -%}
  <a class="kategori-cipi" href="{{ url_for('konular.ana_sayfa', kategori=kategori_id) }}"><span class="kat-nokta" style="background: {{ kategori_id|kategori_rengi }}"></span>{{ kategori_id|kategori }}</a>
