{% extends "base.html" %}
{% from "_makrolar.html" import konu_durumu, kategori_cipi, asama_noktalari, sayfa_gezgini, trend_listesi, kelime_bulutu, nabiz_satiri, yakinda_listesi, konu_sekmeleri %}
{% block baslik %}{{ kategori|kategori if kategori else 'Konular' }}{% endblock %}
{% block icerik %}
{% if not kullanici %}
<a class="gundem-seridi tanitim-seridi" href="{{ url_for('konular.acilis') }}">
  <span>{{ ikon('meclis') }} Forumda yeni misin? Konuların nasıl karara dönüştüğü tanıtım sayfasında.</span><strong>Tanıtıma git →</strong>
</a>
{% endif %}

{#- Vitrin: gündemdeki konu, bitmek üzere olan oylama ve son karar -#}
{% if sayfalama.sayfa == 1 and not kategori and filtre == 'tumu' %}
<div class="vitrin">
  {% set t = yan.trend[0] if yan.trend else None %}
  {% if t %}
  <a class="vitrin-karti vurgu" href="{{ url_for('konular.konu', konu_id=t.id) }}">
    <span class="vk-ust">{{ ikon('ates') }} Şu an gündemde</span>
    <strong>{{ t.baslik }}</strong>
    <span class="vk-alt">{{ t.mesaj }} mesaj · {{ t.kisi }} kişi {{ 'son 24 saatte' if yan.trend_saat == 24 else 'son günlerde' }}</span>
  </a>
  {% endif %}
  {% set y = (yan.yakinda|rejectattr('baglanti', 'equalto', '/konu/' ~ t.id)|first) if t else (yan.yakinda|first) %}
  {% if y %}
  <a class="vitrin-karti" href="{{ y.baglanti|site_yolu }}">
    <span class="vk-ust">{{ ikon('kum_saati') }} {{ 'Oylama bitiyor' if y.tur == 'OYLAMA' else 'Oylamaya geçiyor' }}</span>
    <strong>{{ y.baslik }}</strong>
    <span class="vk-alt">{{ y.bitis|kalan }}</span>
  </a>
  {% endif %}
  {% if son_karar %}
  <a class="vitrin-karti" href="{{ url_for('konular.konu', konu_id=son_karar.konu_id, _anchor='karar') }}">
    <span class="vk-ust">{{ ikon('karar') }} Son karar</span>
    <strong>“{{ son_karar.metin }}”</strong>
    <span class="vk-alt">{{ son_karar.baslik }}</span>
  </a>
  {% endif %}
</div>
{% endif %}

{{ konu_sekmeleri('konular.ana_sayfa') }}

<div class="iki-panel">
<div class="ana">
{% set filtre_adi = dict(filtreler).get(filtre, 'Tümü') %}
<div class="sayfa-bas">
  <div>
    <h1>{% if kategori %}<span class="kat-nokta buyuk" style="background: {{ kategori|kategori_rengi }}"></span>{{ kategori|kategori }}{% else %}Konular{% endif %}</h1>
    <p class="soluk kucuk">{{ sayfalama.toplam }} konu · son etkinliğe göre</p>
  </div>
  <details class="acilir-filtre">
    <summary class="cip">{{ ikon('ayar') }} {{ filtre_adi }} ▾</summary>
    <div class="acilir">
      {% for deger, ad in filtreler %}
        {% if deger not in ('katilabildiklerim', 'gozlemci') or kullanici %}
        <a class="{{ 'secili' if filtre == deger }}" href="{{ url_for('konular.ana_sayfa', filtre=deger, kategori=kategori) }}">{{ ad }}</a>
        {% endif %}
      {% endfor %}
    </div>
  </details>
</div>

<nav class="cipler" aria-label="Kategoriler">
  <a class="cip {{ 'secili' if not kategori }}" href="{{ url_for('konular.ana_sayfa', filtre=filtre) }}">Tümü</a>
  {% for kat in yan_kategoriler %}
    <a class="cip {{ 'secili' if kok_kategori == kat.id }}" href="{{ url_for('konular.ana_sayfa', kategori=kat.id, filtre=filtre) }}">
      <span class="kat-nokta" style="background: {{ kat.renk }}"></span>{{ kat.ad }}{% if kat.sayi %} <small class="cip-sayi">{{ kat.sayi }}</small>{% endif %}</a>
  {% endfor %}
  <a class="cip ince-cip" href="{{ url_for('konular.kategori_sayfasi') }}">{{ ikon('izgara') }} Tüm kategoriler</a>
</nav>
{% if alt_kategoriler %}
<nav class="cipler alt-cipler" aria-label="Alt kategoriler">
  {% for id, yol in alt_kategoriler %}<a class="cip" href="{{ url_for('konular.ana_sayfa', kategori=id, filtre=filtre) }}">{{ yol.split(' › ')[-1] }}</a>{% endfor %}
</nav>
{% endif %}
{% if kategori and (kategori|kategori) == ayarlar.GENEL_KATEGORI %}
<div class="uyari bilgi">{{ ikon('bilgi') }} <span><strong>Genel</strong> her konuya açık. Yeni bir kategoriye ihtiyaç mı var?
  Burada tartış, sonra <a href="{{ url_for('konular.kategori_sayfasi', _anchor='oner') }}">Kategoriler sayfasından öner</a>; bütün üyeler oylar.</span></div>
{% endif %}

{% if bekleyen_oy or istatistik.oylama %}
<a class="gundem-seridi" href="{{ url_for('oylamalar.gundem') }}">
  <span>{{ ikon('oy') }} {% if bekleyen_oy %}{{ bekleyen_oy }} oylama oyunu bekliyor{% else %}{{ istatistik.oylama }} oylama sürüyor{% endif %}</span>
  <strong>{{ 'Oy ver' if bekleyen_oy else 'Gündeme git' }} →</strong>
</a>
{% endif %}

<div class="konu-akisi">
  {% for s in satirlar %}{% set k = s.konu %}
    <article class="konu-karti {{ 'soluk-kart' if k.durum == 'SONUCSUZ' }}">
      <div class="kk-ana">
        <a class="konu-baslik" href="{{ url_for('konular.konu', konu_id=k.id) }}">{{ k.baslik }}</a>
        <div class="konu-etiketler">
          {{ kategori_cipi(k.kategori_id) }}
          {{ konu_durumu(k.durum) }}{% if k.durum == 'OYLAMA' %}<span class="rozet oylama-var">{{ ikon('oy') }} {{ k.tur }}. tur</span>{% endif %}
          {% if k.id in gundemdekiler %}<span class="rozet gundemde">{{ ikon('ates') }} Gündemde</span>{% endif %}
          {% if k.itiraz_id %}<span class="rozet">{{ ikon('yanit') }} İtiraz</span>{% endif %}
          {% if s.kural != 'Herkese açık' %}<span class="kural kisitli" title="Katılım kuralı">{{ ikon('konum') }}{{ s.kural }}</span>{% endif %}
          {% if kullanici and not s.uygunluk.katilimci %}<span class="rozet gozlemci" title="Katılım kuralını sağlamıyorsun">Gözlemci</span>{% endif %}
          <span class="soluk kucuk">{{ k.mesaj_sayisi }} yanıt · {{ k.fikir_sayisi }} fikir{% if k.alt_sayisi %} · {{ k.alt_sayisi }} alt konu{% endif %} ·
            <span title="{{ k.son_etkinlik|tarih }}">{{ k.son_etkinlik|once }}</span></span>
        </div>
      </div>
      {{ asama_noktalari(k) }}
    </article>
  {% else %}
    <p class="bos-durum">Bu filtreye uyan konu yok.{% if kullanici %} <a href="{{ url_for('konular.konu_yeni') }}">İlk konuyu sen aç →</a>{% endif %}</p>
  {% endfor %}
</div>
{{ sayfa_gezgini(sayfalama, 'konular.ana_sayfa', request.args.to_dict()) }}
</div>

<aside class="yan gundem-yan" aria-label="Gündem">
  <section class="kart">
    <h3>{{ ikon('ates') }} Trend konular</h3>
    {{ trend_listesi(yan.trend, yan.trend_saat) }}
  </section>
  <section class="kart">
    <h3>{{ ikon('etiket') }} Öne çıkan kelimeler</h3>
    {{ kelime_bulutu(yan.kelimeler) }}
  </section>
  <section class="kart">
    <h3>{{ ikon('kum_saati') }} Yakında bitenler</h3>
    {{ yakinda_listesi(yan.yakinda) }}
  </section>
  <section class="kart">
    <h3>{{ ikon('nabiz') }} Kategorilerin nabzı <small class="soluk">bu hafta</small></h3>
    {% for n in yan.nabiz %}{{ nabiz_satiri(n) }}{% endfor %}
    <a class="kucuk" href="{{ url_for('konular.kesfet') }}">Hepsini Keşfet'te gör →</a>
  </section>
</aside>
</div>
{% endblock %}

{% extends "base.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}@{{ k.takma_ad }}{% endblock %}
{% block icerik %}
<section class="kart orta profil-bas">
  <img class="avatar buyuk-avatar" src="{{ avatar(k.takma_ad, k.yz_mi) }}" alt="">
  <div>
    <h1>@{{ k.takma_ad }} {% if k.yz_mi %}<span class="rozet yz">Yapay zeka</span>{% endif %}
      {% for u in uzmanliklar %}<span class="rozet agirlik">Uzman: {{ u.kategori_id|kategori }}</span>{% endfor %}</h1>
    <p class="soluk">Üyelik: {{ k.olusturma|gun }} · {{ takipci }} takipçi · {{ takip }} takip</p>
    <p class="kucuk">Etki puanı: <strong>{{ etki }}</strong> · Devirle taşıdığı oy: <strong>{{ guc }}</strong>
      {% if grup %} · <span class="grup-rengi" style="background: {{ grup.renk }}"></span>{{ grup.ad }}{% endif %}</p>
    {% if kullanici and kullanici.id != k.id %}
      <form method="post" action="{{ url_for('profil.takip_et', takma_ad=k.takma_ad) }}">{{ csrf() }}
        <button class="dugme {{ 'ince' if takip_ediyor }}">{{ 'Takibi bırak' if takip_ediyor else '+ Takip et' }}</button></form>
    {% endif %}
  </div>
</section>
{% if k.yz_mi %}
<section class="kart orta">
  <p>Bu hesap bir yapay zeka. Yalnızca kısa özetler yazar: tartışmaları ve tur sonuçlarını özetler. Oy kullanmaz, fikir yazmaz.</p>
  {% if aday_oylamasi %}
    <p>Bu hesap için süren bir uzmanlık oylaması var. <a href="{{ url_for('oylamalar.teklif', teklif_id=aday_oylamasi.id) }}">Oylamayı gör →</a></p>
  {% elif kullanici and not kullanici.yz_mi %}
    <details><summary class="dugme ince">Uzmanlığa aday göster</summary>
      <form method="post" action="{{ url_for('profil.uzmanlik_basvurusu') }}" class="form">{{ csrf() }}
        <input type="hidden" name="aday" value="{{ k.id }}">
        <p class="soluk kucuk">Yapay zeka hesapları da üyelerle aynı ön şartları sağlamalı ve aynı oylamadan geçmelidir.</p>
        <label>Alan <select name="kategori_id">{% for id, ad in kategoriler %}<option value="{{ id }}">{{ ad }}</option>{% endfor %}</select></label>
        <label>Gerekçe <textarea name="gerekce" rows="2" minlength="20" required placeholder="Bu alanda neden uzman sayılmalı?"></textarea></label>
        <div><button class="dugme ince">Aday göster ve oylamaya sun</button></div></form></details>
  {% endif %}
</section>
{% endif %}

{% if acik_oylar %}
<section class="kart orta">
  <h2>Uzman olarak verdiği oylar</h2>
  <p class="soluk kucuk">Uzman oyları, oylama bittikten sonra gerekçeleriyle birlikte görünür.</p>
  {% for o in acik_oylar %}
    <div class="surum"><p><a href="{{ url_for('oylamalar.teklif', teklif_id=o.teklif_no) }}">{{ basliklar(o.teklif_no) }}</a> <span class="rozet agirlik">{{ o.agirlik }} oy</span></p>
      {% if o.gerekce %}<div class="gerekce">{{ o.gerekce }}</div>{% endif %}</div>
  {% endfor %}
</section>
{% endif %}

<section class="kart orta">
  <h2>Son mesajları</h2>
  {% for m in son_mesajlar %}
    <p><a href="{{ url_for('konular.konu', konu_id=m.konu_id, _anchor='m' ~ m.id) }}">{{ m.baslik }}</a> <span class="rozet mtip">{{ ayarlar.MESAJ_TIPLERI[m.tip] }}</span><br>
      <span class="soluk">{{ m.icerik|truncate(160) }}</span></p>
  {% else %}<p class="soluk">Henüz mesajı yok.</p>{% endfor %}
</section>
{% endblock %}

