{% extends "base.html" %}
{% block baslik %}Mesaj geçmişi{% endblock %}
{% block icerik %}
<section class="kart orta">
  <p class="soluk"><a href="{{ url_for('konular.konu', konu_id=mesaj.konu_id, _anchor='m' ~ mesaj.id) }}">← Konuya dön</a></p>
  <h1>#{{ mesaj.id }} numaralı mesajın geçmişi</h1>
  <div class="surum guncel">
    <p class="soluk kucuk">Güncel hali ({{ mesaj.duzenleme|tarih }})</p>
    <div class="icerik">{{ mesaj.icerik|bicimle }}</div>
  </div>
  {% for s in surumler|reverse %}
    <div class="surum">
      <p class="soluk kucuk">{{ s.tarih|tarih }} tarihine kadarki hali</p>
      <div class="icerik">{{ s.icerik|bicimle }}</div>
    </div>
  {% endfor %}
</section>
{% endblock %}

{% extends "base.html" %}
{#- Panelim: üyenin kendi hesabı. Solda bölüm menüsü (telefonda üstte kaydırılabilir şerit), sağda sayfa. -#}
{% block icerik %}
{% set menu = [('profil.profil', 'Özet', 'pano'), ('profil.bildirim_listesi', 'Bildirimler', 'zil'),
               ('profil.hesap', 'Hesap bilgileri', 'kisiler'), ('profil.devir_sayfasi', 'Oy devri', 'oy'),
               ('profil.uzmanlik_sayfasi', 'Uzmanlık', 'makbuz'), ('profil.guvenlik_sayfasi', 'Güvenlik', 'kilit'),
               ('profil.uygulama', 'Uygulama ve API', 'telefon')] %}
{% set ep = request.endpoint %}
<div class="panel-kabugu">
  <nav class="panel-menu" aria-label="Panelim">
    <a class="pm-kim" href="{{ url_for('profil.kullanici', takma_ad=kullanici.takma_ad) }}">
      <img class="avatar" src="{{ avatar(kullanici.takma_ad) }}" alt=""><span>@{{ kullanici.takma_ad }}<small>Herkese açık profilim</small></span></a>
    {% for e, ad, ik in menu %}
      <a class="{{ 'secili' if ep == e }}" {{ 'aria-current=page' if ep == e }} href="{{ url_for(e) }}">{{ ikon(ik) }}<span>{{ ad }}</span>
        {% if e == 'profil.bildirim_listesi' and okunmamis %}<span class="sayac">{{ okunmamis }}</span>{% endif %}</a>
    {% endfor %}
  </nav>
  <div class="panel-icerik">{% block panel %}{% endblock %}</div>
</div>
{% endblock %}

{% extends "panel/_kabuk.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}Güvenlik{% endblock %}
{% block panel %}
<section class="kart">
  <h1>Güvenlik</h1>
  <h2>Şifre değiştir</h2>
  <form method="post" action="{{ url_for('profil.sifre') }}" class="form dar-form">{{ csrf() }}
    <label>Mevcut şifre <input type="password" name="eski" required autocomplete="current-password"></label>
    <label>Yeni şifre <small>En az {{ ayarlar.SIFRE_MIN }} karakter; harf ve rakam içermeli.</small>
      <input type="password" name="yeni" minlength="{{ ayarlar.SIFRE_MIN }}" required autocomplete="new-password"></label>
    <label>Yeni şifre (tekrar) <input type="password" name="yeni_tekrar" minlength="{{ ayarlar.SIFRE_MIN }}" required autocomplete="new-password"></label>
    <div><button class="dugme ince">Şifreyi değiştir</button></div></form>
</section>
<section class="kart">
  <h2>Kurtarma kodu</h2>
  <p class="soluk">Şifreni unutursan kurtarma koduyla yeni şifre belirlersin. Kodu kaybettiysen yenisini üret; eski kod geçersiz olur.</p>
  <form method="post" action="{{ url_for('profil.kurtarma') }}" class="form dar-form">{{ csrf() }}
    <label>Şifren <input type="password" name="sifre" required autocomplete="current-password"></label>
    <div><button class="dugme ince">Yeni kod üret</button></div></form>
</section>
{% endblock %}

{% extends "panel/_kabuk.html" %}
{% from "_makrolar.html" import konu_durumu %}
{% block baslik %}Panelim{% endblock %}
{% block panel %}
<section class="kart profil-bas">
  <img class="avatar buyuk-avatar" src="{{ avatar(ben.takma_ad) }}" alt="">
  <div>
    <h1>Merhaba, @{{ ben.takma_ad }} {% if ben.yonetici_mi %}<span class="rozet durum-karara_baglandi">Yönetici</span>{% endif %}</h1>
    <p class="soluk">Üyeliğin {{ ben.olusturma|gun }} tarihinden beri · {{ takipci }} takipçi · {{ takip }} takip</p>
  </div>
</section>

{% if askida %}
  <p class="uyari hata">{{ ikon('duraklat') }} Hesabın {{ ben.askida_bitis|tarih }} tarihine kadar askıda. Bu sürede okuyabilirsin ama yazamaz ve oy veremezsin.
    Neden: {{ ben.askida_neden }}</p>
{% endif %}

<div class="stat-izgara dortlu">
  <a class="stat" href="{{ url_for('oylamalar.gundem') }}"><span>Oyunu bekleyen</span><strong>{{ bekleyen|length }}</strong><small>oylama</small></a>
  <div class="stat"><span>Mesaj</span><strong>{{ sayilar.mesaj }}</strong><small>{{ sayilar.fikir }} fikir</small></div>
  <div class="stat"><span>Verdiğin oy</span><strong>{{ sayilar.oy }}</strong><small>makbuzla doğrulanabilir</small></div>
  <a class="stat" href="{{ url_for('profil.bildirim_listesi') }}"><span>Okunmamış</span><strong>{{ okunmamis }}</strong><small>bildirim</small></a>
</div>

<div class="pano-izgara">
  <section class="kart">
    <h2>{{ ikon('oy') }} Oyunu bekleyenler</h2>
    {% for x in bekleyen %}
      <p class="is-satiri"><a href="{{ url_for('oylamalar.teklif', teklif_id=x.teklif.id) }}">{{ x.baslik }}</a>
        <span class="soluk kucuk">{{ x.teklif.bitis|kalan }}</span></p>
    {% else %}<p class="soluk">Oyunu bekleyen oylama yok.</p>{% endfor %}
    {% if oy_verdigim %}
      <h3>Oy verdiklerin (sürüyor)</h3>
      {% for x in oy_verdigim %}
        <p class="is-satiri"><a href="{{ url_for('oylamalar.teklif', teklif_id=x.teklif.id) }}">{{ x.baslik }}</a>
          <span class="soluk kucuk">{{ x.teklif.bitis|kalan }}</span></p>
      {% endfor %}
    {% endif %}
  </section>
  <section class="kart">
    <h2>{{ ikon('belge') }} Açtığın konular</h2>
    {% for k in konularim %}
      <p class="is-satiri"><a href="{{ url_for('konular.konu', konu_id=k.id) }}">{{ k.baslik }}</a> {{ konu_durumu(k.durum) }}</p>
    {% else %}<p class="soluk">Henüz konu açmadın. <a href="{{ url_for('konular.konu_yeni') }}">Konu aç →</a></p>{% endfor %}
  </section>
</div>

<section class="kart">
  <h2>{{ ikon('sohbet') }} Son mesajların</h2>
  <ul class="olay-listesi">
    {% for m in mesajlarim %}
      <li><a href="{{ url_for('konular.konu', konu_id=m.konu_id, _anchor='m' ~ m.id) }}">{{ m.baslik }}</a>
        <span class="soluk kucuk">· {{ m.olusturma|once }}{% if m.gizli %} · gizlendi{% endif %}</span><br>
        <span class="kucuk">{{ m.icerik|truncate(140) }}</span></li>
    {% else %}<li class="soluk">Henüz mesaj yazmadın.</li>{% endfor %}
  </ul>
</section>
{% if sikayetlerim %}
<section class="kart">
  <h2>{{ ikon('bayrak') }} Şikayetlerin</h2>
  {% for s in sikayetlerim %}
    <p class="is-satiri"><span><a href="{{ url_for('konular.konu', konu_id=s.konu_id, _anchor=('m' ~ s.hedef_id) if s.tur == 'MESAJ' else None) }}">{{ '#' ~ s.hedef_id ~ ' numaralı mesaj' if s.tur == 'MESAJ' else s.baslik }}</a>
      <span class="soluk kucuk">· {{ s.neden }} · {{ s.olusturma|once }}{% if s.sonuc_notu and s.durum == 'YERSIZ' %} · {{ s.sonuc_notu }}{% endif %}</span></span>
      {% if s.durum == 'OYLAMADA' %}<a class="rozet durum-oylama" href="{{ url_for('oylamalar.teklif', teklif_id=s.teklif_id) }}">{{ sikayet_durumlari[s.durum] }}</a>
      {% else %}<span class="rozet {{ 'durum-sonucsuz' if s.durum == 'YERSIZ' else 'durum-tartisma' }}">{{ sikayet_durumlari[s.durum] }}</span>{% endif %}</p>
  {% endfor %}
</section>
{% endif %}
{% endblock %}

{% extends "panel/_kabuk.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}Uygulama ve API{% endblock %}
{% block panel %}
<section class="kart">
  <h1>{{ ikon('telefon') }} Mobil uygulama</h1>
  {% if mobil_uygulama %}
    <p class="uyari basari">{{ ikon('tik') }} Şu an {{ ayarlar.SITE_ADI }} uygulamasındasın. Web sitesiyle aynı hesabı ve aynı içeriği kullanır.</p>
    <p><a class="dugme ince kucuk-dugme" href="{{ request.script_root }}/uygulama/adres" target="_top">{{ ikon('sunucu') }} Sunucu adresini değiştir</a></p>
  {% else %}
    <p>Telefonda üç yoldan kullanabilirsin; hepsi web sitesiyle aynı hesabı ve aynı içeriği kullanır.</p>
    <ul>
      <li><strong>Expo Go ile:</strong> telefona Expo Go'yu kur, bilgisayarda <code>mobil-expo</code> klasöründe <code>npx expo start</code> çalıştır ve ekrandaki QR kodu okut. Adımlar <code>mobil-expo/BENIOKU.md</code> dosyasında.</li>
      <li><strong>Android uygulaması:</strong> proje klasöründeki <code>mobil</code> klasöründen APK olarak derlenir. Adımlar <code>mobil/BENIOKU.md</code> dosyasında.</li>
      <li><strong>Ana ekrana ekle:</strong> telefonun tarayıcısında siteyi açıp menüden “Ana ekrana ekle”yi seç. iPhone'da Safari'nin paylaş menüsündedir.</li>
    </ul>
    <p><button type="button" class="dugme ince gizle" data-uygulama-kur>{{ ikon('indir') }} Bu cihaza kur</button></p>
  {% endif %}
</section>
<section class="kart" id="api">
  <h2>{{ ikon('anahtar') }} API anahtarları</h2>
  <p class="soluk">Forumu kendi programından kullanmak için anahtar oluştur (<a href="{{ url_for('genel.api_belgeleri') }}">API belgeleri</a>).
    Bir cihazın erişimini kesmek için o cihazın anahtarını sil.</p>
  {% if yeni_anahtar %}
    <div class="uyari basari">Yeni anahtarın (bir daha gösterilmez): <code id="anahtar">{{ yeni_anahtar }}</code>
      <button type="button" class="dugme ince kucuk-dugme" data-kopyala="#anahtar">Kopyala</button></div>
  {% endif %}
  {% for a in api_anahtarlari %}
    <p class="is-satiri"><span>{{ ikon('anahtar') }} {{ a.ad }} <span class="soluk kucuk">oluşturma {{ a.olusturma|gun }}{% if a.son_kullanim %} · son kullanım {{ a.son_kullanim|tarih }}{% endif %}</span></span>
      <form method="post" action="{{ url_for('profil.api_anahtari_sil', anahtar_id=a.id) }}" class="satir-ici">{{ csrf() }}<button class="bag tehlike">sil</button></form></p>
  {% else %}<p class="soluk">Anahtarın yok.</p>{% endfor %}
  <form method="post" action="{{ url_for('profil.api_anahtari') }}" class="satir-form">{{ csrf() }}
    <input name="ad" placeholder="Anahtar adı (ör. Telefonum)" maxlength="40" aria-label="Anahtar adı"><button class="dugme ince">Anahtar oluştur</button>
  </form>
</section>
{% endblock %}

{% extends "panel/_kabuk.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}Uzmanlık{% endblock %}
{% block panel %}
<section class="kart">
  <h1>Uzmanlık</h1>
  <p class="soluk">Uzmanın, kendi alanındaki fikir oylamalarında oyu {{ parametre('UZMAN_AGIRLIK') }} sayılır. Uzmanın oyu herkesçe görülür ve bir gerekçeyle birlikte verilir.
    Uzmanlık {{ parametre('UZMAN_SURE_GUN') }} gün sürer. Yöneticiler uzman atayamaz; uzmanlık yalnızca oylamayla verilir.</p>
  {% for u in uzmanliklar %}
    <p class="is-satiri"><span>{{ u.kategori_id|kategori }}<br><span class="soluk kucuk">{{ u.baslangic|gun }} – {{ u.bitis|gun }}</span></span>
      <span class="rozet {{ 'durum-karara_baglandi' if u.id in aktif_uzmanliklar }}">{{ 'Aktif' if u.id in aktif_uzmanliklar else 'Sona erdi' }}</span></p>
  {% else %}<p class="soluk">Uzmanlığın yok.</p>{% endfor %}
</section>

<section class="kart">
  <h2>Başvuru</h2>
  <ol class="adim-listesi">
    <li><strong>Ön şart:</strong> o alanda en az {{ parametre('UZMAN_MIN_MESAJ') }} mesaj yazmış ve en az {{ parametre('UZMAN_MIN_KONU') }} farklı konuya katılmış olmak.</li>
    <li><strong>Kontenjan:</strong> bir ana kategoride en fazla {{ parametre('UZMAN_KONTENJAN') }} uzman olabilir.</li>
    <li><strong>Oylama:</strong> o alandaki konulara yazmış üyeler oylar; kabul için {{ parametre('ESIK_UZMANLIK') }} gerekir. Herkesin oyu 1 sayılır.</li>
  </ol>
  {% if basvuru %}
    <p>Süren bir başvurun var. <a href="{{ url_for('oylamalar.teklif', teklif_id=basvuru.id) }}">Oylamayı gör →</a></p>
  {% else %}
    <form method="get" class="satir-form">
      <label for="alan">Alan</label>
      <select name="alan" id="alan">{% for id, ad in kategoriler %}<option value="{{ id }}" {{ 'selected' if id == secili }}>{{ ad }}</option>{% endfor %}</select>
      <button class="dugme ince kucuk-dugme">Şartlara bak</button>
    </form>
    {% if sart %}
      <ul class="kontrol-listesi">
        <li class="{{ 'tamam' if sart.mesaj >= sart.gereken_mesaj else 'eksik' }}">Bu alanda {{ sart.mesaj }} mesajın var (en az {{ sart.gereken_mesaj }} gerekir)</li>
        <li class="{{ 'tamam' if sart.konu >= sart.gereken_konu else 'eksik' }}">Bu alanda {{ sart.konu }} farklı konuya katıldın (en az {{ sart.gereken_konu }} gerekir)</li>
        <li class="{{ 'tamam' if kontenjan.yer_var else 'eksik' }}">{{ kontenjan.alan }} alanında {{ kontenjan.dolu }}/{{ kontenjan.toplam }} uzman var{{ '' if kontenjan.yer_var else '; kontenjan dolu' }}</li>
      </ul>
      {% if sart.tamam and kontenjan.yer_var %}
        <form method="post" action="{{ url_for('profil.uzmanlik_basvurusu') }}" class="form">{{ csrf() }}
          <input type="hidden" name="kategori_id" value="{{ secili }}">
          <label>Gerekçe <textarea name="gerekce" rows="3" minlength="20" required placeholder="Eğitimin, deneyimin, bu alandaki katkın…"></textarea></label>
          <div><button class="dugme">Başvur ve oylamaya sun</button></div></form>
      {% else %}
        <p class="soluk">Şartlar sağlanınca başvuru formu burada açılır.</p>
      {% endif %}
    {% endif %}
  {% endif %}
</section>
{% endblock %}

{% extends "base.html" %}
{% from "_makrolar.html" import csrf, giris_kabugu %}
{% block baslik %}Şifremi unuttum{% endblock %}
{% block icerik %}
{% call giris_kabugu('Hesabına geri dön', 'Forum e-posta istemez; kayıt olurken aldığın kurtarma kodu yeni şifre belirlemen için yeterli.') %}
  <h1>Şifremi unuttum</h1>
  <p class="soluk">Kayıt olurken sana verilen kurtarma koduyla (AGORA-XXXX-…) yeni şifre belirleyebilirsin.</p>
  <form method="post" class="form">
    {{ csrf() }}
    <label>Takma ad <input name="takma_ad" value="{{ takma_ad }}" required></label>
    <label>Kurtarma kodu <input name="kurtarma_kodu" required placeholder="AGORA-XXXX-XXXX-XXXX-XXXX" autocomplete="off"></label>
    <div class="iki-sutun">
      <label>Yeni şifre <input type="password" name="yeni" minlength="{{ ayarlar.SIFRE_MIN }}" required autocomplete="new-password"></label>
      <label>Yeni şifre (tekrar) <input type="password" name="yeni_tekrar" minlength="{{ ayarlar.SIFRE_MIN }}" required autocomplete="new-password"></label>
    </div>
    <button class="dugme">Şifremi sıfırla</button>
  </form>
{% endcall %}
{% endblock %}

{# Oylama sayfasının KARAR türüne özgü bölümü (teklif.html bunu tür koduna göre içerir). #}
{% if tur_bilgisi %}
<div class="kutucuk">
  <p><strong>{{ tur_bilgisi.no }}. tur kuralı:</strong>
    {% if tur_bilgisi.son %}Son tur. En yüksek oranı alan fikir kabul edilir ve konu kapanır.
    {% else %}Tur bitince oranı {{ tur_bilgisi.eleme }} altında kalan fikirler elenir. Geriye tek fikir kalırsa o kabul edilir.{% endif %}
    Herhangi bir fikir {{ tur_bilgisi.ezici }} ya da daha fazla alırsa hemen kabul edilir.</p>
  <p class="soluk kucuk">Bir fikrin oranı iki ayrı yoldan hesaplanır: ağırlıklı oylara ve kişi sayısına göre. Küçük olan geçerlidir. Çekimser oylar toplamda sayılır.</p>
</div>
{% endif %}

{# Oylama sayfasının KATEGORI türüne özgü bölümü (teklif.html bunu tür koduna göre içerir). #}
{% if kategori_onerisi %}
<div class="kutucuk"><p><strong>Önerilen kategori:</strong> {{ kategori_onerisi.yol }}
  <span class="soluk kucuk">({{ 'alt kategori' if kategori_onerisi.ust else 'yeni ana kategori' }})</span></p>
  {% if kategori_onerisi.kavramlar %}<p class="kucuk">Kavramlar: {{ kategori_onerisi.kavramlar|join(', ') }}</p>{% endif %}
  {% if kategori_onerisi.eklenen %}<p>{{ ikon('tik') }} Kategori eklendi: <a href="{{ url_for('konular.ana_sayfa', kategori=kategori_onerisi.eklenen.id) }}">konularına git →</a></p>{% endif %}
  <p class="soluk kucuk">Kabul edilirse kategori hemen eklenir ve herkes o kategoride konu açabilir. Bu oylamada herkesin oyu 1 sayılır.
    <a href="{{ url_for('konular.kategori_sayfasi') }}">Bütün kategoriler →</a></p></div>
{% endif %}

{# Oylama sayfasının KONU_SILME türüne özgü bölümü (teklif.html bunu tür koduna göre içerir). #}
{% if konu %}
<p>Oylanan: <strong>“{{ konu.baslik }}”</strong> konusunun (ve alt konularının) kaldırılması. Kabul edilirse konu gizlenir, yerinde iz kalır.</p>
{% endif %}

{# Oylama sayfasının MESAJ_SILME türüne özgü bölümü (teklif.html bunu tür koduna göre içerir). #}
{% from "_makrolar.html" import kisi %}
{% if hedef_mesajlar %}
{% if hedef_mesajlar|length > 1 %}<p><strong>Tartışmanın bir kısmı:</strong> {{ hedef_mesajlar|length }} mesaj tek oylamada.</p>{% endif %}
{% for hm in hedef_mesajlar %}
<div class="mesaj tip-{{ hm.tip|lower }}">
  <img class="avatar mesaj-avatar" src="{{ avatar(hm.takma_ad, hm.yz_mi) }}" alt="">
  <div class="mesaj-govde">
    <header>{{ kisi(hm.takma_ad, hm.yz_mi, resim=False) }} <span class="rozet mtip">{{ ayarlar.MESAJ_TIPLERI[hm.tip] }}</span>
      <span class="soluk kucuk">#{{ hm.id }} · {{ hm.olusturma|tarih }}</span></header>
    {% if hm.gizli %}<p class="iz">{{ ikon('oy') }} {{ hm.gizlenme_notu }}</p>{% else %}<div class="icerik">{{ hm.icerik|bicimle }}</div>{% endif %}
  </div>
</div>
{% endfor %}
<p class="soluk kucuk">Kabul edilirse mesajlar silinmez, gizlenir: yerinde iz kalır, özetleri kayıt defterinde durur.</p>
{% endif %}

{# Oylama sayfasının UZMANLIK türüne özgü bölümü (teklif.html bunu tür koduna göre içerir). #}
{% from "_makrolar.html" import kisi %}
{% if aday %}
<p>{{ kisi(aday.k.takma_ad, aday.k.yz_mi) }} için <strong>{{ veri.kategori_id|kategori }}</strong> alanında uzmanlık isteniyor.
  Kabul edilirse {{ parametre('UZMAN_SURE_GUN') }} gün boyunca bu alandaki fikir oylamalarında oyu {{ parametre('UZMAN_AGIRLIK') }} sayılır.</p>
<ul class="kontrol-listesi">
  <li class="{{ 'tamam' if aday.sart.mesaj >= aday.sart.gereken_mesaj else 'eksik' }}">Ön şart: bu alanda {{ aday.sart.mesaj }} mesaj (en az {{ aday.sart.gereken_mesaj }})</li>
  <li class="{{ 'tamam' if aday.sart.konu >= aday.sart.gereken_konu else 'eksik' }}">Ön şart: bu alanda {{ aday.sart.konu }} farklı konu (en az {{ aday.sart.gereken_konu }})</li>
  <li class="{{ 'tamam' if aday.kontenjan.yer_var else 'eksik' }}">Kontenjan: {{ aday.kontenjan.alan }} alanında {{ aday.kontenjan.dolu }}/{{ aday.kontenjan.toplam }} uzman</li>
</ul>
<p class="soluk kucuk">Bu oylamaya yalnızca {{ aday.kontenjan.alan }} alanındaki konulara yazmış üyeler katılır. Herkesin oyu 1 sayılır; aday oy kullanamaz.</p>
{% endif %}

{# Oylama sayfasının YONETMELIK türüne özgü bölümü (teklif.html bunu tür koduna göre içerir). #}
<div class="kutucuk"><p><strong>Önerilen değişiklik:</strong> {{ veri.aciklama }}</p>
  {% if veri.tur == 'BEYAN' %}<p><em>{{ veri.baslik }}:</em> {{ veri.metin }}</p>{% endif %}
  {% if veri.korunan %}<p class="uyari hata">Bu değişiklik korunan bir temel hak maddesine dokunuyor; {{ ayarlar.ESIKLER[t.esik].ad|lower }} gerekir.</p>{% endif %}
  <p class="soluk kucuk">Yönetmelik oylamasında herkesin oyu 1 sayılır.</p></div>

{% extends "base.html" %}
{% from "_makrolar.html" import csrf, kisi, teklif_durumu, esik, sonuc_tablosu %}
{% block baslik %}{{ baslik }}{% endblock %}
{% block icerik %}
<section class="kart orta">
  {% if konu %}<p class="soluk"><a href="{{ url_for('konular.konu', konu_id=konu.id) }}">← {{ konu.baslik }}</a></p>
  {% elif t.tip == 'YONETMELIK' %}<p class="soluk"><a href="{{ url_for('genel.yonetmelik_sayfasi') }}">← Yönetmelik</a></p>{% endif %}
  <h1>{{ baslik }}</h1>
  <p>{{ teklif_durumu(t.durum) }} {% if t.esik in ayarlar.ESIKLER %}{{ esik(t.esik) }}{% endif %}
    <span class="soluk kucuk">{% if acan %}Açan: {{ kisi(acan.takma_ad, acan.yz_mi) }} · {% endif %}{{ t.baslangic|tarih }} ·
      {% if t.durum == 'ACIK' %}bitiş {{ t.bitis|tarih }} ({{ t.bitis|kalan }}){% else %}kapanış {{ t.kapanis|tarih }}{% endif %}</span></p>
  {% if t.gerekce %}<p><strong>Gerekçe:</strong> {{ t.gerekce|bicimle }}</p>{% endif %}

  {% include 'teklif/_' ~ t.tip|lower ~ '.html' ignore missing %}
</section>

<section class="kart orta" id="oy">
{% if t.durum == 'ACIK' %}
  <h2>Oy ver</h2>
  <p class="soluk">{{ oy_sayisi }} kişi oy verdi · {{ hak_sahibi }} hak sahibi. Ara sonuçlar oylama bitene kadar gizlidir.</p>

  {% if makbuz %}
    <div class="uyari basari makbuz">{{ ikon('makbuz') }} <strong>Oy makbuzun:</strong> <code id="makbuz">{{ makbuz.kod }}</code>
      <button type="button" class="dugme ince kucuk-dugme" data-kopyala="#makbuz">Kopyala</button><br>
      <small>Oyun kayıt defterine, seçimini açık etmeyen bir özet olarak yazıldı. Bu kodla <a href="{{ url_for('genel.defter_sayfasi', _anchor='makbuz') }}">kayıt defteri sayfasında</a>
        oyunun kaydedildiğini ve neye oy verdiğini yalnızca sen doğrulayabilirsin. Kod bir daha gösterilmez; bir yere not al.</small></div>
  {% endif %}

  {% if durum.devir and not durum.oy %}
    <div class="uyari bilgi">Oy hakkın @{{ durum.devir.takma_ad }} kişisine devredilmiş ({{ durum.devir.kapsam|lower }}). Kendin oy verirsen bu oylama için devir geçersiz olur.</div>
  {% endif %}

  {% if durum.verebilir %}
    <form method="post" action="{{ url_for('oylamalar.oy_ver', teklif_id=t.id) }}" class="form oy-formu">
      {{ csrf() }}
      {% set mevcut = durum.oy.secim if durum.oy else None %}
      {% if fikir_oylamasi %}
        {% for s in secenekler %}
          <label class="secenek{{ ' soluk' if s.gizli }}"><input type="radio" name="secim" value="{{ s.id }}" required {{ 'checked' if mevcut == s.id|string }} {{ 'disabled' if s.gizli }}>
            <span>{{ s.metin }}{% if s.mesaj_id and not s.gizli %} <a class="soluk kucuk" href="{{ url_for('konular.konu', konu_id=t.konu_id, _anchor='m' ~ s.mesaj_id) }}">(tartışmasını gör)</a>{% endif %}</span></label>
        {% else %}<p class="soluk">Henüz fikir yazılmadı. Konu sayfasından bir fikir ekleyebilirsin.</p>{% endfor %}
        <label class="secenek"><input type="radio" name="secim" value="CEKIMSER" required {{ 'checked' if mevcut == 'CEKIMSER' }}>
          <span><strong>Çekimser</strong> <small class="soluk">Hiçbir fikri desteklemiyorum. Toplamda sayılır, fikirlerin oranını düşürür.</small></span></label>
      {% else %}
        {% for s in ['EVET', 'HAYIR', 'CEKIMSER'] %}
          <label class="secenek"><input type="radio" name="secim" value="{{ s }}" required {{ 'checked' if mevcut == s }}> <span>{{ ayarlar.SECIM_ADLARI[s] }}</span></label>
        {% endfor %}
      {% endif %}
      <p>Oyun <strong>{{ durum.agirlik }}</strong> sayılacak <span class="soluk">({{ durum.aciklama }})</span>.</p>
      <label>Gerekçe {% if durum.agirlik > 1 %}<strong>(zorunlu, çünkü uzman oyları herkese açıktır)</strong>{% else %}<small>(isteğe bağlı; oyun gizli kalır)</small>{% endif %}
        <textarea name="gerekce" rows="3" {{ 'required minlength=10' if durum.agirlik > 1 }}>{{ durum.oy.gerekce if durum.oy and durum.oy.gerekce else '' }}</textarea></label>
      <div><button class="dugme">{{ 'Oyumu güncelle' if durum.oy else 'Oyumu ver' }}</button></div>
      {% if durum.oy %}<p class="soluk kucuk">Oyun kayıtlı ({{ durum.oy.zaman|tarih }}). Oylama bitene kadar değiştirebilirsin; değiştirirsen yeni makbuz alırsın.</p>{% endif %}
    </form>
  {% elif kullanici %}
    <p class="kilit">{{ ikon('kilit') }} {{ durum.aciklama or 'Bu oylamada oy hakkın yok.' }}</p>
  {% else %}
    <p><a href="{{ url_for('hesap.giris', sonra=request.path) }}">Oy vermek için giriş yap.</a></p>
  {% endif %}

{% elif sonuc %}
  <h2>Sonuç</h2>
  {% if fikir_oylamasi %}
    {% if tur_sonucu %}
      <p class="uyari {{ 'basari' if tur_sonucu.karar == 'KABUL' else ('hata' if tur_sonucu.karar == 'SONUCSUZ' else 'bilgi') }}">
        {% if tur_sonucu.karar == 'KABUL' %}{{ ikon('tik') }} Bir fikir kabul edildi: {{ tur_sonucu.aciklama }}.
        {% elif tur_sonucu.karar == 'DEVAM' %}{{ ikon('ileri') }} {{ tur_sonucu.aciklama|capitalize }}; kalanlar sonraki tura geçti.
        {% else %}{{ ikon('uyari') }} Konu sonuçsuz kapandı: {{ tur_sonucu.aciklama }}.{% endif %}</p>
      {{ sonuc_tablosu(sonuc, sonuc.onde if tur_sonucu.karar == 'KABUL' else None, fikir=True, kalanlar=tur_sonucu.kalanlar) }}
    {% else %}
      {{ sonuc_tablosu(sonuc, None, fikir=True) }}
    {% endif %}
  {% else %}
    {{ sonuc_tablosu(sonuc, 'EVET' if t.durum == 'KABUL' else None) }}
  {% endif %}
{% else %}
  <p class="soluk">Bu oylama iptal edildi.</p>
{% endif %}
</section>
{% endblock %}

{% extends "base.html" %}
{#- Yönetim bölümünün sayfa düzeni: forumun menüsü yerine kendi üst çubuğu. Üye arayüzünden ayrıdır. -#}
{% block ust %}
<header class="ust ust-yonetim">
  <div class="ust-ic">
    <a class="marka" href="{{ url_for('yonetim.pano') }}" aria-label="Yönetim paneli">
      <img class="logo" src="{{ url_for('static', filename='ikon.svg') }}" alt="">
      <span>{{ ayarlar.SITE_ADI }} <small class="marka-ek">Yönetim</small></span>
    </a>
    <div class="hesap">
      <a class="dugme ince kucuk-dugme" href="{{ url_for('konular.ana_sayfa') }}">Siteye dön</a>
      {% if kullanici %}
        <span class="soluk kucuk yonetici-kim">{{ ikon('kalkan') }} @{{ kullanici.takma_ad }}</span>
        <form method="post" action="{{ url_for('yonetim.cikis') }}"><input type="hidden" name="csrf" value="{{ csrf_token() }}"><button class="dugme kucuk-dugme">Çıkış</button></form>
      {% endif %}
    </div>
  </div>
</header>
{% endblock %}
{% block alt_cubuk %}{% endblock %}
{% block alt_bilgi %}{% endblock %}

{% extends "yonetim/_duzen.html" %}
{#- Yönetim panelinin iskeleti: solda bölüm menüsü (telefonda üstte kaydırılabilir şerit), sağda sayfa. -#}
{% block icerik %}
{% set menu = [('yonetim.pano', 'Pano', 'pano'), ('yonetim.uyeler', 'Üyeler', 'kisiler'),
               ('yonetim.sikayet_listesi', 'Şikayetler', 'bayrak'), ('yonetim.konu_listesi', 'Konular', 'sohbet'),
               ('yonetim.oylamalar', 'Oylamalar', 'oy'), ('yonetim.bildirim_gonder', 'Toplu bildirim', 'zil'),
               ('yonetim.kategoriler', 'Kategoriler', 'etiket'), ('yonetim.sistem', 'Sistem', 'sunucu'),
               ('yonetim.gunluk_sayfasi', 'Günlük', 'belge')] %}
{% set ep = request.endpoint %}
<div class="panel-kabugu">
  <nav class="panel-menu" aria-label="Yönetim paneli">
    <p class="pm-baslik">{{ ikon('kalkan') }} Yönetim</p>
    {% for e, ad, ik in menu %}
      <a class="{{ 'secili' if ep == e or (e == 'yonetim.uyeler' and ep == 'yonetim.uye') }}"
         {{ 'aria-current=page' if ep == e }} href="{{ url_for(e) }}">{{ ikon(ik) }}<span>{{ ad }}</span>
        {% if e == 'yonetim.sikayet_listesi' and acik_sikayet %}<span class="sayac">{{ acik_sikayet }}</span>{% endif %}</a>
    {% endfor %}
    <p class="pm-not soluk kucuk">Yönetici yalnızca siteyi yönetir: içerik silemez, uzman atayamaz, oylamalara dokunamaz. Yaptığın her işlem şeffaflık günlüğüne yazılır.</p>
  </nav>
  <div class="panel-icerik">{% block panel %}{% endblock %}</div>
</div>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf, kisi, konum_secici %}
{% block baslik %}Toplu bildirim · Yönetim{% endblock %}
{% block panel %}
<h1>Toplu bildirim</h1>
<section class="kart">
  <p class="soluk">Bildirim, seçtiğin üyelerin bildirim listesine düşer. Telefonunda bildirimleri açmış üyelere anlık bildirim olarak da gider.
    Her gönderim şeffaflık günlüğüne yazılır.</p>
  <form method="post" class="form hedef-formu">{{ csrf() }}
    <fieldset><legend>Kime?</legend>
      {% for d, ad in hedefler.items() %}
        <label class="secenek"><input type="radio" name="hedef" value="{{ d }}" {{ 'checked' if loop.first }}> <span>{{ ad }}</span></label>
      {% endfor %}
    </fieldset>
    <div class="hedef-KONUM gizle">{{ konum_secici(iller, ilceler, zorunlu=False) }}
      <p class="soluk kucuk">İlçe seçmezsen ildeki bütün üyelere gider.</p></div>
    <label class="hedef-UZMAN gizle">Alan <select name="kategori_id">{% for id, ad in kategoriler %}<option value="{{ id }}">{{ ad }}</option>{% endfor %}</select>
      <small>Ana kategori seçersen alt alanların uzmanları da dahil olur.</small></label>
    <label>Metin <textarea name="metin" rows="3" minlength="5" maxlength="300" required placeholder="ör. Kampüs ulaşımı konusunda karar oylaması başladı, oyunu kullanmayı unutma."></textarea></label>
    <label>Bağlantı <small>İsteğe bağlı; bildirime dokununca açılacak sayfa (ör. /konu/3 ya da /gundem).</small>
      <input name="baglanti" placeholder="/gundem" pattern="/.*" maxlength="200"></label>
    <div><button class="dugme" data-onay="Bildirim gönderilsin mi?">{{ ikon('zil') }} Gönder</button></div>
  </form>
</section>
<section class="kart">
  <h2>Son gönderilenler</h2>
  <ul class="olay-listesi">
    {% for o in gecmis %}<li><span class="soluk kucuk">{{ o.zaman|tarih }}</span> {{ kisi(o.takma_ad, resim=False) }} · {{ o.detay }}</li>
    {% else %}<li class="soluk">Henüz toplu bildirim gönderilmedi.</li>{% endfor %}
  </ul>
</section>
{% endblock %}

{% extends "yonetim/_duzen.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}Yönetici girişi{% endblock %}
{% block icerik %}
<section class="kart yonetici-giris">
  <h1>{{ ikon('kalkan') }} Yönetici girişi</h1>
  <p class="soluk">Yönetim paneline yalnızca yönetici hesapları girebilir. Bu giriş üye girişinden ayrıdır: forumda
    üye olarak açık olan oturumun etkilenmez.</p>
  <form method="post" class="form">
    {{ csrf() }}
    <input type="hidden" name="sonra" value="{{ sonra or '' }}">
    <label>Takma ad <input name="takma_ad" value="{{ takma_ad }}" required autofocus autocomplete="username"></label>
    <label>Şifre <input type="password" name="sifre" required autocomplete="current-password"></label>
    <button class="dugme">Yönetim paneline gir</button>
  </form>
  <p class="soluk kucuk">Demo yönetici hesabı: <code>yonetici</code> · şifre <code>forum1234</code>.
    Forumu kullanmak için <a href="{{ url_for('hesap.giris') }}">üye girişi</a>.</p>
</section>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import kisi, sayfa_gezgini %}
{% block baslik %}Günlük · Yönetim{% endblock %}
{% block panel %}
<div class="sayfa-bas"><div><h1>Günlük</h1><p class="soluk kucuk">{{ sayfalama.toplam }} kayıt</p></div></div>
<form class="arac-cubugu" method="get">
  <select name="eylem" aria-label="Olay türü">
    <option value="">Bütün olaylar</option>
    <option value="YONETIM" {{ 'selected' if eylem == 'YONETIM' }}>Yalnızca yönetim işlemleri</option>
    {% for e in eylemler %}<option value="{{ e }}" {{ 'selected' if eylem == e }}>{{ eylem_adlari.get(e, e) }}</option>{% endfor %}
  </select>
  <input name="kim" value="{{ kim }}" placeholder="Takma ad" aria-label="Takma ad">
  <button class="dugme kucuk-dugme">Süz</button>
</form>
<section class="kart sifir-dolgu">
  <div class="tablo-kap"><table class="liste yonetim-tablosu">
    <thead><tr><th>Zaman</th><th>Kim</th><th>Tür</th><th>Olay</th></tr></thead>
    {% for o in kayitlar %}
      <tr><td class="soluk kucuk">{{ o.zaman|tarih }}</td><td>{{ kisi(o.takma_ad, o.yz_mi, resim=False) }}</td>
        <td><span class="rozet">{{ eylem_adlari.get(o.eylem, o.eylem) }}</span></td><td>{{ o.detay }}</td></tr>
    {% else %}<tr><td colspan="4" class="bos-durum">Kayıt yok.</td></tr>{% endfor %}
  </table></div>
</section>
{{ sayfa_gezgini(sayfalama, 'yonetim.gunluk_sayfasi', request.args.to_dict()) }}
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}Kategoriler · Yönetim{% endblock %}
{% macro renk_secici(secili) -%}
  <select name="renk" aria-label="Renk">{% for r, ad in renkler %}<option value="{{ r }}" {{ 'selected' if (secili or '') == r }}>{{ ad }}</option>{% endfor %}</select>
{%- endmacro %}
{% block panel %}
<h1>Kategoriler</h1>
<p class="soluk">Konular bu yapıya göre sınıflanır; yönetmeliğin kategori denetimi de buna bakar. Kategori silinemez, çünkü eski konular ona bağlıdır; adını değiştirebilirsin.</p>

<div class="kategori-listesi">
{% for kok in agac %}
  <section class="kart">
    <form method="post" action="{{ url_for('yonetim.kategori_duzenle', kategori_id=kok.id) }}" class="satir-form kok-satiri">{{ csrf() }}
      <span class="kat-nokta buyuk" style="background: {{ kok.renk_goster }}"></span>
      <input name="ad" value="{{ kok.ad }}" required maxlength="40" aria-label="Kategori adı">
      {{ renk_secici(kok.renk) }}
      <button class="dugme ince kucuk-dugme">Kaydet</button>
      <span class="soluk kucuk">{{ kok.sayi }} konu</span>
    </form>
    <ul class="alt-kategoriler">
      {% for a in kok.altlar %}
        <li><form method="post" action="{{ url_for('yonetim.kategori_duzenle', kategori_id=a.id) }}" class="satir-form">{{ csrf() }}
          <input name="ad" value="{{ a.ad }}" required maxlength="40" aria-label="Alt kategori adı">
          <button class="bag">Kaydet</button><span class="soluk kucuk">{{ a.sayi }} konu</span></form></li>
      {% endfor %}
      <li><form method="post" action="{{ url_for('yonetim.kategori_ekle') }}" class="satir-form">{{ csrf() }}
        <input type="hidden" name="ust_id" value="{{ kok.id }}">
        <input name="ad" required maxlength="40" placeholder="Yeni alt kategori" aria-label="Yeni alt kategori">
        <button class="dugme ince kucuk-dugme">{{ ikon('arti') }} Ekle</button></form></li>
    </ul>
  </section>
{% endfor %}
</div>

<section class="kart">
  <h2>Ana kategori ekle</h2>
  <form method="post" action="{{ url_for('yonetim.kategori_ekle') }}" class="satir-form">{{ csrf() }}
    <input name="ad" required maxlength="40" placeholder="Kategori adı" aria-label="Kategori adı">
    {{ renk_secici('') }}
    <button class="dugme kucuk-dugme">{{ ikon('arti') }} Ekle</button>
  </form>
</section>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf, konu_durumu, kategori_cipi, sayfa_gezgini %}
{% block baslik %}Konular · Yönetim{% endblock %}
{% block panel %}
<div class="sayfa-bas"><div><h1>Konular</h1><p class="soluk kucuk">{{ sayfalama.toplam }} konu</p></div></div>
<nav class="cipler" aria-label="Duruma göre süz">
  {% for d, ad in filtreler %}<a class="cip {{ 'secili' if durum == d }}" href="{{ url_for('yonetim.konu_listesi', durum=d) }}">{{ ad }}</a>{% endfor %}
</nav>
<section class="kart sifir-dolgu">
  <div class="tablo-kap"><table class="liste yonetim-tablosu">
    <thead><tr><th>Konu</th><th>Durum</th><th class="genis">Sahibi</th><th class="genis">Mesaj</th>{% if config.DEMO %}<th>Sunum</th>{% endif %}</tr></thead>
    {% for k in satirlar %}
      <tr>
        <td><a href="{{ url_for('konular.konu', konu_id=k.id) }}">#{{ k.id }} {{ k.baslik }}</a><br>{{ kategori_cipi(k.kategori_id) }}</td>
        <td>{% if k.silindi %}<span class="rozet durum-sonucsuz">Kaldırıldı</span>{% else %}{{ konu_durumu(k.durum) }}
          {% if k.durum == 'OYLAMA' %}<br><span class="soluk kucuk">{{ k.tur }}. tur</span>
          {% elif k.durum == 'TARTISMA' and k.tartisma_bitis %}<br><span class="soluk kucuk">{{ k.tartisma_bitis|kalan }}</span>{% endif %}{% endif %}</td>
        <td class="genis"><a href="{{ url_for('yonetim.uye', kullanici_id=k.sahip_id) }}">@{{ k.sahip }}</a></td>
        <td class="genis">{{ k.mesaj_sayisi }}</td>
        {% if config.DEMO %}
        <td class="islem-hucresi">
          {% if durum_nesnesi(k).zamanli %}
            <form method="post" action="{{ url_for('yonetim.konu_ilerlet', konu_id=k.id) }}">{{ csrf() }}<input type="hidden" name="geri" value="{{ request.full_path }}">
              <button class="dugme ince kucuk-dugme" data-onay="Süre beklenmeden bir sonraki aşamaya geçilsin mi? (Yalnızca sunum kipi)">Süreyi ilerlet</button></form>
          {% else %}<span class="soluk kucuk">—</span>{% endif %}
        </td>
        {% endif %}
      </tr>
    {% else %}<tr><td colspan="5" class="bos-durum">Bu durumda konu yok.</td></tr>{% endfor %}
  </table></div>
</section>
{{ sayfa_gezgini(sayfalama, 'yonetim.konu_listesi', request.args.to_dict()) }}
<p class="soluk kucuk">Yönetici konulara dokunamaz: konu kaldırmak ya da mesaj gizlemek konu sayfasından açılan oylamayla olur; süreler kendiliğinden işler.
  {% if config.DEMO %}<strong>Sunum kipi açık:</strong> “Süreyi ilerlet” yalnızca beklemeyi kısaltır, sayım kurallarını değiştirmez ve günlüğe yazılır.{% endif %}</p>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf, teklif_durumu, esik %}
{% block baslik %}Oylamalar · Yönetim{% endblock %}
{% block panel %}
<h1>Oylamalar</h1>
<section class="kart sifir-dolgu">
  <h2 class="kart-ici-baslik">Süren oylamalar <span class="soluk kucuk">({{ acik|length }})</span></h2>
  <div class="tablo-kap"><table class="liste yonetim-tablosu">
    <thead><tr><th>Oylama</th><th>Tür</th><th>Eşik</th><th>Oy</th><th>Kalan</th>{% if config.DEMO %}<th>Sunum</th>{% endif %}</tr></thead>
    {% for x in acik %}{% set t = x.t %}
      <tr>
        <td><a href="{{ url_for('oylamalar.teklif', teklif_id=t.id) }}">#{{ t.id }} {{ x.baslik }}</a></td>
        <td class="kucuk">{{ ayarlar.TEKLIF_TIPLERI[t.tip].ad }}{% if t.tip == 'KARAR' %} ({{ t.tur_no }}. tur){% endif %}</td>
        <td>{% if t.esik in ayarlar.ESIKLER %}{{ esik(t.esik) }}{% else %}<span class="soluk kucuk">tur kuralı</span>{% endif %}</td><td>{{ x.oy }}</td>
        <td class="kucuk soluk">{{ t.bitis|kalan }}</td>
        {% if config.DEMO %}<td><form method="post" action="{{ url_for('yonetim.oylama_ilerlet', teklif_id=t.id) }}">{{ csrf() }}
          <button class="dugme ince kucuk-dugme" data-onay="Süre beklenmeden şimdiki oylarla sayım yapılsın mı? (Yalnızca sunum kipi)">Süreyi ilerlet</button></form></td>{% endif %}
      </tr>
    {% else %}<tr><td colspan="6" class="bos-durum">Süren oylama yok.</td></tr>{% endfor %}
  </table></div>
</section>
<p class="soluk kucuk">Bu sayfa yalnızca izlemek içindir: yönetici oylamaların süresine ve sonucuna dokunamaz.
  {% if config.DEMO %}<strong>Sunum kipi açık:</strong> “Süreyi ilerlet” beklemeden sayım yapar; kurallar ve eşikler değişmez, işlem günlüğe yazılır.{% endif %}</p>

<section class="kart sifir-dolgu">
  <h2 class="kart-ici-baslik">Son biten oylamalar</h2>
  <div class="tablo-kap"><table class="liste yonetim-tablosu">
    <thead><tr><th>Oylama</th><th>Tür</th><th>Sonuç</th><th>Bitiş</th></tr></thead>
    {% for x in biten %}{% set t = x.t %}
      <tr><td><a href="{{ url_for('oylamalar.teklif', teklif_id=t.id) }}">#{{ t.id }} {{ x.baslik }}</a></td>
        <td class="kucuk">{{ (ayarlar.TEKLIF_TIPLERI.get(t.tip) or {'ad': 'Eski oylama'}).ad }}</td><td>{{ teklif_durumu(t.durum) }}</td>
        <td class="kucuk soluk">{{ (t.kapanis or t.bitis)|gun }}</td></tr>
    {% else %}<tr><td colspan="4" class="bos-durum">Henüz biten oylama yok.</td></tr>{% endfor %}
  </table></div>
</section>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf, kisi %}
{% block baslik %}Yönetim paneli{% endblock %}
{% block panel %}
{% set s = p.sayilar %}
<div class="sayfa-bas">
  <div>
    <h1>Pano</h1>
    <p class="soluk kucuk">Yönetici siteyi yönetir; kararları üyeler verir.</p>
  </div>
  <a class="dugme ince kucuk-dugme" href="{{ url_for('yonetim.yedek') }}">{{ ikon('indir') }} Yedek indir</a>
</div>

<div class="stat-izgara">
  <a class="stat" href="{{ url_for('yonetim.uyeler') }}"><span>Üye</span><strong>{{ s.uye }}</strong><small>bu hafta +{{ s.yeni_uye }}</small></a>
  <div class="stat"><span>Son 7 günde giren</span><strong>{{ s.aktif_uye }}</strong><small>{{ ((s.aktif_uye / s.uye * 100) if s.uye else 0)|round|int }}% üye</small></div>
  <a class="stat" href="{{ url_for('yonetim.konu_listesi', durum='TARTISMA') }}"><span>Açık konu</span><strong>{{ s.acik_konu }}</strong><small>{{ s.tartisma }} tartışmada</small></a>
  <a class="stat" href="{{ url_for('yonetim.oylamalar') }}"><span>Süren oylama</span><strong>{{ s.acik_oylama }}</strong><small>{{ s.karar }} kesin karar</small></a>
  <div class="stat"><span>Bu hafta mesaj</span><strong>{{ s.mesaj_hafta }}</strong><small>{{ s.oy_hafta }} oy verildi</small></div>
  <a class="stat" href="{{ url_for('yonetim.uyeler', filtre='yonetici') }}"><span>Yönetici</span><strong>{{ s.yonetici }}</strong><small>{{ s.uzman }} uzman · {{ s.askida }} askıda</small></a>
</div>

<div class="pano-izgara">
  <section class="kart">
    <h2>Son 14 gün</h2>
    <p class="gosterge kucuk"><span class="renk-kare seri-mesaj"></span> Mesaj <span class="renk-kare seri-oy"></span> Oy</p>
    {% set gen = 28 %}
    <svg class="etkinlik-grafigi" viewBox="0 0 {{ p.etkinlik|length * gen }} 130" role="img" aria-label="Son 14 günde günlük mesaj ve oy sayısı">
      {% for e in p.etkinlik %}
        {% set x = loop.index0 * gen + 5 %}
        {% set hm = (e.mesaj / p.tepe * 100)|round(1) %}
        {% set ho = (e.oy / p.tepe * 100)|round(1) %}
        <g><title>{{ e.gun.strftime('%d.%m') }}: {{ e.mesaj }} mesaj, {{ e.oy }} oy</title>
          <rect class="zemin" x="{{ x }}" y="4" width="{{ gen - 10 }}" height="100" rx="4"></rect>
          <rect class="seri-oy" x="{{ x }}" y="{{ 104 - hm - ho }}" width="{{ gen - 10 }}" height="{{ ho }}" rx="3"></rect>
          <rect class="seri-mesaj" x="{{ x }}" y="{{ 104 - hm }}" width="{{ gen - 10 }}" height="{{ hm }}" rx="3"></rect>
          {% if loop.index0 % 2 == 1 or loop.last %}<text x="{{ x + (gen - 10) / 2 }}" y="122">{{ e.gun.strftime('%d.%m') }}</text>{% endif %}
        </g>
      {% endfor %}
    </svg>
  </section>
  <section class="kart">
    <h2>Konuların durumu</h2>
    <ul class="cubuklar">
      {% for ad, n in p.durumlar %}
        <li><span>{{ ad }}</span><span class="cubuk"><i style="width: {{ (n / p.durum_tepe * 100)|round }}%"></i></span><strong>{{ n }}</strong></li>
      {% else %}<li class="soluk">Henüz konu yok.</li>{% endfor %}
    </ul>
  </section>
</div>

<div class="pano-izgara">
  <section class="kart">
    <h2>{{ ikon('kum_saati') }} İlgilenmen gerekenler</h2>
    {% set d = p.dikkat %}
    {% if not d.defter.saglikli %}
      <p class="uyari hata">{{ ikon('uyari') }} Kayıt defterinde uyumsuz bir kopya var. <a href="{{ url_for('yonetim.sistem', _anchor='defter') }}">Sistem sayfasında onar →</a></p>
    {% endif %}
    {% if d.sikayet %}
      <p class="uyari">{{ ikon('bayrak') }} {{ d.sikayet }} içerik için bekleyen şikayet var. <a href="{{ url_for('yonetim.sikayet_listesi') }}">Şikayetlere git →</a></p>
    {% endif %}
    <h3>24 saat içinde biten oylamalar</h3>
    {% for t in d.biten_oylamalar %}
      <p class="is-satiri"><a href="{{ url_for('oylamalar.teklif', teklif_id=t.id) }}">#{{ t.id }} {{ basliklar(t) }}</a>
        <span class="soluk kucuk">{{ t.bitis|kalan }}</span></p>
    {% else %}<p class="soluk kucuk">Yok.</p>{% endfor %}
    <h3>24 saat içinde oylamaya geçecek konular</h3>
    {% for k in d.biten_tartismalar %}
      <p class="is-satiri"><a href="{{ url_for('konular.konu', konu_id=k.id) }}">{{ k.baslik }}</a>
        <span class="soluk kucuk">{{ k.tartisma_bitis|kalan }}</span></p>
    {% else %}<p class="soluk kucuk">Yok.</p>{% endfor %}
    <h3>30 gün içinde biten uzmanlıklar</h3>
    {% for u in d.biten_uzmanlik %}
      <p class="is-satiri"><a href="{{ url_for('yonetim.uye', kullanici_id=u.kullanici_id) }}">@{{ u.takma_ad }}</a>
        <span class="soluk kucuk">{{ u.kategori_id|kategori }} · {{ u.bitis|gun }}</span></p>
    {% else %}<p class="soluk kucuk">Yok.</p>{% endfor %}
    <p class="soluk kucuk">Bunlar bilgi içindir: süreler kendiliğinden işler, yönetici oylamaya ya da süreye dokunamaz.</p>
  </section>
  <section class="kart">
    <h2>Son yönetim işlemleri</h2>
    <ul class="olay-listesi">
      {% for o in p.son_islemler %}
        <li><span class="soluk kucuk">{{ o.zaman|once }}</span> {{ kisi(o.takma_ad, resim=False) }} · {{ o.detay }}</li>
      {% else %}<li class="soluk">Henüz yönetim işlemi yok.</li>{% endfor %}
    </ul>
    <a class="kucuk" href="{{ url_for('yonetim.gunluk_sayfasi', eylem='YONETIM') }}">Tümü →</a>
  </section>
</div>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf, kisi %}
{% block baslik %}Şikayetler · Yönetim{% endblock %}
{% block panel %}
<div class="sayfa-bas">
  <div><h1>Şikayetler</h1><p class="soluk kucuk">Üyelerin bildirdiği mesajlar ve konular. Aynı içerik hakkındaki şikayetler birlikte görünür.</p></div>
</div>
<nav class="cipler" aria-label="Şikayet durumu">
  <a class="cip {{ 'secili' if not kapali }}" href="{{ url_for('yonetim.sikayet_listesi') }}">Bekleyenler{% if acik_sikayet %} · {{ acik_sikayet }}{% endif %}</a>
  <a class="cip {{ 'secili' if kapali }}" href="{{ url_for('yonetim.sikayet_listesi', durum='kapali') }}">Sonuçlananlar</a>
</nav>

{% for gr in gruplar %}
  <section class="kart sikayet-karti">
    <div class="baslik-satiri">
      <h2>{% if gr.mesaj %}{{ ikon('sohbet') }} #{{ gr.mesaj.id }} numaralı mesaj{% else %}{{ ikon('belge') }} Konu{% endif %}
        <span class="rozet {{ 'durum-oylama' if gr.durum == 'OYLAMADA' else ('durum-sonucsuz' if gr.durum == 'YERSIZ' else 'durum-tartisma') }}">{{ durumlar[gr.durum] }}</span></h2>
      <span class="soluk kucuk">{{ gr.sikayetler|length }} şikayet</span>
    </div>
    <p class="kucuk"><a href="{{ url_for('konular.konu', konu_id=gr.konu.id, _anchor=('m' ~ gr.mesaj.id) if gr.mesaj else None) }}">{{ gr.konu.baslik }}</a></p>
    {% if gr.mesaj %}
      <blockquote class="alinti">
        <p class="kucuk soluk">{{ kisi(gr.mesaj.takma_ad, resim=False) }} · {{ gr.mesaj.olusturma|tarih }}{% if gr.mesaj.gizli %} · <strong>gizlendi</strong>{% endif %}</p>
        <div class="icerik">{{ gr.mesaj.icerik|truncate(400) }}</div>
      </blockquote>
    {% endif %}
    <ul class="olay-listesi">
      {% for s in gr.sikayetler %}
        <li><strong>{{ s.neden }}</strong> · {{ kisi(s.sikayetci, resim=False) }} <span class="soluk kucuk">{{ s.olusturma|once }}</span>
          {% if s.aciklama %}<br><span class="kucuk">{{ s.aciklama }}</span>{% endif %}</li>
      {% endfor %}
    </ul>

    {% if gr.durum == 'ACIK' %}
      <div class="sikayet-eylem">
        <form method="post" action="{{ url_for('yonetim.sikayet_oylama', sikayet_id=gr.ilk_id) }}">{{ csrf() }}
          {% if gr.suren_oylama %}
            <button class="dugme kucuk-dugme">Süren oylamaya bağla (#{{ gr.suren_oylama }})</button>
          {% else %}
            <button class="dugme kucuk-dugme" data-onay="{{ 'Mesaj için gizleme oylaması açılsın mı?' if gr.mesaj else 'Konu için kaldırma oylaması açılsın mı?' }}">
              {{ ikon('oy') }} {{ 'Gizleme oylaması aç' if gr.mesaj else 'Kaldırma oylaması aç' }}</button>
          {% endif %}
        </form>
        <details class="satir-ici"><summary class="dugme ince kucuk-dugme">Yersiz bul</summary>
          <form method="post" action="{{ url_for('yonetim.sikayet_yersiz', sikayet_id=gr.ilk_id) }}" class="form yanit">{{ csrf() }}
            <input name="not" required minlength="5" maxlength="300" placeholder="Şikayet edene gösterilecek not (ör. Eleştiri hakaret sayılmaz.)" aria-label="Not">
            <div><button class="dugme ince kucuk-dugme">Kapat</button></div></form></details>
      </div>
      <p class="soluk kucuk">Yönetici içeriği kendisi gizleyemez ya da kaldıramaz; kararı oylama verir.</p>
    {% else %}
      <p class="soluk kucuk">{{ gr.kapanis|tarih }} · {{ kisi(gr.yonetici, resim=False) }}:
        {% if gr.durum == 'OYLAMADA' %}<a href="{{ url_for('oylamalar.teklif', teklif_id=gr.teklif_id) }}">#{{ gr.teklif_id }} numaralı oylama</a>{% else %}{{ gr.sonuc_notu }}{% endif %}</p>
    {% endif %}
  </section>
{% else %}
  <p class="kart bos-durum">{{ 'Sonuçlanan şikayet yok.' if kapali else 'Bekleyen şikayet yok.' }}</p>
{% endfor %}
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}Sistem · Yönetim{% endblock %}
{% block panel %}
<h1>Sistem</h1>

<section class="kart" id="ayarlar">
  <h2>{{ ikon('ayar') }} Site ayarları</h2>
  <form method="post" action="{{ url_for('yonetim.ayar') }}" class="form">{{ csrf() }}
    <label>Duyuru <small>Boş değilse her sayfanın üstünde görünür. En fazla 300 karakter.</small>
      <textarea name="duyuru" rows="2" maxlength="300" placeholder="ör. Cuma 22.00'de bakım yapılacak.">{{ duyuru }}</textarea></label>
    <fieldset><legend>Yeni üyelik</legend>
      <label class="secenek"><input type="radio" name="kayit_acik" value="1" {{ 'checked' if kayit_acik }}> <span><strong>Açık</strong><br><small>Herkes üye olabilir.</small></span></label>
      <label class="secenek"><input type="radio" name="kayit_acik" value="0" {{ 'checked' if not kayit_acik }}> <span><strong>Kapalı</strong><br><small>Üye ol sayfası yeni kayıt almaz; mevcut üyeler girebilir.</small></span></label>
    </fieldset>
    <div><button class="dugme">Kaydet</button></div>
  </form>
</section>

<div class="iki-sutun">
  <section class="kart" id="yz">
    <h2>{{ ikon('robot') }} Yapay zeka</h2>
    <p class="soluk kucuk">Yapay zeka hesapları yalnızca tartışmaları ve tur sonuçlarını kısaca özetler; oy kullanamaz.
      Uzman olabilmeleri için üyelerle aynı ön şartları sağlamaları ve oylanmaları gerekir.</p>
    {% for y in yz_hesaplari %}
      <p class="is-satiri"><a class="kisi" href="{{ url_for('yonetim.uye', kullanici_id=y.id) }}"><img class="avatar" src="{{ avatar(y.takma_ad, 1) }}" alt="">@{{ y.takma_ad }}</a>
        <span class="soluk kucuk">açılış {{ y.olusturma|gun }}</span></p>
    {% endfor %}
    {% if yz_hesaplari|length < ayarlar.MAX_YZ_HESABI %}
      <form method="post" action="{{ url_for('yonetim.yz_ekle') }}" class="satir-form">{{ csrf() }}
        <input name="takma_ad" required placeholder="Takma ad" aria-label="Yapay zeka takma adı"><button class="dugme ince">Hesap aç</button></form>
    {% endif %}
    <p class="soluk kucuk">En fazla {{ ayarlar.MAX_YZ_HESABI }} yapay zeka hesabı açılabilir.</p>
  </section>

  <section class="kart" id="yedek">
    <h2>{{ ikon('indir') }} Yedek</h2>
    <p class="soluk">Veritabanının o anki kopyasını indirir. Kişisel bilgiler de içinde olduğu için dosyayı güvenli bir yerde sakla.</p>
    <a class="dugme ince" href="{{ url_for('yonetim.yedek') }}">{{ ikon('indir') }} Yedek indir</a>
    <p class="soluk kucuk">Kayıt defterinin kopyaları sunucudaki <code>instance/defter</code> klasöründedir.</p>
  </section>
</div>

<section class="kart" id="defter">
  <h2>{{ ikon('zincir') }} Kayıt defteri</h2>
  <p class="{{ 'uyari basari' if defter_durumu.saglikli else 'uyari hata' }}">
    {% if defter_durumu.saglikli %}{{ ikon('tik') }} Bütün kopyalar aynı zincirde ({{ defter_durumu.uzunluk }} blok).
    {% else %}{{ ikon('uyari') }} Uyumsuz bir kopya var; aşağıdan onarabilirsin.{% endif %}</p>
  <div class="dugumler">
    {% for d in defter_durumu.dugumler %}
      <div class="kart dugum durum-{{ d.durum|lower }}">
        <h3>{{ ikon('sunucu') }} Kopya {{ d.ad }}</h3>
        <p><span class="rozet dugum-{{ d.durum|lower }}">{{ {'UYUMLU': 'Uyumlu', 'BOZUK': 'Bozuk', 'AYRISMIS': 'Farklı', 'AZINLIKTA': 'Azınlıkta'}[d.durum] }}</span>
          <span class="soluk kucuk">{{ d.uzunluk }} blok</span></p>
        <div class="eylem-satiri">
          {% if config.DEMO %}<form method="post" action="{{ url_for('yonetim.defter_deneme', ad=d.ad, islem='boz') }}">{{ csrf() }}
            <button class="dugme ince tehlike kucuk-dugme" data-onay="Deneme: {{ d.ad }} düğümündeki bir blok bozulsun mu?">Bozmayı dene</button></form>{% endif %}
          {% if d.durum != 'UYUMLU' %}<form method="post" action="{{ url_for('yonetim.defter_deneme', ad=d.ad, islem='onar') }}">{{ csrf() }}
            <button class="dugme kucuk-dugme">Onar</button></form>{% endif %}
        </div>
      </div>
    {% endfor %}
  </div>
  <p class="soluk kucuk">“Bozmayı dene”, sunumda sahteliğin nasıl yakalandığını göstermek içindir. Bir kopyadaki kaydı değiştirir; sayfa bunu hemen gösterir. “Onar” ise çoğunluğun kopyasını geri yazar.</p>
  {% if tutarlilik %}
    <h3>Veritabanı ile karşılaştırma</h3>
    {% if tutarlilik.sorunlar %}
      <ul>{% for s in tutarlilik.sorunlar %}<li>{{ s }}</li>{% endfor %}</ul>
    {% else %}<p class="uyari basari">{{ ikon('tik') }} {{ tutarlilik.mesaj }} mesaj, {{ tutarlilik.oylama }} oylama ve {{ tutarlilik.sonuc }} sonuç defterle uyuşuyor.</p>{% endif %}
  {% else %}
    <a class="dugme ince kucuk-dugme" href="{{ url_for('yonetim.sistem', denetle=1, _anchor='defter') }}">Veritabanıyla karşılaştır</a>
  {% endif %}
</section>
{% endblock %}

{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import csrf %}
{% block baslik %}@{{ k.takma_ad }} · Yönetim{% endblock %}
{% block panel %}
<p class="yol"><a href="{{ url_for('yonetim.uyeler') }}">Üyeler</a> › @{{ k.takma_ad }}</p>
<section class="kart profil-bas">
  <img class="avatar buyuk-avatar" src="{{ avatar(k.takma_ad, k.yz_mi) }}" alt="">
  <div>
    <h1>@{{ k.takma_ad }}
      {% if k.yonetici_mi %}<span class="rozet durum-karara_baglandi">Yönetici</span>{% endif %}
      {% if k.yz_mi %}<span class="rozet yz">Yapay zeka</span>{% endif %}
      {% if askida %}<span class="rozet durum-sonucsuz">Askıda</span>{% endif %}</h1>
    <p class="soluk">Üyelik {{ k.olusturma|gun }} · son giriş {{ k.son_giris|tarih if k.son_giris else 'hiç' }} ·
      <a href="{{ url_for('profil.kullanici', takma_ad=k.takma_ad) }}">herkese açık profil</a></p>
  </div>
</section>

<div class="stat-izgara dortlu kucuk-stat">
  <div class="stat"><span>Mesaj</span><strong>{{ ozet.mesaj }}</strong><small>{{ ozet.gizlenen }} gizlendi</small></div>
  <div class="stat"><span>Oy</span><strong>{{ ozet.oy }}</strong></div>
  <div class="stat"><span>Konu</span><strong>{{ ozet.konu }}</strong></div>
  <div class="stat"><span>Fikir</span><strong>{{ ozet.fikir }}</strong></div>
</div>

<div class="iki-sutun">
  <section class="kart">
    <h2>{{ ikon('kalkan') }} Yetki</h2>
    {% if k.id == kullanici.id %}
      <p class="soluk">Kendi yetkini değiştiremezsin; bunu başka bir yönetici yapabilir.</p>
    {% elif k.yz_mi %}
      <p class="soluk">Yapay zeka hesapları yönetici olamaz.</p>
    {% else %}
      <p class="soluk kucuk">Yönetici bu paneli görür: üyeleri askıya alır, şikayetlere bakar, kategorileri ve site ayarlarını değiştirir.
        İçerik silemez, uzman atayamaz, oylamaların süresine ve sonucuna dokunamaz.</p>
      <form method="post" action="{{ url_for('yonetim.yetki', kullanici_id=k.id) }}">{{ csrf() }}
        {% if k.yonetici_mi %}
          <input type="hidden" name="yonetici" value="0">
          <button class="dugme ince tehlike" data-onay="@{{ k.takma_ad }} yöneticilikten çıkarılsın mı?">Yöneticilikten çıkar</button>
        {% else %}
          <input type="hidden" name="yonetici" value="1">
          <button class="dugme" data-onay="@{{ k.takma_ad }} yönetici yapılsın mı? Yönetim paneline tam erişimi olacak.">Yönetici yap</button>
        {% endif %}
      </form>
    {% endif %}

    <h2>{{ ikon('duraklat') }} Askıya alma</h2>
    {% if askida %}
      <p>{{ k.askida_bitis|tarih }} tarihine kadar askıda.<br><span class="soluk kucuk">Neden: {{ k.askida_neden }}</span></p>
      <form method="post" action="{{ url_for('yonetim.aski_kaldir', kullanici_id=k.id) }}">{{ csrf() }}
        <button class="dugme ince">Askıyı kaldır</button></form>
    {% elif k.id == kullanici.id or k.yonetici_mi or k.yz_mi %}
      <p class="soluk kucuk">{% if k.yz_mi %}Yapay zeka hesapları askıya alınamaz.{% elif k.id == kullanici.id %}Kendini askıya alamazsın.{% else %}Önce yöneticilik yetkisini kaldırmalısın.{% endif %}</p>
    {% else %}
      <p class="soluk kucuk">Askıdaki üye siteyi okuyabilir ama mesaj yazamaz, oy veremez, konu açamaz. Verdiği oylar ve mesajları olduğu gibi kalır.
        Neden şeffaflık günlüğünde herkese görünür.</p>
      <form method="post" action="{{ url_for('yonetim.aski', kullanici_id=k.id) }}" class="form">{{ csrf() }}
        <label>Süre (gün) <input type="number" name="gun" value="7" min="1" max="{{ max_aski }}" required></label>
        <label>Neden <textarea name="neden" rows="2" minlength="10" maxlength="300" required placeholder="ör. Yönetmeliğin B1 maddesine aykırı, tekrarlanan kişisel saldırılar"></textarea></label>
        <button class="dugme ince tehlike" data-onay="@{{ k.takma_ad }} askıya alınsın mı?">Askıya al</button>
      </form>
    {% endif %}
  </section>

  <section class="kart">
    <h2>{{ ikon('makbuz') }} Uzmanlık</h2>
    {% for u in uzmanliklar %}
      <p class="is-satiri"><span>{{ u.kategori_id|kategori }}<br><span class="soluk kucuk">{{ u.baslangic|gun }} – {{ u.bitis|gun }}</span></span>
        <span class="rozet {{ 'durum-karara_baglandi' if u.id in aktif }}">{{ 'Aktif' if u.id in aktif else 'Sona erdi' }}</span></p>
    {% else %}<p class="soluk">Uzmanlığı yok.</p>{% endfor %}
    <p class="soluk kucuk">Uzmanlığı yönetici veremez ve geri alamaz. Üye ön şartları sağlayıp başvurur, alanın katılımcıları oylar;
      süre dolunca uzmanlık kendiliğinden biter.</p>
  </section>
</div>

{% if not k.yz_mi %}
<section class="kart">
