{% extends "yonetim/_kabuk.html" %}
{% from "_makrolar.html" import sayfa_gezgini %}
{% block baslik %}Üyeler · Yönetim{% endblock %}
{% block panel %}
<div class="sayfa-bas">
  <div><h1>Üyeler</h1><p class="soluk kucuk">{{ sayfalama.toplam }} kişi</p></div>
</div>
<form class="arac-cubugu" method="get">
  <input type="search" name="q" value="{{ q }}" placeholder="Takma ad ya da ad soyad" aria-label="Üye ara">
  <select name="filtre" aria-label="Süz">{% for d, ad in filtreler.items() %}<option value="{{ d }}" {{ 'selected' if filtre == d }}>{{ ad }}</option>{% endfor %}</select>
  <button class="dugme kucuk-dugme">Ara</button>
</form>
<section class="kart sifir-dolgu">
  <div class="tablo-kap"><table class="liste yonetim-tablosu">
    <thead><tr><th>Üye</th><th>Rol</th><th class="genis">Konum</th><th class="genis">Mesaj</th><th class="genis">Oy</th><th class="genis">Son giriş</th><th></th></tr></thead>
    {% for k in satirlar %}
      <tr>
        <td><a class="kisi" href="{{ url_for('yonetim.uye', kullanici_id=k.id) }}"><img class="avatar" src="{{ avatar(k.takma_ad, k.yz_mi) }}" alt="">@{{ k.takma_ad }}</a>
          {% if k.ad_soyad %}<br><span class="soluk kucuk">{{ k.ad_soyad }}</span>{% endif %}</td>
        <td>{% if k.yonetici_mi %}<span class="rozet durum-karara_baglandi">Yönetici</span>{% endif %}
            {% if k.yz_mi %}<span class="rozet yz">Yapay zeka</span>{% endif %}
            {% if k.uzmanlik %}<span class="rozet agirlik">Uzman</span>{% endif %}
            {% if k.askida_bitis and k.askida_bitis > simdi %}<span class="rozet durum-sonucsuz">Askıda</span>{% endif %}
            {% if not (k.yonetici_mi or k.yz_mi or k.uzmanlik) %}<span class="soluk kucuk">Üye</span>{% endif %}</td>
        <td class="kucuk genis">{{ k.konum_id|konum }}</td>
        <td class="genis">{{ k.mesaj_sayisi }}</td><td class="genis">{{ k.oy_sayisi }}</td>
        <td class="kucuk soluk genis">{{ k.son_giris|once if k.son_giris else '—' }}</td>
        <td><a class="dugme ince kucuk-dugme" href="{{ url_for('yonetim.uye', kullanici_id=k.id) }}">Yönet</a></td>
      </tr>
    {% else %}<tr><td colspan="7" class="bos-durum">Aramana uyan üye yok.</td></tr>{% endfor %}
  </table></div>
</section>
{{ sayfa_gezgini(sayfalama, 'yonetim.uyeler', request.args.to_dict()) }}
{% endblock %}

{% extends "base.html" %}
{% from "_makrolar.html" import csrf, teklif_durumu %}
{% block baslik %}Yönetmelik{% endblock %}
{% block icerik %}
<section class="kart">
  <h1>Yönetmelik</h1>
  <p>Forumun kuralları. Her kural üyelerin oylamasıyla değişebilir. Maddelerdeki sayılar aşağıdaki parametrelerden gelir;
    parametre değişince madde de güncellenir. Temel hak maddeleri ve korunan parametreler ancak {{ parametre('ESIK_TEMEL_HAK') }} ile değişir.</p>
</section>

{% for tur, ad, liste in gruplar if liste %}
<section class="kart">
  <h2>{{ ad }}</h2>
  {% for m in liste %}
    <article class="madde" id="{{ m.kod }}">
      <h3><span class="madde-kodu">{{ m.kod }}</span> {{ m.baslik }}
        {% if m.korunan %}<span class="rozet korunan">{{ ikon('kalkan') }} Korunan</span>{% endif %}
        {% if m.ciddiyet %}<span class="rozet ciddiyet-{{ m.ciddiyet|lower }}">{{ ciddiyetler[m.ciddiyet] }}</span>{% endif %}</h3>
      <p>{{ m.metin_goster }}</p>
      {% if m.degisme %}<p class="soluk kucuk">Son değişiklik: {{ m.degisme|tarih }}</p>{% endif %}
    </article>
  {% endfor %}
</section>
{% endfor %}

<section class="kart" id="parametreler">
  <h2>Parametreler</h2>
  <div class="tablo-kap"><table class="liste">
    <thead><tr><th>Parametre</th><th>Değer</th></tr></thead>
    {% for p in parametreler %}
      <tr><td>{{ p.aciklama }} <br><code class="kucuk">{{ p.kod }}</code> {% if p.korunan %}<span class="rozet korunan" title="Korunan">{{ ikon('kalkan') }}</span>{% endif %}</td>
          <td><strong>{{ parametre(p.kod) }}</strong>{% if p.degisme %}<br><small class="soluk">değişti: {{ p.degisme|gun }}</small>{% endif %}</td></tr>
    {% endfor %}
  </table></div>
</section>

<section class="kart" id="degisiklik">
  <h2>Değişiklik öner</h2>
  {% if kullanici and not kullanici.yz_mi %}
  <p class="soluk">Normal maddeler {{ parametre('ESIK_YONETMELIK') }}, korunanlar {{ parametre('ESIK_TEMEL_HAK') }} ister. Yönetmelik oylamasında her oy 1 sayılır; yapay zeka hesapları oy kullanamaz.</p>
  <div class="uc-sutun">
    <form method="post" action="{{ url_for('genel.yonetmelik_teklif') }}" class="form kutucuk">{{ csrf() }}
      <h3>Parametre</h3><input type="hidden" name="tur" value="PARAMETRE">
      <label>Parametre <select name="kod">{% for p in parametreler %}<option value="{{ p.kod }}">{{ p.aciklama }} ({{ p.deger }})</option>{% endfor %}</select></label>
      <label>Yeni değer <input name="yeni" required list="esik-kodlari" placeholder="ör. 0.3 · 72 · UCTE_IKI"></label>
      <datalist id="esik-kodlari">{% for kod, e in ayarlar.ESIKLER.items() %}<option value="{{ kod }}">{{ e.ad }}</option>{% endfor %}</datalist>
      <small class="soluk">Eşikler: SALT, BESTE_UC, UCTE_IKI, DORTTE_UC · oranlar 0–1 arası.</small>
      <label>Gerekçe <textarea name="gerekce" rows="3" minlength="20" required></textarea></label>
      <button class="dugme ince">Oylamaya sun</button>
    </form>
    <form method="post" action="{{ url_for('genel.yonetmelik_teklif') }}" class="form kutucuk">{{ csrf() }}
      <h3>Denetim maddesi</h3><input type="hidden" name="tur" value="DENETIM">
      <label>Madde <select name="madde">{% for m in denetim_maddeleri %}<option value="{{ m.kod }}">{{ m.kod }} {{ m.baslik }} ({{ ciddiyetler[m.ciddiyet] }})</option>{% endfor %}</select></label>
      <label>Yeni ciddiyet <select name="ciddiyet">{% for kod, ad in ciddiyetler.items() %}<option value="{{ kod }}">{{ ad }}</option>{% endfor %}</select></label>
      <label>Gerekçe <textarea name="gerekce" rows="3" minlength="20" required></textarea></label>
      <button class="dugme ince">Oylamaya sun</button>
    </form>
    <form method="post" action="{{ url_for('genel.yonetmelik_teklif') }}" class="form kutucuk">{{ csrf() }}
      <h3>Yeni beyan maddesi</h3><input type="hidden" name="tur" value="BEYAN">
      <label>Başlık <input name="baslik" required minlength="5" maxlength="80"></label>
      <label>Metin <textarea name="metin" rows="3" required minlength="20"></textarea></label>
      <label>Gerekçe <textarea name="gerekce" rows="2" minlength="20" required></textarea></label>
      <button class="dugme ince">Oylamaya sun</button>
    </form>
  </div>
  {% else %}<p class="soluk">Değişiklik önermek için üye olarak giriş yap.</p>{% endif %}

  <h3>Yönetmelik oylamaları</h3>
  <ul class="duz-liste">
    {% for t in teklifler %}<li><a href="{{ url_for('oylamalar.teklif', teklif_id=t.id) }}">{{ basliklar[t.id] }}</a> {{ teklif_durumu(t.durum) }}</li>
    {% else %}<li class="soluk">Henüz yok.</li>{% endfor %}
  </ul>
</section>
{% endblock %}

"""Kim hangi konuda katılımcı, kim gözlemci; kimin oyu kaç sayılır?

Temel kural: önce uygunluk, sonra ağırlık.
  1. Konunun konum/yaş kurallarını sağlamayan kişi gözlemcidir (okur, yazamaz, oy veremez).
  2. Uygun olan kişinin oyu 1 sayılır; konunun alanındaki uzmanın oyu UZMAN_AGIRLIK (varsayılan 10) sayılır.
  3. Uzmanlık ve yönetmelik oylamalarında herkesin oyu 1'dir.
  Yapay zeka hesapları oy kullanmaz.
"""
from dataclasses import dataclass, field
from datetime import date

from . import ontoloji, zaman


@dataclass
class Uygunluk:
    katilimci: bool
    puan: float                                   # 0–1, ontoloji tabanlı uygunluk ölçümü
    satirlar: list = field(default_factory=list)  # [(gecti_mi, açıklama), ...]

    @property
    def rol(self):
        return "Katılımcı" if self.katilimci else "Gözlemci"


@dataclass
class Baglam:
    """Bir oylamanın geçtiği ortam: hangi konu, hangi alan, uzman oyu kaç sayılır, kimler oy verebilir?"""
    konu: object
    kategori_id: object
    uzman_agirlik: int
    haric: set = field(default_factory=set)       # oy kullanamayacaklar (ör. uzmanlık adayı)
    esit_agirlik: bool = False                    # uzmanlık ve yönetmelik oylaması: herkes 1
    secmenler: object = None                      # None: herkes; küme: yalnızca bu üyeler (uzmanlıkta alanda yazanlar)


def yas(dogum_tarihi, bugun=None):
    bugun = bugun or zaman.simdi().date()
    d = date.fromisoformat(dogum_tarihi)
    return bugun.year - d.year - ((bugun.month, bugun.day) < (d.month, d.day))


def etkin_konum_id(kullanici, an=None):
    """Adres değişikliği bekleme süresinin ardından geçerli olur; süre dolmadıysa eski adres kullanılır."""
    bekleyen = kullanici["bekleyen_konum_id"]
    if bekleyen and kullanici["konum_gecerlilik"] <= zaman.metin(an or zaman.simdi()):
        return bekleyen
    return kullanici["konum_id"]


def konu_zinciri(db, konu):
    """Kök konudan bu konuya kadar olan konular (alt konu, üst konunun kurallarını miras alır)."""
    zincir = [konu]
    ust_id = konu["ust_id"]
    while ust_id:
        ust = db.execute("SELECT * FROM konular WHERE id = ?", (ust_id,)).fetchone()
        zincir.append(ust)
        ust_id = ust["ust_id"]
    return list(reversed(zincir))


def etkin_kurallar(db, konu):
    """Zincirdeki bütün kuralların birleşimi (VE): en dar konum, en dar yaş aralığı."""
    konum_id, min_yas, max_yas = None, None, None
    for k in konu_zinciri(db, konu):
        if k["konum_id"]:
            konum_id = k["konum_id"]
        if k["min_yas"] is not None:
            min_yas = k["min_yas"] if min_yas is None else max(min_yas, k["min_yas"])
        if k["max_yas"] is not None:
            max_yas = k["max_yas"] if max_yas is None else min(max_yas, k["max_yas"])
    return konum_id, min_yas, max_yas


def yas_araligi_metni(min_yas, max_yas):
    if min_yas is not None and max_yas is not None:
        return f"{min_yas}–{max_yas} yaş"
    if min_yas is not None:
        return f"{min_yas}+ yaş"
    return f"{max_yas} yaş ve altı"


def kural_metni(db, konu):
    konum_id, min_yas, max_yas = etkin_kurallar(db, konu)
    parcalar = []
    if konum_id:
        parcalar.append(f"{ontoloji.yol_metni(db, 'konumlar', konum_id)} sakinleri")
    if min_yas is not None or max_yas is not None:
        parcalar.append(yas_araligi_metni(min_yas, max_yas))
    return " · ".join(parcalar) if parcalar else "Herkese açık"


def uygunluk(db, kullanici, konu, an=None):
    if kullanici is None:
        return Uygunluk(False, 0.0, [(False, "Katılmak için giriş yapmalısın.")])
    if kullanici["yz_mi"]:
        return Uygunluk(False, 0.0, [(False, "Yapay zeka hesapları yalnızca özet yazar; oy kullanmaz.")])

    konum_id, min_yas, max_yas = etkin_kurallar(db, konu)
    satirlar, puanlar = [], []
    if konum_id:
        kullanici_konum = etkin_konum_id(kullanici, an)
        puan = ontoloji.benzerlik(db, "konumlar", kullanici_konum, konum_id)
        puanlar.append(puan)
        satirlar.append((
            puan == 1.0,
            f"Konumun {ontoloji.yol_metni(db, 'konumlar', kullanici_konum)}; konu "
            f"{ontoloji.yol_metni(db, 'konumlar', konum_id)} sakinlerine açık (uyum %{round(puan * 100)})",
        ))
    if min_yas is not None or max_yas is not None:
        y = yas(kullanici["dogum_tarihi"], (an or zaman.simdi()).date())
        gecti = (min_yas is None or y >= min_yas) and (max_yas is None or y <= max_yas)
        puanlar.append(1.0 if gecti else 0.0)
        satirlar.append((gecti, f"Yaşın {y}; konu {yas_araligi_metni(min_yas, max_yas)} için açık"))

    if not puanlar:
        return Uygunluk(True, 1.0, [(True, "Bu konu herkese açık.")])
    return Uygunluk(all(g for g, _ in satirlar), sum(puanlar) / len(puanlar), satirlar)


# --- Oylama bağlamı ve ağırlık ---

def alanda_yazanlar(db, kategori_id):
    """Bir alanın "niş kitlesi": o ana kategorideki (alt kategorileriyle) konulara en az bir mesaj yazmış insan üyeler."""
    kok = ontoloji.atalar(db, "kategoriler", kategori_id)[0]
    alan = set(ontoloji.alt_agac(db, "kategoriler", kok))
    return {r["yazar_id"] for r in db.execute(
        """SELECT DISTINCT m.yazar_id, k.kategori_id FROM mesajlar m JOIN konular k ON k.id = m.konu_id
           JOIN kullanicilar u ON u.id = m.yazar_id WHERE u.yz_mi = 0 AND k.silindi = 0""")
        if r["kategori_id"] in alan}


def konu_baglami(konu):
    return Baglam(konu, konu["kategori_id"], konu["bilirkisi_agirlik"])


def askida_mi(kullanici, an=None):
    return bool(kullanici and kullanici["askida_bitis"] and kullanici["askida_bitis"] > zaman.metin(an or zaman.simdi()))


def katilabilir_mi(db, kullanici, baglam, an=None):
    if kullanici is None:
        return False, "Oy vermek için giriş yapmalısın."
    if kullanici["yz_mi"]:
        return False, "Yapay zeka hesapları oy kullanmaz."
    if askida_mi(kullanici, an):              # askıdaki üye yeter sayıyı da şişirmesin
        return False, "Hesabın askıda; askı bitene kadar oy kullanamazsın."
    if kullanici["id"] in baglam.haric:
        return False, "Kendi uzmanlık oylamanda oy kullanamazsın."
    if baglam.secmenler is not None and kullanici["id"] not in baglam.secmenler:
        return False, "Bu oylamaya yalnızca bu alandaki konulara yazmış üyeler katılabilir."
    if baglam.konu is None:
        return True, ""
    u = uygunluk(db, kullanici, baglam.konu, an)
    return u.katilimci, ("" if u.katilimci else "Bu konuda gözlemcisin; oy hakkın yok.")


def aktif_uzmanlik(db, kullanici_id, kategori_id, an=None):
    """Kullanıcı bu kategoride (ya da üst kategorisinde) aktif uzman mı?"""
    simdi = zaman.metin(an or zaman.simdi())
    for u in db.execute(
        "SELECT * FROM uzmanliklar WHERE kullanici_id = ? AND baslangic <= ? AND bitis > ?",
        (kullanici_id, simdi, simdi),
    ):
        if ontoloji.altinda_mi(db, "kategoriler", kategori_id, u["kategori_id"]):
            return u
    return None


def oy_agirligi(db, kullanici, baglam, an=None):
    """(ağırlık, açıklama). Oy hakkı yoksa ağırlık 0."""
    uygun, neden = katilabilir_mi(db, kullanici, baglam, an)
    if not uygun:
        return 0, neden
    if baglam.esit_agirlik:
        return 1, "Bu oylamada herkes eşit"
    uzmanlik = aktif_uzmanlik(db, kullanici["id"], baglam.kategori_id, an)
    if uzmanlik:
        alan = ontoloji.yol_metni(db, "kategoriler", uzmanlik["kategori_id"])
        return baglam.uzman_agirlik, f"Uzman ({alan})"
    return 1, "Üye"


def oy_hakki_olanlar(db, baglam, an=None):
    kullanicilar = db.execute("SELECT * FROM kullanicilar").fetchall()
    return [k for k in kullanicilar if katilabilir_mi(db, k, baglam, an)[0]]

"""Uzmanlık: bir alanda oyu ağır sayılan üyeler.

Uzman olmanın üç adımı vardır:
  1. ÖN ŞART: aday o alanda yeterince yazmış olmalı (en az UZMAN_MIN_MESAJ mesaj, en az UZMAN_MIN_KONU farklı konu).
  2. KONTENJAN: bir ana kategoride en fazla UZMAN_KONTENJAN uzman olabilir; yer yoksa başvuru açılamaz.
     Böylece küçük bir grup birbirini sırayla uzman yapamaz.
  3. OYLAMA: başvuruyu o alanın "niş kitlesi" (o ana kategorideki konulara yazmış üyeler) oylar.
     Herkesin oyu 1 sayılır, aday oy kullanamaz; kabul için ESIK_UZMANLIK gerekir.
Yönetici uzman atayamaz. Yapay zeka hesapları da aynı şartlarla, bir üyenin aday göstermesiyle uzman olabilir.
"""
from datetime import timedelta

from . import bildirimler, defter, denetim, gunluk, ontoloji, oylama, uygunluk, yonetmelik, zaman
from .hatalar import KuralHatasi


def uzmanliklar(db, kullanici_id, sadece_aktif=True):
    sorgu, parametreler = "SELECT * FROM uzmanliklar WHERE kullanici_id = ?", [kullanici_id]
    if sadece_aktif:
        sorgu += " AND baslangic <= ? AND bitis > ?"
        parametreler += [zaman.simdi_metin()] * 2
    return db.execute(sorgu + " ORDER BY id", parametreler).fetchall()


def _kok(db, kategori_id):
    return ontoloji.atalar(db, "kategoriler", kategori_id)[0]


def alan_uzmanlari(db, kategori_id):
    """Bir ana kategorideki (alt kategorileriyle) aktif uzmanların id'leri."""
    alan = set(ontoloji.alt_agac(db, "kategoriler", _kok(db, kategori_id)))
    simdi = zaman.simdi_metin()
    return {r["kullanici_id"] for r in db.execute(
        "SELECT kullanici_id, kategori_id FROM uzmanliklar WHERE baslangic <= ? AND bitis > ?", (simdi, simdi))
        if r["kategori_id"] in alan}


def kontenjan(db, kategori_id):
    dolu, toplam = len(alan_uzmanlari(db, kategori_id)), yonetmelik.deger(db, "UZMAN_KONTENJAN")
    return {"dolu": dolu, "toplam": toplam, "yer_var": dolu < toplam,
            "alan": ontoloji.ad(db, "kategoriler", _kok(db, kategori_id))}


def on_sartlar(db, kullanici_id, kategori_id):
    """Adayın o alandaki (seçilen kategori ve alt kategorileri) etkinliği ön şartları sağlıyor mu?"""
    alan = set(ontoloji.alt_agac(db, "kategoriler", kategori_id))
    mesaj, konular_ = 0, set()
    for r in db.execute("""SELECT m.konu_id, k.kategori_id FROM mesajlar m JOIN konular k ON k.id = m.konu_id
                           WHERE m.yazar_id = ? AND m.gizli = 0 AND k.silindi = 0""", (kullanici_id,)):
        if r["kategori_id"] in alan:
            mesaj += 1
            konular_.add(r["konu_id"])
    gereken_mesaj, gereken_konu = yonetmelik.deger(db, "UZMAN_MIN_MESAJ"), yonetmelik.deger(db, "UZMAN_MIN_KONU")
    return {"mesaj": mesaj, "konu": len(konular_), "gereken_mesaj": gereken_mesaj, "gereken_konu": gereken_konu,
            "tamam": mesaj >= gereken_mesaj and len(konular_) >= gereken_konu}


def basvur(db, basvuran, kategori_id, gerekce, aday_id=None):
    """Üye kendisi için başvurur; aday_id verilirse bir yapay zeka hesabını aday gösterir."""
    if basvuran["yz_mi"]:
        raise KuralHatasi("Yapay zeka hesapları başvuru açamaz; bir üye aday gösterebilir.")
    aday = basvuran
    if aday_id and aday_id != basvuran["id"]:
        aday = db.execute("SELECT * FROM kullanicilar WHERE id = ?", (aday_id,)).fetchone()
        if not aday or not aday["yz_mi"]:
            raise KuralHatasi("Yalnızca yapay zeka hesapları aday gösterilebilir; üyeler kendileri başvurur.")
    try:
        kategori_id = int(kategori_id)
    except (TypeError, ValueError):
        raise KuralHatasi("Alan seç.")
    if not ontoloji.dugum(db, "kategoriler", kategori_id):
        raise KuralHatasi("Alan bulunamadı.")
    if uygunluk.aktif_uzmanlik(db, aday["id"], kategori_id):
        raise KuralHatasi("Bu alanda zaten uzmanlık var.")
    if oylama.acik_teklif(db, "UZMANLIK", hedef_id=aday["id"]):
        raise KuralHatasi("Zaten süren bir uzmanlık oylaması var.")
    sart = on_sartlar(db, aday["id"], kategori_id)
    if not sart["tamam"]:
        raise KuralHatasi(f"Ön şartlar sağlanmıyor: bu alanda en az {sart['gereken_mesaj']} mesaj ve "
                          f"{sart['gereken_konu']} farklı konu gerekir (şu an {sart['mesaj']} mesaj, {sart['konu']} konu).")
    yer = kontenjan(db, kategori_id)
    if not yer["yer_var"]:
        raise KuralHatasi(f"{yer['alan']} alanında uzman kontenjanı dolu ({yer['dolu']}/{yer['toplam']}). "
                          "Bir uzmanlığın süresi dolunca yer açılır.")
    gerekce = (gerekce or "").strip()
    if len(gerekce) < 20:
        raise KuralHatasi("Gerekçeye eğitimi, deneyimi ya da alandaki katkıyı yaz (en az 20 karakter).")
    denetim.mesaj_denetle(db, gerekce)
    return oylama.teklif_ac(db, "UZMANLIK", basvuran["id"], hedef_id=aday["id"], gerekce=gerekce,
                            veri={"kategori_id": kategori_id})


def uzmanlik_ver(db, kullanici_id, kategori_id):
    """Oylama kabul edince çağrılır. Kontenjan o arada dolduysa uzmanlık verilmez."""
    k = db.execute("SELECT * FROM kullanicilar WHERE id = ?", (kullanici_id,)).fetchone()
    alan = ontoloji.yol_metni(db, "kategoriler", kategori_id)
    if not k or uygunluk.aktif_uzmanlik(db, kullanici_id, kategori_id):
        return False
    if not kontenjan(db, kategori_id)["yer_var"]:
        bildirimler.gonder(db, kullanici_id, f"Başvurun kabul edildi ama {alan} alanında kontenjan doldu; "
                                             "uzmanlık verilemedi.", "/profil/uzmanlik")
        return False
    gun = yonetmelik.deger(db, "UZMAN_SURE_GUN")
    an = zaman.simdi()
    db.execute("INSERT INTO uzmanliklar (kullanici_id, kategori_id, baslangic, bitis, kaynak) VALUES (?, ?, ?, ?, 'TOPLULUK')",
               (kullanici_id, kategori_id, zaman.metin(an), zaman.metin(an + timedelta(days=gun))))
    gunluk.kaydet(db, kullanici_id, "UZMANLIK", f"@{k['takma_ad']} {alan} alanında uzman oldu ({gun} gün)")
    defter.ekle(db, "UZMANLIK", {"yurttas": k["takma_ad"], "alan": alan, "gun": gun})
    bildirimler.gonder(db, kullanici_id, f"{alan} alanında uzman oldun. Bu alandaki fikir oylamalarında oyun ağır "
                                         "sayılır ve gerekçe yazman gerekir.", f"/kullanici/{k['takma_ad']}")
    return True

"""Web katmanı: iş mantığı modüllerini (forum/*.py) HTTP'ye bağlar.

Modüller: istek.py (istek öncesi zincir: kimlik, askı, CSRF, zamanlayıcı), hata_sayfalari.py, sablon.py (şablon
filtreleri ve bağlamı) ve alan başına blueprint'ler (hesap, konu_sayfalari, oylama_sayfalari, profil, genel,
yonetim_sayfalari, api). Bu dosyada yalnızca blueprint'lerin ortak kullandığı küçük yardımcılar vardır.

Kimlik doğrulama iki yoldan olur:
  * Tarayıcı: imzalı oturum çerezi + her POST'ta CSRF anahtarı. Yönetim paneli (/yonetim) üye oturumunu değil, ayrı
    yönetici girişiyle açılan yönetici oturumunu kullanır.
  * Uygulama (API): `Authorization: Bearer <anahtar>` başlığı (CSRF gerekmez, çerez kullanılmaz).
"""
import secrets
from functools import wraps

from flask import abort, current_app, flash, g, jsonify, redirect, request, session, url_for

from .. import veritabani


def db_al():
    if "db" not in g:
        g.db = veritabani.baglan(current_app.config["VERITABANI"])
    return g.db


def giris_gerekli(f):
    @wraps(f)
    def sarici(*args, **kwargs):
        if g.kullanici is None:
            if g.get("api"):
                return jsonify(hata="Kimlik doğrulaması gerekli."), 401
            flash("Bu işlem için giriş yapmalısın.", "hata")
            # Girişten sonra yalnızca GET sayfasına dönülür; POST adresi 405 verir.
            return redirect(url_for("hesap.giris", sonra=request.path if request.method == "GET" else None))
        return f(*args, **kwargs)
    return sarici


def yonetici_gerekli(f):
    """Yönetim paneli üye girişinden ayrı bir oturumla açılır (bkz. istek.kimlik). Oturum yoksa yönetici girişine
    yönlendirilir."""
    @wraps(f)
    def sarici(*args, **kwargs):
        if g.kullanici is None:
            if request.method == "GET":
                return redirect(url_for("yonetim.giris", sonra=request.full_path.rstrip("?")))
            abort(403)
        if not g.kullanici["yonetici_mi"]:
            abort(403)
        return f(*args, **kwargs)
    return sarici


UYE_OTURUMU = ("kullanici_id", "surum")
YONETICI_OTURUMU = ("yonetici_id", "yonetici_surum")


def oturumu_kapat(anahtarlar):
    """Üye ve yönetici oturumları aynı çerezde ama birbirinden bağımsızdır; biri kapanınca öteki sürer."""
    for anahtar in anahtarlar:
        session.pop(anahtar, None)


def csrf_token():
    if "csrf" not in session:
        session["csrf"] = secrets.token_hex(16)
    return session["csrf"]


def sayfa_no():
    """Sayfa numarası 1 ile 100.000 arasında tutulur; çok büyük sayılar sorguda taşmaya (500) yol açar."""
    return min(max(request.args.get("sayfa", 1, type=int), 1), 100_000)


def kur(app):
    """Web katmanını uygulamaya bağlar. Her parça kendi modülündedir (tek sorumluluk)."""
    from . import api, genel, hata_sayfalari, hesap, istek, konu_sayfalari, oylama_sayfalari, profil, sablon, \
        yonetim_sayfalari
    istek.kur(app)              # istek öncesi zincir, güvenlik başlıkları, bağlantı kapatma
    hata_sayfalari.kur(app)     # KuralHatasi ve HTTP hataları → sayfa ya da JSON
    sablon.kur(app)             # şablon değişkenleri ve filtreleri
    for modul in (hesap, konu_sayfalari, oylama_sayfalari, profil, genel, yonetim_sayfalari, api):
        app.register_blueprint(modul.bp)

"""REST API (v1) — mobil uygulama ve dış istemciler için.

Kimlik doğrulama: POST /api/v1/giris ile alınan anahtar `Authorization: Bearer <anahtar>` başlığıyla gönderilir.
Tarayıcıdan (oturum çereziyle) yapılan POST isteklerinde `X-CSRF-Token` başlığı gerekir.
Kişisel veriler (ad, doğum tarihi, adres) API'de hiçbir zaman döndürülmez.
"""
import json

from flask import Blueprint, g, jsonify, request

from .. import (anlik, arama, ayarlar, bildirimler, gundem, kategoriler, defter, graf, guvenlik, kararlar, konular, kullanicilar,
                ontoloji, oylama, uygunluk, yonetmelik)
from ..denetim import mesaj_uyarilari
from . import db_al, giris_gerekli

bp = Blueprint("api", __name__, url_prefix="/api/v1")


def _veri():
    """İstek gövdesi: JSON nesnesi ya da form verisi. Sayı ve mantıksal alanlar metne çevrilir, çünkü iş katmanı
    metin bekler."""
    veri = request.get_json(silent=True)
    if not isinstance(veri, dict):
        veri = request.form.to_dict()
    return {k: str(v) if isinstance(v, (int, float, bool)) else v for k, v in veri.items()}


def _yurttas(k):
    if not k:
        return None
    return {"takma_ad": k["takma_ad"], "yz": bool(k["yz_mi"]), "yonetici": bool(k["yonetici_mi"])}


def _konu(db, k, detay=False):
    d = {"id": k["id"], "ust_id": k["ust_id"], "baslik": k["baslik"], "durum": k["durum"],
         "durum_adi": ayarlar.KONU_DURUMLARI[k["durum"]], "kategori": ontoloji.yol_metni(db, "kategoriler", k["kategori_id"]),
         "katilim_kurali": uygunluk.kural_metni(db, k), "tur": k["tur"], "tartisma_bitis": k["tartisma_bitis"],
         "itiraz_id": k["itiraz_id"], "uzman_agirlik": k["bilirkisi_agirlik"], "olusturma": k["olusturma"]}
    if detay:
        u = uygunluk.uygunluk(db, g.kullanici, k)
        d.update(aciklama=k["aciklama"], denetim=json.loads(k["denetim"]) if k["denetim"] else None,
                 rolum="KATILIMCI" if u.katilimci else "GOZLEMCI", uygunluk_puani=round(u.puan, 2))
    return d


def _teklif(db, t):
    d = {"id": t["id"], "tip": t["tip"], "baslik": oylama.teklif_basligi(db, t), "durum": t["durum"], "esik": t["esik"],
         "konu_id": t["konu_id"], "tur": t["tur_no"], "baslangic": t["baslangic"], "bitis": t["bitis"]}
    d["secenekler"] = [{"id": a, "metin": m} for a, m, _ in oylama.turu(t).secenekler(db, t)]
    if t["durum"] != "ACIK" and t["sonuc"]:
        s = json.loads(t["sonuc"])
        d["sonuc"] = {k: s.get(k) for k in ("secenekler", "cekimser", "agirlik_oran", "kisi_oran", "yeter", "katilan",
                                            "hak_sahibi", "acik_oylar")}
    if g.kullanici:
        durum = oylama.oy_durumu(db, t, g.kullanici)
        d["benim"] = {"verebilir": durum["verebilir"], "agirlik": durum["agirlik"], "aciklama": durum["aciklama"],
                      "oy_verdim": durum["oy"] is not None}
    return d


@bp.get("")
