"""Şablonların kullandığı genel değişkenler, bağlam ve filtreler.

Saf filtreler (tarih, gün, kalan süre, göreli zaman) modül düzeyinde fonksiyonlardır; Flask olmadan test edilebilir.
Filtreler FILTRELER sözlüğünden kaydedilir."""
from flask import g, request

from .. import ayarlar, bildirimler, konular, ontoloji, oylama, sikayetler, uygunluk, yonetim, yonetmelik, zaman
from ..konu_durumlari import durumu
from ..metin import yuzde
from . import csrf_token, db_al, ikonlar, yardimcilar


def tarih(deger):
    return zaman.coz(deger).strftime("%d.%m.%Y %H:%M") if deger else ""


def gun(deger):
    return zaman.coz(deger).strftime("%d.%m.%Y") if deger else ""


def kalan(deger):
    fark = zaman.coz(deger) - zaman.simdi()
    if fark.total_seconds() <= 0:
        return "süresi doldu"
    saat, dakika = fark.seconds // 3600, (fark.seconds % 3600) // 60
    if fark.days:
        return f"{fark.days} gün {saat} saat kaldı"
    return f"{saat} saat {dakika} dk kaldı" if saat else f"{dakika} dk kaldı"


def once(deger):
    """Göreli zaman: "az önce", "5 dk önce", "3 saat önce", "2 gün önce"."""
    if not deger:
        return ""
    saniye = (zaman.simdi() - zaman.coz(deger)).total_seconds()
    if saniye < 60:
        return "az önce"
    if saniye < 3600:
        return f"{int(saniye // 60)} dk önce"
    if saniye < 86400:
        return f"{int(saniye // 3600)} saat önce"
    if saniye < 30 * 86400:
        return f"{int(saniye // 86400)} gün önce"
    return zaman.coz(deger).strftime("%d.%m.%Y")


def kategori_rengi(kategori_id):
    return ontoloji.kategori_rengi(db_al(), kategori_id) if kategori_id else ayarlar.VARSAYILAN_KATEGORI_RENGI


def konum(konum_id):
    return ontoloji.yol_metni(db_al(), "konumlar", konum_id) if konum_id else "—"


def kategori(kategori_id):
    return ontoloji.yol_metni(db_al(), "kategoriler", kategori_id) if kategori_id else "—"


def bicimle(metin):
    return yardimcilar.bicimle(metin, request.script_root)


def site_yolu(yol):
    """Veritabanında saklanan uygulama içi yolu ("/konu/3") bağlantıya çevirir; uygulama bir alt yolda çalışıyorsa
    (GitHub Pages) önek eklenir, yoksa tarayıcı sitenin köküne gider."""
    return request.script_root + yol if yol and yol.startswith("/") and not yol.startswith("//") else yol


FILTRELER = {"tarih": tarih, "gun": gun, "kalan": kalan, "once": once, "kategori_rengi": kategori_rengi,
             "yuzde": yuzde, "konum": konum, "kategori": kategori, "bicimle": bicimle, "site_yolu": site_yolu}


def sablon_degiskenleri():
    k = getattr(g, "kullanici", None)
    db = db_al()
    ortak = {"yan_kategoriler": konular.kategori_ozeti(db), "site_duyurusu": yonetim.site_ayari(db, "duyuru"),
             "mobil_uygulama": ayarlar.MOBIL_UA in request.headers.get("User-Agent", "")}
    if not k:
        return dict(ortak, kullanici=None, bekleyen_oy=0, okunmamis=0, askida=False, acik_sikayet=0)
    return dict(ortak, kullanici=k, bekleyen_oy=oylama.bekleyen_oy_sayisi(db, k),
                okunmamis=bildirimler.okunmamis_sayisi(db, k["id"]), askida=uygunluk.askida_mi(k),
                acik_sikayet=sikayetler.acik_sayisi(db) if k["yonetici_mi"] else 0)


def kur(app):
    app.jinja_env.globals.update(ayarlar=ayarlar, csrf_token=csrf_token, avatar=yardimcilar.avatar, ikon=ikonlar.ikon,
                                 durum_nesnesi=durumu,
                                 parametre=lambda kod: yonetmelik.parametre_metni(db_al(), kod))
    app.context_processor(sablon_degiskenleri)
    for ad, filtre in FILTRELER.items():
        app.add_template_filter(filtre, ad)

"""Şablon yardımcıları: güvenli metin biçimlendirme, avatar, sayfalama."""
import hashlib
import math
import re
from base64 import b64encode

from markupsafe import Markup, escape

from ..ayarlar import GRI, TAS_BEYAZI, YESIL

_URL = re.compile(r"(https?://[^\s<]+)")
_BAHSETME = re.compile(r"(?<![\w/])@([A-Za-z0-9_.çğıöşüÇĞİÖŞÜ]{3,30})")
_KALIN = re.compile(r"\*\*(.+?)\*\*")


def bicimle(metin, kok=""):
    """Önce HTML kaçışı, sonra güvenli biçimler: bağlantı, @bahsetme, **kalın**. Satır sonları CSS ile korunur.
    `kok`, uygulama bir alt yolda çalışıyorsa (GitHub Pages) bahsetme bağlantılarının önüne eklenir."""
    if not metin:
        return ""
    e = str(escape(metin))
    parcalar = _URL.split(e)
    for i, p in enumerate(parcalar):
        if i % 2:   # URL
            parcalar[i] = f'<a href="{p}" rel="nofollow noopener noreferrer" target="_blank">{p}</a>'
        else:
            p = _BAHSETME.sub(rf'<a class="bahsetme" href="{kok}/kullanici/\1">@\1</a>', p)
            parcalar[i] = _KALIN.sub(r"<strong>\1</strong>", p)
    return Markup("".join(parcalar))


# Avatar zemin/desen çiftleri: sadece paletteki renkler (taş beyazı, yeşil, gri)
AVATAR_CIFTLERI = [(YESIL[200], YESIL[700]), (TAS_BEYAZI[200], GRI[700]), (YESIL[600], TAS_BEYAZI[50]),
                   (GRI[300], YESIL[800]), (YESIL[100], YESIL[600]), (YESIL[800], YESIL[200])]


def avatar(takma_ad, yz_mi=False):
    """Takma addan türetilen simetrik desen (identicon) — veri URI'si olarak SVG."""
    h = hashlib.sha256((takma_ad or "?").encode()).digest()
    if yz_mi:
        svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"><rect width="10" height="10" rx="2" '
               f'fill="{YESIL[700]}"/><text x="5" y="6.8" font-size="4.2" text-anchor="middle" fill="{TAS_BEYAZI[50]}" '
               'font-family="sans-serif" font-weight="bold">YZ</text></svg>')
    else:
        zemin, renk = AVATAR_CIFTLERI[h[0] % len(AVATAR_CIFTLERI)]
        kareler = []
        for y in range(5):
            for x in range(3):
                if h[1 + y * 3 + x] % 2:
                    for xx in {x, 4 - x}:
                        kareler.append(f'<rect x="{xx * 2}" y="{y * 2}" width="2" height="2" fill="{renk}"/>')
        svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"><rect width="10" height="10" rx="2" '
               f'fill="{zemin}"/>{"".join(kareler)}</svg>')
    return "data:image/svg+xml;base64," + b64encode(svg.encode()).decode()


def sayfala(liste, sayfa, boy):
    toplam = len(liste)
    sayfa_sayisi = max(1, math.ceil(toplam / boy))
    sayfa = min(max(1, sayfa), sayfa_sayisi)
    return liste[(sayfa - 1) * boy: sayfa * boy], {"sayfa": sayfa, "sayfa_sayisi": sayfa_sayisi, "toplam": toplam}


def sayfa_bilgisi(toplam, sayfa, boy):
    sayfa_sayisi = max(1, math.ceil(toplam / boy))
    return {"sayfa": min(max(1, sayfa), sayfa_sayisi), "sayfa_sayisi": sayfa_sayisi, "toplam": toplam}

"""Yönetim paneli (/yonetim). Yalnızca yöneticiler görür; üye girişinden ayrı, kendi giriş sayfası (/yonetim/giris)
ve oturumu vardır.

Yönetici yalnızca siteyi yönetir: yetki, askı, kategoriler, şikayet kutusu, duyurular, site ayarları, yedek.
Kararları etkileyemez: uzman atayamaz, oylama sonuçlandıramaz, süre değiştiremez. Tek istisna sunum içindir:
sunucu --demo ile başlatılırsa "süreyi ilerlet" düğmeleri görünür (her kullanımı günlüğe yazılır).
"""
from flask import Blueprint, Response, current_app, flash, g, redirect, render_template, request, session, url_for

